}

/**
 * SiteSwitcher — header dropdown for multi-site Pulse Pro tenants
 * (Iter 216i).
 *
 * Behaviour:
 *   • Shown only when the org has ≥2 sites.
 *   • Lists every site + an "All sites" pseudo-entry that flips the
 *     dashboard into the multi-site overview (consumed by the parent
 *     via `onAllSites`).
 *   • Active site is sourced from the auth context (`activeSite`) and
 *     written back via `setActiveSite`. Persisted in localStorage by the
 *     parent so the choice survives reloads.
 *   • Pure presentational — no API calls; the sites list is whatever
 *     the auth context already loaded.
 */
import { useState, useRef, useEffect } from 'react';
import { ChevronDown, MapPin, Star, Globe2, Check } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '@/App';

const SiteSwitcher = ({ onAllSites, onPickSite, allSitesActive = false }) => {
  const { t } = useTranslation();
  const { sites, activeSite, setActiveSite, allSitesMode, enableAllSites } = useAuth();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // Hide the switcher entirely for single-site tenants — there's nothing
  // to switch to. The parent header still renders the company name.
  if (!sites || sites.length < 2) return null;

  // Effective "all sites" mode: either the parent controls it
  // (Operations) or the global isolation mode from the auth context.
  const allActive = allSitesActive || (allSitesMode && !activeSite);
  // When in global all-mode but a site is still cached for label, prefer
  // showing "All sites" if the context flag is set and parent isn't driving.
  const showAll = allSitesActive || allSitesMode;

  const label = showAll
    ? t('sites.all_sites', 'All Sites')
    : (activeSite?.name || t('sites.pick_site', 'Pick a site'));

  const handleAllSites = () => {
    if (onAllSites) onAllSites();
    else enableAllSites();
    setOpen(false);
  };

  /**
   * Iter 216bk — picking a specific site after the org was in "All sites"
   * mode used to leave `allSitesActive=true` on the parent, so the
   * dashboard stayed on the estate-wide overview and the click looked
   * dead. The new `onPickSite` callback lets the parent flip it back
   * to false. We still call `setActiveSite` (which the auth context
   * persists to localStorage) so the choice survives a reload.
   */
  const handlePickSite = (site) => {
    setActiveSite(site);
    if (onPickSite) onPickSite(site);
    setOpen(false);
  };

  return (
    <div ref={ref} className="relative" data-testid="site-switcher">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors"
        style={{
          background: 'var(--theme-surface)',
          borderColor: 'var(--theme-border)',
          color: 'var(--theme-text)',
        }}
        data-testid="site-switcher-trigger"
      >
        {showAll ? <Globe2 size={13} /> : <MapPin size={13} className="text-[var(--color-brand-blue)]" />}
        <span className="max-w-[180px] truncate">{label}</span>
        <ChevronDown size={12} className="opacity-60" />
      </button>
      {open && (
        <div
          /* Iter 216bk — dropdown is now viewport-safe. On mobile (<640px)
             we anchor to the left edge of the trigger so the menu opens
             rightward and never clips off the left. On sm+ we keep the
             original right-aligned behaviour. Width caps at the viewport
             minus a 16px gutter so portrait phones never overflow. */
          className="absolute left-0 sm:left-auto sm:right-0 mt-2 rounded-lg shadow-xl z-30 overflow-hidden"
          style={{
            background: 'var(--theme-surface)',
            border: '1px solid var(--theme-border)',
            width: 'min(18rem, calc(100vw - 2rem))',
          }}
          data-testid="site-switcher-menu"
        >
          <div className="px-3 py-2 text-[10px] uppercase tracking-wider font-bold" style={{ color: 'var(--theme-text-muted)' }}>
            {t('sites.switch_site', 'Switch site')}
          </div>
          {/* All-sites aggregate — always available so users can return to
              the estate-wide / "all my sites" view from any module. */}
          <button
            type="button"
            onClick={handleAllSites}
            className="w-full flex items-center gap-2 px-3 py-2 text-sm text-left hover:bg-[var(--theme-hover-bg)]"
            style={{ color: 'var(--theme-text)' }}
            data-testid="site-switcher-all"
          >
            <Globe2 size={14} className="text-[var(--color-brand-blue)]" />
            <span className="flex-1 font-semibold">{t('sites.all_sites', 'All Sites')}</span>
            <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-[rgb(var(--rgb-brand-blue)/0.12)] text-[var(--color-brand-blue)] font-bold">overview</span>
            {showAll ? <Check size={14} className="text-emerald-500" /> : null}
          </button>
          <div className="border-t" style={{ borderColor: 'var(--theme-border-soft)' }} />
          <ul className="max-h-72 overflow-y-auto" data-testid="site-switcher-list">
            {sites.map((s) => {
              const active = !showAll && activeSite?.id === s.id;
              return (
                <li key={s.id}>
                  <button
                    type="button"
                    onClick={() => handlePickSite(s)}
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-left hover:bg-[var(--theme-hover-bg)]"
                    style={{ color: 'var(--theme-text)' }}
                    data-testid={`site-switcher-item-${s.id}`}
                  >
                    {s.is_head_office
                      ? <Star size={13} className="text-amber-500 shrink-0" />
                      : <MapPin size={13} className="text-[var(--theme-text-muted)] shrink-0" />}
                    <span className="flex-1 truncate">{s.name}</span>
                    {s.equipment_count != null
                      ? <span className="text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>{s.equipment_count} eq</span>
                      : null}
                    {active ? <Check size={14} className="text-emerald-500" /> : null}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
};

export default SiteSwitcher;

import { useEffect, useState, useCallback } from 'react';
import { bfpo, uploadFile, pendingStatusFor, onOutboxChange, outboxCount } from '../bfpoApi';
import { Card, Btn, Badge, Spinner, PriorityBadge, STATUS_LABEL, Field, inputCls, localTime } from '../ui';
import SignOffFields, { signoffBody } from './SignOffFields';
import MissingAssetDetails from './MissingAssetDetails';
import { EngineerReportFields, withReportDefaults, reportTimeError } from '@/components/shared/EngineerReportFields';
import { EngineerReportView } from '@/components/shared/EngineerReportView';
import {
  ChevronLeft, AlertTriangle, MapPin, Wrench, ShieldCheck, ShieldAlert, Package,
  RotateCcw, Ban, PlusCircle, Camera, CheckCircle2, FileText, History, Loader2,
} from 'lucide-react';

const OPEN = ['new', 'triaged', 'assigned', 'en_route', 'on_site', 'paused_parts', 'paused_customer', 'repaired', 'awaiting_sign_off'];

export default function JobDetail({ jobId, onBack, onOpenJob }) {
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(true);
  const [panel, setPanel] = useState(null); // arrive | workflow | parts | outcome:X | report | complete
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState('');

  const load = useCallback(async () => {
    try {
      const r = await bfpo.get(`/jobs/${jobId}`);
      setJob({ ...r.data, status: pendingStatusFor(jobId, r.data.status) });
    } catch { /* offline and not cached — keep what we have */ }
    setLoading(false);
  }, [jobId]);
  useEffect(() => { load(); }, [load]);
  // Saved offline updates just went out → show the server's latest state.
  useEffect(() => { let prev = outboxCount(); return onOutboxChange((n) => { if (n < prev) load(); prev = n; }); }, [load]);

  const flash = (m) => { setToast(m); setTimeout(() => setToast(''), 2500); };
  const act = async (fn, msg) => {
    setBusy(true);
    try { const r = await fn(); if (r?.data?.queued) { setJob((j) => (j ? { ...j, status: pendingStatusFor(jobId, j.status) } : j)); flash('No signal — saved on this phone, it will send automatically'); setPanel(null); return; } await load(); if (msg) flash(msg); setPanel(null); }
    catch (e) { flash(e?.response?.data?.detail || 'Could not save — your work is stored, we will retry.'); }
    finally { setBusy(false); }
  };

  if (loading) return <Spinner />;
  if (!job) return null;
  const status = job.status;
  const isOpen = OPEN.includes(status);

  const primary = () => {
    if (!isOpen) return null;
    if (['new', 'triaged'].includes(status)) return { label: 'Accept Job', onClick: () => act(() => bfpo.post(`/jobs/${jobId}/accept`, {}), 'Job accepted') };
    if (['assigned', 'en_route'].includes(status)) return { label: "I'm on site — Start Job", onClick: () => setPanel('arrive') };
    if (status === 'paused_parts') return { label: 'Continue Job', onClick: () => setPanel('workflow') };
    if (job.return_visit) return { label: 'Continue — Return Visit', onClick: () => setPanel('workflow') };
    return { label: 'Update Job', onClick: () => setPanel('workflow') };
  };
  const pa = primary();

  return (
    <div className="pb-28 max-w-2xl mx-auto" data-testid="engineer-jobdetail">
      <div className="sticky top-0 z-10 bg-white border-b border-slate-200 px-4 py-3 flex items-center gap-3">
        <button onClick={onBack} data-testid="jobdetail-back" className="p-1 -ml-1"><ChevronLeft className="w-6 h-6 text-slate-600" /></button>
        <div className="min-w-0">
          <p className="font-bold text-slate-900 truncate">{job.reference}</p>
          <p className="text-xs text-slate-500">{STATUS_LABEL[status] || status}</p>
        </div>
      </div>

      <div className="p-4 space-y-4">
        <div className="flex items-center gap-2 flex-wrap">
          <PriorityBadge p={job.priority} testid="jobdetail-priority" />
          {job.safety_critical && <Badge className="bg-red-100 text-red-700 border-red-200"><AlertTriangle className="w-3 h-3" /> Safety Critical</Badge>}
          {job.return_visit && <Badge className="bg-indigo-100 text-indigo-700 border-indigo-200"><RotateCcw className="w-3 h-3" /> Return Visit</Badge>}
          {status === 'paused_parts' && <Badge className="bg-amber-100 text-amber-700 border-amber-200"><Package className="w-3 h-3" /> Waiting for Parts</Badge>}
        </div>

        {/* Reported fault — front and centre */}
        <Card className="p-4 border-l-4 border-l-cyan-500">
          <p className="text-xs font-semibold text-cyan-700 uppercase tracking-wide">Reported Fault</p>
          <h1 className="text-lg font-bold text-slate-900 mt-1">{job.title}</h1>
          {job.description && <p className="text-slate-600 mt-1">{job.description}</p>}
        </Card>

        <div className="grid grid-cols-1 gap-3">
          <Card className="p-4">
            <div className="flex items-start gap-3">
              <Wrench className="w-5 h-5 text-slate-400 mt-0.5" />
              <div>
                <p className="text-xs font-semibold text-slate-400 uppercase">Equipment</p>
                <p className="font-semibold text-slate-900">{job.asset_name || '—'}</p>
                {job.equipment?.[0]?.serial_number && <p className="text-sm text-slate-500">Serial {job.equipment[0].serial_number}</p>}
              </div>
            </div>
          </Card>
          <Card className="p-4">
            <div className="flex items-start gap-3">
              <MapPin className="w-5 h-5 text-slate-400 mt-0.5" />
              <div className="min-w-0">
                <p className="text-xs font-semibold text-slate-400 uppercase">Site</p>
                <p className="font-semibold text-slate-900">{job.site_name}</p>
                <p className="text-sm text-slate-500">{job.territory_name} · {job.country}</p>
                {job.site?.access_instructions && (
                  <p className="text-sm text-slate-600 mt-2 bg-slate-50 rounded-lg p-2"><span className="font-semibold">Access:</span> {job.site.access_instructions}</p>
                )}
                {job.site?.contact_name && <p className="text-sm text-slate-500 mt-1">Contact: {job.site.contact_name} · {job.site.contact_phone}</p>}
              </div>
            </div>
          </Card>
        </div>

        {isOpen && <MissingAssetDetails jobId={jobId} />}

        {job.diagnosis && (
          <Card className="p-4"><p className="text-xs font-semibold text-slate-400 uppercase">Diagnosis</p><p className="text-slate-700 mt-1">{job.diagnosis}</p></Card>
        )}
        {!isOpen && job.resolution_notes && (
          <Card className="p-4 border-l-4 border-l-emerald-500" data-testid="jobdetail-completed-recap">
            <p className="text-xs font-semibold text-emerald-700 uppercase flex items-center gap-1"><CheckCircle2 className="w-3 h-3" /> Completed</p>
            {job.engineer_report ? <div className="mt-2"><EngineerReportView report={job.engineer_report} signoff={job.signature} /></div> : <p className="text-slate-700 mt-1">{job.resolution_notes}</p>}
            {job.parts_used && <p className="text-sm text-slate-500 mt-1">Parts used: {job.parts_used}</p>}
            <a href={`${process.env.REACT_APP_BACKEND_URL}/api/bfpo/jobs/${jobId}/job-sheet.pdf`} target="_blank" rel="noreferrer"
              className="inline-flex items-center gap-2 mt-3 text-cyan-600 font-semibold text-sm" data-testid="jobdetail-jobsheet">
              <FileText className="w-4 h-4" /> View job sheet (PDF)
            </a>
          </Card>
        )}

        {/* Panels */}
        {panel === 'arrive' && <ArrivePanel busy={busy} onCancel={() => setPanel(null)}
          onSubmit={(safe, notes) => act(() => bfpo.post(`/jobs/${jobId}/arrive`, { safe, notes }), safe ? 'On site' : 'Safety concern raised')} />}

        {panel === 'workflow' && (
          <WorkflowPanel job={job} busy={busy} onClose={() => setPanel(null)}
            onDiagnosis={(t) => act(() => bfpo.post(`/jobs/${jobId}/diagnosis`, { diagnosis: t }), 'Diagnosis saved')}
            onChoose={setPanel} />
        )}

        {panel === 'parts' && <PartsPanel job={job} busy={busy} onCancel={() => setPanel('workflow')}
          onSubmit={(payload) => act(() => bfpo.post(`/jobs/${jobId}/parts`, payload), 'Parts request logged — job now Waiting for Parts')} />}

        {String(panel).startsWith('outcome:') && (
          <OutcomePanel outcome={panel.split(':')[1]} busy={busy} onCancel={() => setPanel('workflow')}
            onSubmit={(reason, details) => act(() => bfpo.post(`/jobs/${jobId}/outcome`, { outcome: panel.split(':')[1], reason, details }), 'Update sent to MOD staff')} />
        )}

        {panel === 'report' && <ReportFaultPanel job={job} busy={busy} onCancel={() => setPanel('workflow')}
          onDone={(res) => { setPanel(null); flash(res.queued ? 'No signal — fault saved on this phone, it will send automatically' : res.warning ? res.warning : `Linked case ${res.case.reference} created`); }} jobId={jobId} />}

        {panel === 'complete' && <CompletePanel jobId={jobId} job={job} busy={busy} onCancel={() => setPanel('workflow')}
          onDone={(queued) => { if (!queued) load(); else setJob((j) => (j ? { ...j, status: pendingStatusFor(jobId, j.status) } : j)); setPanel(null); flash(queued ? 'No signal — completion saved on this phone, it will send automatically' : 'Job completed — job sheet generated'); }} />}

        {/* Timeline */}
        <div>
          <p className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1 mb-2"><History className="w-3 h-3" /> Activity</p>
          <div className="space-y-2">
            {(job.events || []).slice(0, 12).map((e) => (
              <div key={e.id} className="flex gap-3 text-sm">
                <div className="w-2 h-2 rounded-full bg-cyan-500 mt-1.5 shrink-0" />
                <div>
                  <p className="text-slate-700">{e.body || e.type}</p>
                  <p className="text-xs text-slate-400">{e.actor_name} · {localTime(e.at, job.site_timezone)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Sticky primary action */}
      {pa && !panel && (
        <div className="bfpo-sticky-action fixed bottom-16 left-0 right-0 px-4 pb-3 pt-2 bg-gradient-to-t from-white via-white to-transparent max-w-2xl mx-auto">
          <Btn full variant="primary" onClick={pa.onClick} disabled={busy} data-testid="jobdetail-primary-action" className="shadow-lg py-4 text-base">
            {busy ? <Loader2 className="w-5 h-5 animate-spin" /> : null}{pa.label}
          </Btn>
        </div>
      )}
      {toast && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-sm px-4 py-2 rounded-full shadow-lg z-20" data-testid="jobdetail-toast">{toast}</div>}
    </div>
  );
}

