export default function StaffJobs({ initialFilter = {}, onOpenJob }) {
  const [filters, setFilters] = useState({ status: 'open', territory: '', site: '', engineer: '', priority: '', safety: '', overdue: '', ...initialFilter });
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [meta, setMeta] = useState({ engineers: [], sites: [] });

  useEffect(() => { setFilters((f) => ({ ...f, ...initialFilter }));   }, [JSON.stringify(initialFilter)]);

  useEffect(() => {
    Promise.all([bfpo.get('/staff/engineers'), bfpo.get('/sites')]).then(([e, s]) =>
      setMeta({ engineers: e.data.engineers, sites: s.data.sites }));
  }, []);

  const fetchJobs = useCallback(() => {
    setLoading(true);
    const qs = Object.entries(filters).filter(([, v]) => v).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
    bfpo.get(`/staff/jobs?${qs}`).then((r) => { setJobs(r.data.jobs); setLoading(false); });
  }, [filters]);
  useEffect(() => { fetchJobs(); }, [fetchJobs]);

  const set = (k, v) => setFilters((f) => ({ ...f, [k]: v }));

  return (
    <div className="p-6 max-w-6xl mx-auto" data-testid="staff-jobs">
      <Card className="p-4 mb-4">
        <div className="flex items-center gap-2 text-slate-500 text-sm font-semibold mb-3"><Filter className="w-4 h-4" /> Filters</div>
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2">
          <select className={inputCls} value={filters.status} onChange={(e) => set('status', e.target.value)} data-testid="staff-filter-status">
            <option value="">All statuses</option><option value="open">Open</option><option value="on_site">On site</option>
            <option value="paused_parts">Waiting for parts</option><option value="closed">Completed</option>
          </select>
          <select className={inputCls} value={filters.priority} onChange={(e) => set('priority', e.target.value)} data-testid="staff-filter-priority">
            <option value="">Any priority</option><option value="p1">P1</option><option value="p2">P2</option><option value="p3">P3</option><option value="p4">P4</option>
          </select>
          <select className={inputCls} value={filters.site} onChange={(e) => set('site', e.target.value)} data-testid="staff-filter-site">
            <option value="">All sites</option>{meta.sites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
          <select className={inputCls} value={filters.engineer} onChange={(e) => set('engineer', e.target.value)} data-testid="staff-filter-engineer">
            <option value="">Any engineer</option>{meta.engineers.map((e) => <option key={e.id} value={e.id}>{e.full_name}</option>)}
          </select>
          <label className="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" checked={filters.safety === 'true'} onChange={(e) => set('safety', e.target.checked ? 'true' : '')} data-testid="staff-filter-safety" /> Safety-critical</label>
          <label className="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" checked={filters.overdue === 'true'} onChange={(e) => set('overdue', e.target.checked ? 'true' : '')} data-testid="staff-filter-overdue" /> Overdue</label>
        </div>
      </Card>

      {loading ? <Spinner /> : jobs.length === 0 ? <Empty icon={ClipboardList} title="No jobs match" testid="staff-jobs-empty" /> : (
        <Card className="overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
              <tr><th className="text-left p-3">Ref</th><th className="text-left p-3">Job</th><th className="text-left p-3 hidden md:table-cell">Site</th><th className="text-left p-3 hidden lg:table-cell">Engineer</th><th className="text-left p-3">Priority</th><th className="text-left p-3">Status</th><th className="p-3" /></tr>
            </thead>
            <tbody>
              {jobs.map((j) => (
                <tr key={j.id} onClick={() => onOpenJob(j.id)} className="border-t border-slate-100 hover:bg-slate-50 cursor-pointer" data-testid={`staff-job-row-${j.id}`}>
                  <td className="p-3 font-mono text-xs text-slate-500">{j.reference}</td>
                  <td className="p-3"><div className="flex items-center gap-1.5">{j.safety_critical && <AlertTriangle className="w-3.5 h-3.5 text-red-500" />}<span className="font-medium text-slate-800">{j.title}</span></div></td>
                  <td className="p-3 hidden md:table-cell text-slate-500">{j.site_name}</td>
                  <td className="p-3 hidden lg:table-cell text-slate-500">{j.assigned_engineer_name || <span className="text-amber-600">Unallocated</span>}</td>
                  <td className="p-3"><PriorityBadge p={j.priority} /></td>
                  <td className="p-3"><Badge className="bg-slate-100 text-slate-600 border-slate-200">{STATUS_LABEL[j.status] || j.status}</Badge></td>
                  <td className="p-3"><ChevronRight className="w-4 h-4 text-slate-300" /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Eye, EyeOff, ArrowRight, ArrowLeft, Check, Users, Building2, CreditCard, Loader2, Shield } from 'lucide-react';
import BrandWordmark from '../../components/shared/BrandWordmark';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

const PLANS = {
  starter: {
    name: 'Starter', base: 9.99, perUser: 4.99, color: 'var(--color-info-ios)',
    features: ['Contact & Company Management', 'Basic Deal Pipeline', 'Email Integration', 'Activity Tracking', 'Mobile Access'],
    best: false,
  },
  professional: {
    name: 'Professional', base: 19.99, perUser: 9.99, color: 'var(--color-success-alt)',
    features: ['Everything in Starter', 'AI-Powered Insights', 'Custom Pipelines', 'Workflow Automation', 'Quote & Proposal Builder', 'Advanced Reporting', 'Team Collaboration'],
    best: true,
  },
  enterprise: {
    name: 'Enterprise', base: 29.99, perUser: 14.99, color: 'var(--color-accent-magenta)',
    features: ['Everything in Professional', 'Custom Integrations (API)', 'White-Label Branding', 'Advanced Security & SSO', 'Unlimited Workflows', 'Priority Support', 'Data Import/Export Tools'],
    best: false,
  },
};

export default function CRMLogin({ onLogin }) {
  const [mode, setMode] = useState('login'); // login | signup
  const [step, setStep] = useState(1); // 1=plan, 2=details, 3=confirm
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [fullName, setFullName] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [selectedPlan, setSelectedPlan] = useState('professional');
  const [teamSize, setTeamSize] = useState(1);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [needs2FA, setNeeds2FA] = useState(false);
  const [tempToken, setTempToken] = useState('');
  const [twoFACode, setTwoFACode] = useState('');
  const [twoFAUser, setTwoFAUser] = useState(null);

  const theme = localStorage.getItem('theme') || 'dark';

  // Clear any stale CRM token when on login page
  useEffect(() => {
    localStorage.removeItem('crm_token');
  }, []);
  const isDark = theme === 'dark';
  const bg = isDark ? 'var(--color-ink-alt)' : 'var(--color-neutral-25)';
  const surface = isDark ? 'var(--color-neutral-900)' : 'var(--color-white)';
  const border = isDark ? 'var(--color-surface-dark-3)' : 'var(--color-border-alt)';
  const txt = isDark ? 'var(--color-neutral-50)' : '#1B1C1D';
  const txtM = isDark ? 'var(--color-neutral-400)' : 'var(--color-text-faint-alt)';
  const inputBg = isDark ? 'var(--color-ink-alt)' : 'var(--color-white)';

  // Iter 216h101 — branding leak fix. The CRM is shared across Pulse Fitness
  // and Pulse Fitness deployments. Default brand label tracks the host
  // domain so a Pulse Fitness operator never sees "Pulse Fitness CRM" on the
  // login screen, and vice versa.
  const isPulseHost = typeof window !== 'undefined' && /pulsefitness|pulse-fitness|pulse\.local/i.test(window.location.hostname || '');
  const brandLabel = isPulseHost ? 'Pulse Fitness CRM' : 'Pulse Fitness CRM';
  const brandInitial = isPulseHost ? 'P' : 'G';

  const plan = PLANS[selectedPlan];
  const monthlyTotal = plan ? (plan.base + plan.perUser * teamSize).toFixed(2) : '0.00';

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/login`, { email, password });
      if (data.requires_2fa) {
        setNeeds2FA(true);
        setTempToken(data.temp_token);
        setTwoFAUser(data.user);
        setTwoFACode('');
      } else {
        onLogin(data.token, data.user);
      }
    } catch (err) {
      setError(err.response?.data?.detail || 'Invalid credentials');
    } finally { setLoading(false); }
  };

  const handle2FAVerify = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/2fa/validate`, { temp_token: tempToken, code: twoFACode });
      onLogin(data.token, data.user);
    } catch (err) {
      setError(err.response?.data?.detail || 'Invalid 2FA code');
    } finally { setLoading(false); }
  };

  const handleRegister = async () => {
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/register`, {
        email, password, full_name: fullName,
        company_name: companyName, plan: selectedPlan, team_size: teamSize,
      });
      onLogin(data.token, data.user);
    } catch (err) {
      setError(err.response?.data?.detail || 'Registration failed');
    } finally { setLoading(false); }
  };

  const canProceedStep2 = fullName && email && password && password.length >= 6 && companyName;

  if (mode === 'login') {
    // 2FA Verification Screen
    if (needs2FA) {
      return (
        <div className="min-h-screen flex items-center justify-center px-4" style={{ background: bg }}>
          <div className="w-full max-w-sm" data-testid="crm-2fa-page">
            <div className="flex items-center gap-3 mb-8">
              <BrandWordmark height={36} />
            </div>
            <div className="w-12 h-12 rounded-full bg-[rgb(var(--rgb-info-ios)/0.1)] flex items-center justify-center mx-auto mb-4">
              <Shield size={24} style={{ color: 'var(--color-info-ios)' }} />
            </div>
            <h2 className="text-2xl font-semibold mb-1 text-center" style={{ color: txt }}>Two-Factor Authentication</h2>
            <p className="text-sm mb-6 text-center" style={{ color: txtM }}>
              Enter the 6-digit code from your authenticator app{twoFAUser?.full_name ? `, ${twoFAUser.full_name}` : ''}
            </p>
            {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm" data-testid="crm-2fa-error">{error}</div>}
            <form onSubmit={handle2FAVerify} className="space-y-4">
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Verification Code</label>
                <input
                  type="text"
                  value={twoFACode}
                  onChange={e => setTwoFACode(e.target.value.replace(/\D/g, '').slice(0, 8))}
                  className="w-full px-4 py-3 text-lg font-mono text-center tracking-[0.4em] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]"
                  style={{ background: inputBg, border: `1px solid ${border}`, color: txt }}
                  placeholder="000000"
                  autoFocus
                  required
                  data-testid="crm-2fa-code"
                />
                <p className="text-[11px] mt-2 text-center" style={{ color: txtM }}>Enter your 6-digit code or a backup code</p>
              </div>
              <button type="submit" disabled={loading || twoFACode.length < 6} className="w-full py-3 bg-[var(--color-info-ios)] text-white text-sm font-semibold rounded-lg disabled:opacity-50 flex items-center justify-center gap-2" data-testid="crm-2fa-submit">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <Shield size={16} />}
                {loading ? 'Verifying...' : 'Verify'}
              </button>
              <button type="button" onClick={() => { setNeeds2FA(false); setTempToken(''); setTwoFACode(''); setError(''); }}
                className="w-full text-sm text-center hover:underline" style={{ color: txtM }}>
                Back to login
              </button>
            </form>
          </div>
        </div>
      );
    }

    return (
      <div className="min-h-screen flex items-center justify-center px-4" style={{ background: bg }}>
        <div className="w-full max-w-sm" data-testid="crm-login-page">
          <div className="flex items-center gap-3 mb-8">
            <BrandWordmark height={36} />
          </div>
          <h2 className="text-2xl font-semibold mb-1" style={{ color: txt }}>Welcome back</h2>
          <p className="text-sm mb-6" style={{ color: txtM }}>Sign in to your CRM account</p>
          {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm" data-testid="crm-login-error">{error}</div>}
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Email</label>
              <input id="crm-login-email" name="username" autoComplete="username" type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="you@company.com" required data-testid="crm-login-email" />
            </div>
            <div>
              <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Password</label>
              <div className="relative">
                <input id="crm-login-password" name="password" autoComplete="current-password" type={showPwd ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} className="w-full px-4 py-2.5 pr-10 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Your password" required data-testid="crm-login-password" />
                <button type="button" onClick={() => setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2" style={{ color: txtM }}>{showPwd ? <EyeOff size={16} /> : <Eye size={16} />}</button>
              </div>
            </div>
            <button type="submit" disabled={loading} className="w-full flex items-center justify-center gap-2 py-2.5 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white text-sm font-medium rounded-lg transition-all disabled:opacity-50" data-testid="crm-login-submit">
              {loading ? <Loader2 size={16} className="animate-spin" /> : <>Sign In <ArrowRight size={16} /></>}
            </button>
          </form>
          <p className="mt-6 text-center text-sm" style={{ color: txtM }}>
            Don't have an account?{' '}
            <button onClick={() => { setMode('signup'); setStep(1); setError(''); }} className="text-[var(--color-info-ios)] hover:underline font-medium" data-testid="crm-toggle-mode">Start free trial</button>
          </p>
        </div>
      </div>
    );
  }

  // SIGNUP FLOW
  return (
    <div className="min-h-screen" style={{ background: bg }}>
      {/* Header */}
      <div className="border-b px-6 py-4 flex items-center justify-between" style={{ borderColor: border, background: surface }}>
        <div className="flex items-center gap-3">
          <BrandWordmark height={32} />
        </div>
        <button onClick={() => { setMode('login'); setError(''); }} className="text-sm font-medium text-[var(--color-info-ios)] hover:underline" data-testid="back-to-login">Already have an account? Sign in</button>
      </div>

      {/* Progress */}
      <div className="max-w-3xl mx-auto px-6 pt-8">
        <div className="flex items-center justify-center gap-2 mb-8">
          {[{ n: 1, label: 'Choose Plan' }, { n: 2, label: 'Your Details' }, { n: 3, label: 'Confirm' }].map((s, i) => (
            <React.Fragment key={s.n}>
              {i > 0 && <div className="w-12 h-0.5 rounded" style={{ background: step >= s.n ? 'var(--color-info-ios)' : border }} />}
              <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${step >= s.n ? 'bg-[var(--color-info-ios)] text-white' : ''}`} style={step < s.n ? { background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-border-alt)', color: txtM } : {}}>
                  {step > s.n ? <Check size={14} /> : s.n}
                </div>
                <span className="text-xs font-medium hidden sm:inline" style={{ color: step >= s.n ? txt : txtM }}>{s.label}</span>
              </div>
            </React.Fragment>
          ))}
        </div>

        {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm">{error}</div>}

        {/* Step 1: Plan Selection */}
        {step === 1 && (
          <div data-testid="signup-step-plan">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Choose your plan</h2>
            <p className="text-center mb-8 text-sm" style={{ color: txtM }}>All plans include a 14-day free trial. No credit card required.</p>
            <div className="grid md:grid-cols-3 gap-4">
              {Object.entries(PLANS).map(([key, p]) => (
                <div key={key} onClick={() => setSelectedPlan(key)}
                  className={`relative rounded-xl p-5 cursor-pointer transition-all ${selectedPlan === key ? 'ring-2 ring-[var(--color-info-ios)] scale-[1.02]' : 'hover:scale-[1.01]'}`}
                  style={{ background: surface, border: `1px solid ${selectedPlan === key ? 'var(--color-info-ios)' : border}` }}
                  data-testid={`plan-${key}`}>
                  {p.best && <div className="absolute -top-3 left-1/2 -translate-x-1/2 px-3 py-0.5 bg-[var(--color-success-alt)] text-white text-[10px] font-bold uppercase rounded-full tracking-wider">Most Popular</div>}
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ background: `${p.color}20` }}>
                    <CreditCard size={20} style={{ color: p.color }} />
                  </div>
                  <h3 className="text-lg font-semibold mb-1" style={{ color: txt }}>{p.name}</h3>
                  <div className="mb-4">
                    <span className="text-3xl font-bold" style={{ color: txt }}>£{p.base.toFixed(2)}</span>
                    <span className="text-sm" style={{ color: txtM }}>/mo + £{p.perUser.toFixed(2)}/user</span>
                  </div>
                  <ul className="space-y-2">
                    {p.features.map(f => (
                      <li key={f} className="flex items-start gap-2 text-sm" style={{ color: txtM }}>
                        <Check size={14} className="mt-0.5 flex-shrink-0" style={{ color: p.color }} />
                        {f}
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>

            {/* Team size */}
            <div className="mt-6 p-4 rounded-xl flex flex-col sm:flex-row items-center gap-4 justify-between" style={{ background: surface, border: `1px solid ${border}` }}>
              <div className="flex items-center gap-3">
                <Users size={20} style={{ color: 'var(--color-info-ios)' }} />
                <div>
                  <p className="text-sm font-medium" style={{ color: txt }}>Team Size</p>
                  <p className="text-xs" style={{ color: txtM }}>How many people will use the CRM?</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setTeamSize(Math.max(1, teamSize - 1))} className="w-8 h-8 rounded-lg flex items-center justify-center text-lg font-bold" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>-</button>
                <span className="text-xl font-bold w-8 text-center" style={{ color: txt }}>{teamSize}</span>
                <button onClick={() => setTeamSize(Math.min(100, teamSize + 1))} className="w-8 h-8 rounded-lg flex items-center justify-center text-lg font-bold" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>+</button>
              </div>
              <div className="text-right">
                <p className="text-lg font-bold" style={{ color: txt }}>£{monthlyTotal}</p>
                <p className="text-xs" style={{ color: txtM }}>per month</p>
              </div>
            </div>

            <button onClick={() => setStep(2)} className="w-full mt-6 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all" data-testid="signup-next-step2">
              Continue <ArrowRight size={16} />
            </button>
          </div>
        )}

        {/* Step 2: Details */}
        {step === 2 && (
          <div className="max-w-md mx-auto" data-testid="signup-step-details">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Your details</h2>
            <p className="text-center mb-6 text-sm" style={{ color: txtM }}>Set up your account</p>
            <div className="space-y-4">
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Full Name</label>
                <input type="text" value={fullName} onChange={e => setFullName(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="John Smith" required data-testid="crm-register-name" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Company Name</label>
                <input type="text" value={companyName} onChange={e => setCompanyName(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Acme Ltd" data-testid="crm-register-company" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Email</label>
                <input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="you@company.com" required data-testid="crm-login-email" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Password</label>
                <div className="relative">
                  <input type={showPwd ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} className="w-full px-4 py-2.5 pr-10 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Min 6 characters" required minLength={6} data-testid="crm-login-password" />
                  <button type="button" onClick={() => setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2" style={{ color: txtM }}>{showPwd ? <EyeOff size={16} /> : <Eye size={16} />}</button>
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button onClick={() => setStep(1)} className="flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2 transition-all" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>
                <ArrowLeft size={16} /> Back
              </button>
              <button onClick={() => { if (canProceedStep2) setStep(3); else setError('Please fill in all fields'); }} className="flex-1 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50" disabled={!canProceedStep2} data-testid="signup-next-step3">
                Review <ArrowRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* Step 3: Confirmation */}
        {step === 3 && (
          <div className="max-w-md mx-auto" data-testid="signup-step-confirm">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Review & Start Trial</h2>
            <p className="text-center mb-6 text-sm" style={{ color: txtM }}>14-day free trial — no credit card required</p>

            <div className="rounded-xl overflow-hidden mb-4" style={{ background: surface, border: `1px solid ${border}` }}>
              <div className="p-4 border-b" style={{ borderColor: border }}>
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Plan</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <CreditCard size={18} style={{ color: plan?.color || 'var(--color-info-ios)' }} />
                    <span className="font-semibold" style={{ color: txt }}>{plan?.name}</span>
                  </div>
                  <span className="font-bold" style={{ color: txt }}>£{monthlyTotal}/mo</span>
                </div>
                <p className="text-xs mt-1" style={{ color: txtM }}>£{plan?.base.toFixed(2)} base + £{plan?.perUser.toFixed(2)} x {teamSize} user{teamSize > 1 ? 's' : ''}</p>
              </div>
              <div className="p-4 border-b" style={{ borderColor: border }}>
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Account</p>
                <p className="text-sm" style={{ color: txt }}>{fullName}</p>
                <p className="text-sm" style={{ color: txtM }}>{email}</p>
              </div>
              <div className="p-4">
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Company</p>
                <div className="flex items-center gap-2">
                  <Building2 size={16} style={{ color: txtM }} />
                  <span className="text-sm" style={{ color: txt }}>{companyName || `${fullName}'s CRM`}</span>
                </div>
              </div>
            </div>

            <div className="p-3 rounded-lg mb-6 text-center text-sm" style={{ background: isDark ? '#1a2e1a' : '#F0FFF4', color: 'var(--color-success-alt)', border: '1px solid rgba(52,199,89,0.2)' }}>
              Your 14-day free trial starts today. You won't be charged until it ends.
            </div>

            <div className="flex gap-3">
              <button onClick={() => setStep(2)} className="flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>
                <ArrowLeft size={16} /> Back
              </button>
              <button onClick={handleRegister} disabled={loading} className="flex-1 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50" data-testid="signup-submit">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <>Start Free Trial <ArrowRight size={16} /></>}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import {
  MapPin, CheckCircle, XCircle, RefreshCw, Plus, Wrench, Gauge, AlertTriangle,
  ClipboardCheck, PenTool, ChevronRight, ChevronLeft, Loader2, Radio, Save,
} from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('crm_token') || ''}` });

const STEPS = [
  { id: 'asset_check', label: 'Asset Check', icon: ClipboardCheck },
  { id: 'service', label: 'Service', icon: Wrench },
  { id: 'calibration', label: 'Calibration', icon: Gauge },
  { id: 'faults', label: 'Faults', icon: AlertTriangle },
  { id: 'review', label: 'Review', icon: ClipboardCheck },
  { id: 'sign', label: 'Sign & Complete', icon: PenTool },
];

const RESULT_COLOR = { pass: '#16a34a', review: '#d97706', fail: '#dc2626', incomplete: '#9a9fa1' };

const BigButton = ({ onClick, children, color = '#0091ca', icon: Icon, testId, disabled, variant }) => (
  <button data-testid={testId} onClick={onClick} disabled={disabled}
    className="flex items-center justify-center gap-2 rounded-2xl px-5 py-4 text-base font-semibold transition-transform active:scale-95 disabled:opacity-40 w-full"
    style={variant === 'outline'
      ? { border: `2px solid ${color}`, color, background: 'transparent' }
      : { background: color, color: '#fff' }}>
    {Icon && <Icon size={20} />}{children}
  </button>
);

// ── Numeric keypad for calibration entry (§15/§16) ──────────────────
function NumPad({ value, onChange, onDone }) {
  const press = (k) => {
    if (k === 'del') return onChange(value.slice(0, -1));
    if (k === '.' && value.includes('.')) return;
    onChange((value + k).slice(0, 6));
  };
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '.', '0', 'del'];
  return (
    <div className="grid grid-cols-3 gap-2 mt-3" data-testid="calib-numpad">
      {keys.map(k => (
        <button key={k} onClick={() => press(k)} data-testid={`numpad-${k}`}
          className="rounded-xl py-4 text-xl font-bold bg-slate-100 active:bg-slate-200 dark:bg-zinc-800">
          {k === 'del' ? '⌫' : k}</button>
      ))}
      <button onClick={onDone} data-testid="numpad-done"
        className="col-span-3 rounded-xl py-3 text-base font-semibold bg-blue-600 text-white">Done</button>
    </div>
  );
}

export default function BlueLightVisitWizard() {
  const { visitId } = useParams();
  const nav = useNavigate();
  const [state, setState] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [step, setStep] = useState(0);
  const [activeAsset, setActiveAsset] = useState(null); // for audit/service/calibration modal
  const [mode, setMode] = useState(null); // 'audit' | 'service' | 'calibration' | 'fault' | 'addAsset'
  const [toast, setToast] = useState(null);

  const load = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/crm/v2/visits/${visitId}`, { headers: authHeaders() });
      setState(r.data);
    } catch (e) { setToast({ err: e.response?.data?.detail || 'Could not load the visit' }); }
    finally { setLoading(false); }
  }, [visitId]);

  useEffect(() => { load(); }, [load]);

  const post = async (path, body) => {
    setBusy(true);
    try {
      const r = await axios.post(`${API}/crm/v2/visits/${visitId}${path}`, body, { headers: authHeaders() });
      if (r.data.visit || r.data.progress) setState(r.data);
      else await load();
      return r.data;
    } catch (e) { setToast({ err: e.response?.data?.detail || 'Something went wrong' }); return null; }
    finally { setBusy(false); }
  };

  const lookupAsset = async ({ serial, model, name }) => {
    try {
      const params = new URLSearchParams();
      if (serial) params.set('serial', serial);
      if (model) params.set('model', model);
      if (name) params.set('name', name);
      const r = await axios.get(`${API}/crm/v2/visits/${visitId}/assets/lookup?${params.toString()}`, { headers: authHeaders() });
      return r.data.matches || [];
    } catch { return []; }
  };

  if (loading) return <div className="min-h-screen grid place-items-center bg-slate-50 dark:bg-zinc-900"><Loader2 className="animate-spin text-blue-600" /></div>;
  if (!state) return <div className="min-h-screen grid place-items-center bg-slate-50 text-slate-500 dark:bg-zinc-900">Visit not found.</div>;

  const { pack, assets, progress, completion_blockers, can_complete, contract, visit, calibrations } = state;
  const notStarted = !visit.started_at && visit.status !== 'in_progress' && visit.status !== 'completed';
  const treadmills = assets.filter(a => a.is_treadmill && a.audit && a.audit !== 'not_found');
  const presentAssets = assets.filter(a => ['present', 'update', 'replaced', 'add'].includes(a.audit));

  // ── START SCREEN (§6) ──
  if (notStarted) {
    return (
      <div className="min-h-screen bg-slate-50 pb-10 dark:bg-zinc-900">
        <div className="bg-blue-700 text-white px-5 pt-8 pb-6">
          <div className="flex items-center gap-2 text-blue-200 text-sm"><Radio size={16} /> Blue Light Service</div>
          <h1 className="text-2xl font-bold mt-1" data-testid="visit-station-name">{pack.station_name}</h1>
          <p className="text-blue-100 text-sm mt-1">{pack.station?.address}, {pack.station?.city} {pack.station?.postcode}</p>
        </div>
        <div className="p-5 space-y-4">
          <div className="rounded-2xl bg-white shadow p-4 grid grid-cols-3 text-center dark:bg-zinc-900">
            <div><div className="text-2xl font-bold">{pack.expected_asset_count}</div><div className="text-xs text-slate-500">Machines</div></div>
            <div><div className="text-2xl font-bold text-blue-600">{pack.treadmill_count}</div><div className="text-xs text-slate-500">Treadmills</div></div>
            <div><div className="text-2xl font-bold">{contract.contract_number || '—'}</div><div className="text-xs text-slate-500">Contract</div></div>
          </div>
          <div className="rounded-2xl bg-white shadow p-4 text-sm text-slate-600 space-y-1 dark:bg-zinc-900">
            <div><b>Contact:</b> {pack.station?.contact_name} · {pack.station?.telephone}</div>
            {pack.station?.access_instructions && <div><b>Access:</b> {pack.station.access_instructions}</div>}
            {pack.station?.parking_info && <div><b>Parking:</b> {pack.station.parking_info}</div>}
          </div>
          <label className="flex items-start gap-3 rounded-2xl bg-white shadow p-4 text-sm dark:bg-zinc-900">
            <input type="checkbox" id="confirm-site" data-testid="confirm-on-site" className="mt-1 w-5 h-5" />
            <span>I confirm I am at the correct station: <b>{pack.station_name}</b></span>
          </label>
          <BigButton testId="start-visit-btn" icon={MapPin} disabled={busy} color="#0091ca"
            onClick={async () => {
              const ok = document.getElementById('confirm-site')?.checked;
              if (!ok) { setToast({ err: 'Please tick the box to confirm you are at the correct station.' }); return; }
              await post('/start', { confirmed_on_site: true });
            }}>Start Station Service</BigButton>
        </div>
        {toast && <Toast toast={toast} onClose={() => setToast(null)} />}
      </div>
    );
  }

  if (visit.status === 'completed') {
    return (
      <div className="min-h-screen bg-slate-50 grid place-items-center p-6 dark:bg-zinc-900">
        <div className="rounded-2xl bg-white shadow p-8 text-center max-w-sm dark:bg-zinc-900" data-testid="visit-completed">
          <CheckCircle size={56} className="mx-auto text-green-600" />
          <h2 className="text-xl font-bold mt-3">Visit Completed</h2>
          <p className="text-slate-600 mt-1">{pack.station_name}</p>
          <p className="text-sm text-slate-500 mt-2">Next service due: <b>{visit.next_service_due}</b></p>
          <p className="text-xs text-slate-400 mt-1">Certificate: {visit.certificate_status?.replace(/_/g, ' ')}</p>
          {visit.certificate_id && (
            <button data-testid="download-cert-btn" onClick={() => {
              axios.get(`${API}/crm/v2/certificates/${visit.certificate_id}/download`, { headers: authHeaders(), responseType: 'blob' })
                .then(res => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' })); a.download = 'certificate.pdf'; a.click(); URL.revokeObjectURL(a.href); })
                .catch(() => {});
            }} className="mt-3 text-sm underline text-blue-600">Download certificate</button>
          )}
          <BigButton testId="back-to-matrix" color="#0091ca" onClick={() => nav('/crm?tab=contracts')}>Back to contracts</BigButton>
        </div>
      </div>
    );
  }

  const curStep = STEPS[step].id;

  return (
    <div className="min-h-screen bg-slate-50 pb-28 dark:bg-zinc-900">
      {/* Header + progress */}
      <div className="bg-blue-700 text-white px-5 pt-6 pb-4 sticky top-0 z-20">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-blue-200 text-xs flex items-center gap-1"><Radio size={13} /> Blue Light Service</div>
            <h1 className="text-lg font-bold" data-testid="wizard-station-name">{pack.station_name}</h1>
          </div>
          <div className="text-right text-xs text-blue-100">
            <div data-testid="wizard-asset-progress">{progress.accounted} / {progress.expected_assets} assets</div>
            <div>{progress.treadmills_calibrated}/{progress.treadmills_required} treadmills</div>
          </div>
        </div>
        <div className="flex gap-1 mt-3 overflow-x-auto no-scrollbar">
          {STEPS.map((s, i) => (
            <button key={s.id} onClick={() => setStep(i)} data-testid={`step-tab-${s.id}`}
              className="flex-shrink-0 flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold whitespace-nowrap"
              style={{ background: i === step ? '#fff' : 'rgba(255,255,255,0.15)', color: i === step ? '#0091ca' : '#dbeafe' }}>
              <s.icon size={12} />{i + 1}. {s.label}
            </button>
          ))}
        </div>
      </div>

      <div className="p-4 space-y-3">
        {curStep === 'asset_check' && (
          <AssetList assets={assets} title="Confirm every asset" emptyDone={progress.assets_remaining === 0}
            onPick={(a) => { setActiveAsset(a); setMode('audit'); }}
            badge={(a) => a.audit ? { text: AUDIT_LABEL[a.audit], color: a.audit === 'not_found' ? '#dc2626' : '#16a34a' } : { text: 'Pending', color: '#9a9fa1' }}
            footer={<BigButton testId="add-asset-btn" variant="outline" color="#0091ca" icon={Plus}
              onClick={() => { setActiveAsset(null); setMode('addAsset'); }}>Add machine not on list</BigButton>} />
        )}
        {curStep === 'service' && (
          <AssetList assets={presentAssets} title="Service each machine" emptyDone={progress.serviced === progress.to_service}
            onPick={(a) => { setActiveAsset(a); setMode('service'); }}
            badge={(a) => a.service_outcome ? { text: SERVICE_LABEL[a.service_outcome] || 'Done', color: '#16a34a' } : { text: 'To service', color: '#9a9fa1' }} />
        )}
        {curStep === 'calibration' && (
          <div className="space-y-3">
            <StepTitle>{progress.treadmills_calibrated}/{progress.treadmills_required} treadmills calibrated</StepTitle>
            {treadmills.length === 0 && <Empty>No treadmills requiring calibration at this station.</Empty>}
            {treadmills.map(t => {
              const cal = calibrations[t.asset_key];
              return (
                <button key={t.asset_key} data-testid={`calib-asset-${t.asset_key}`}
                  onClick={() => { setActiveAsset(t); setMode('calibration'); }}
                  className="w-full text-left rounded-2xl bg-white shadow p-4 flex items-center justify-between dark:bg-zinc-900">
                  <div>
                    <div className="font-semibold">{t.asset_name}</div>
                    <div className="text-xs text-slate-500">Serial: {t.serial_number || '—'}</div>
                  </div>
                  {cal?.overall
                    ? <span className="px-3 py-1 rounded-full text-xs font-bold text-white" style={{ background: RESULT_COLOR[cal.overall] }}>{cal.overall.toUpperCase()}</span>
                    : <span className="px-3 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-700">CALIBRATION REQUIRED</span>}
                </button>
              );
            })}
          </div>
        )}
        {curStep === 'faults' && (
          <div className="space-y-3">
            <StepTitle>Faults & actions</StepTitle>
            {(state.faults || []).length === 0 && <Empty>No faults raised yet.</Empty>}
            {(state.faults || []).map(f => (
              <div key={f.id} className="rounded-2xl bg-white shadow p-4 dark:bg-zinc-900" data-testid={`fault-row-${f.id}`}>
                <div className="font-semibold text-sm">{f.reference} · {f.title}</div>
                <div className="text-xs text-slate-500 mt-0.5">Priority {f.priority?.toUpperCase()}{f.out_of_service ? ' · OUT OF SERVICE' : ''}</div>
              </div>
            ))}
            <BigButton testId="raise-fault-btn" variant="outline" color="#dc2626" icon={AlertTriangle}
              onClick={() => { setActiveAsset(null); setMode('fault'); }}>Raise a fault</BigButton>
          </div>
        )}
        {curStep === 'review' && <ReviewPanel state={state} />}
        {curStep === 'sign' && (
          <SignPanel busy={busy} blockers={completion_blockers} canComplete={can_complete}
            onGoTo={(b) => { const idx = STEPS.findIndex(s => s.id === (b.type === 'calibration' ? 'calibration' : b.type === 'service' ? 'service' : 'asset_check')); setStep(idx >= 0 ? idx : 0); }}
            onComplete={async (sig, name, override) => {
              const r = await post('/complete', { signature_data: sig, engineer_name: name, override_reason: override });
              if (r?.success) { setToast({ ok: `Visit complete. Next service ${r.next_service_due}.` }); await load(); }
              else if (r?.blocked) setToast({ err: r.message });
            }}
            onPartial={async (reason) => { const r = await post('/partial', { reason }); if (r?.success) { setToast({ ok: 'Saved as partial visit.' }); nav('/crm?tab=contracts'); } }} />
        )}
      </div>

      {/* Sticky footer nav */}
      <div className="fixed bottom-0 inset-x-0 bg-white border-t p-3 flex gap-2 z-20 dark:bg-zinc-900">
        <button data-testid="wizard-prev" disabled={step === 0} onClick={() => setStep(s => Math.max(0, s - 1))}
          className="flex-1 rounded-xl py-3 font-semibold border disabled:opacity-30 flex items-center justify-center gap-1"><ChevronLeft size={18} />Back</button>
        <button data-testid="wizard-next" disabled={step === STEPS.length - 1} onClick={() => setStep(s => Math.min(STEPS.length - 1, s + 1))}
          className="flex-1 rounded-xl py-3 font-semibold bg-blue-600 text-white disabled:opacity-30 flex items-center justify-center gap-1">Next<ChevronRight size={18} /></button>
      </div>

      {/* Modals */}
      {mode === 'audit' && activeAsset && <AuditSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { await post(`/assets/${activeAsset.asset_key}/audit`, payload); setMode(null); }} />}
      {mode === 'addAsset' && <AddAssetSheet busy={busy} onClose={() => setMode(null)}
        onLookup={lookupAsset}
        onRequestTransfer={async (assetId, reason) => {
          const r = await post(`/assets/${assetId}/transfer-request`, { reason });
          if (r) { setMode(null); setToast({ ok: 'Transfer requested — the office will review it.' }); }
        }}
        onSubmit={async (na) => { await post(`/assets/new-${Date.now()}/audit`, { action: 'add', new_asset: na }); setMode(null); }} />}
      {mode === 'service' && activeAsset && <ServiceSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { await post(`/assets/${activeAsset.asset_key}/service`, payload); setMode(null); }}
        onRaiseFault={() => setMode('fault')} />}
      {mode === 'calibration' && activeAsset && <CalibrationSheet asset={activeAsset} config={contract.blue_light} busy={busy}
        existing={calibrations[activeAsset.asset_key]} onClose={() => setMode(null)}
        onSubmit={async (payload) => await post(`/treadmills/${activeAsset.asset_key}/calibration`, payload)} />}
      {mode === 'fault' && <FaultSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { const r = await post('/faults', payload); if (r?.success) { setToast({ ok: `Fault ${r.fault.reference} raised.` }); setMode(null); await load(); } }} />}

      {toast && <Toast toast={toast} onClose={() => setToast(null)} />}
    </div>
  );
}

const AUDIT_LABEL = { present: 'Present', update: 'Updated', not_found: 'Not found', replaced: 'Replaced', add: 'New' };
const SERVICE_LABEL = {
  serviced_operational: 'Operational', serviced_minor_issue: 'Minor issue', serviced_fault_raised: 'Fault raised',
  out_of_service: 'Out of service', unable_to_service: 'Unable', asset_not_present: 'Not present', further_visit_required: 'Follow-up',
};

const StepTitle = ({ children }) => <h2 className="font-bold text-slate-700 px-1">{children}</h2>;
const Empty = ({ children }) => <div className="rounded-2xl bg-white shadow p-6 text-center text-slate-400 text-sm dark:bg-zinc-900">{children}</div>;

function AssetList({ assets, title, onPick, badge, footer, emptyDone }) {
  return (
    <div className="space-y-3">
      <StepTitle>{title}{emptyDone && <span className="ml-2 text-green-600 text-sm">✓ all done</span>}</StepTitle>
      {assets.length === 0 && <Empty>Nothing here.</Empty>}
      {assets.map(a => {
        const b = badge(a);
        return (
          <button key={a.asset_key} onClick={() => onPick(a)} data-testid={`asset-row-${a.asset_key}`}
            className="w-full text-left rounded-2xl bg-white dark:bg-zinc-900 shadow p-4 flex items-center justify-between active:scale-[0.99] transition-transform">
            <div className="min-w-0">
              <div className="font-semibold truncate">{a.asset_name} {a.is_treadmill && <span className="text-blue-600 text-xs">· treadmill</span>}</div>
              <div className="text-xs text-slate-500 truncate">{a.equipment_type} · {a.serial_number || 'no serial'}</div>
            </div>
            <span className="px-3 py-1 rounded-full text-xs font-semibold flex-shrink-0" style={{ background: b.color + '22', color: b.color }}>{b.text}</span>
          </button>
        );
      })}
      {footer}
    </div>
  );
}

function Sheet({ title, children, onClose }) {
  return (
    <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center bg-black/40" onClick={onClose}>
      <div className="bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-3xl p-5 max-h-[90vh] overflow-y-auto dark:bg-zinc-900" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-bold text-lg">{title}</h3>
          <button onClick={onClose} className="text-slate-400 p-1"><XCircle size={22} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

function AuditSheet({ asset, onSubmit, onClose, busy }) {
  const [view, setView] = useState('actions');
  const [changes, setChanges] = useState({ asset_name: asset.asset_name, model_code: asset.model_code || '', serial_number: asset.serial_number || '', location: asset.location || '' });
  const [reason, setReason] = useState('');
  const inp = 'w-full border rounded-xl px-3 py-2.5 mt-1';
  return (
    <Sheet title={asset.asset_name} onClose={onClose}>
      {view === 'actions' && (
