import { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import {
  ShieldCheck, IdCard, Receipt, RefreshCw, Loader2, AlertTriangle,
  CheckCircle2, Clock, HelpCircle,
} from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

const PILL = {
  expired:   { cls: 'bg-rose-100 text-rose-700 border-rose-200',       label: 'Expired' },
  expiring:  { cls: 'bg-amber-100 text-amber-700 border-amber-200',    label: 'Expiring' },
  missing:   { cls: 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-zinc-800 dark:border-zinc-800',    label: 'Not on file' },
  ok:        { cls: 'bg-emerald-100 text-emerald-700 border-emerald-200', label: 'Valid' },
  attention: { cls: 'bg-rose-100 text-rose-700 border-rose-200',       label: 'Check needed' },
};

function StatusPill({ status, children, testid }) {
  const p = PILL[status] || PILL.missing;
  return (
    <span data-testid={testid}
      className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-semibold ${p.cls}`}>
      {children || p.label}
    </span>
  );
}

function SummaryCard({ testid, icon: Icon, tint, title, urgent, urgentLabel, breakdown }) {
  const clear = urgent === 0;
  return (
    <div data-testid={testid}
      className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:bg-zinc-900 dark:border-zinc-800">
      <div className="flex items-start justify-between">
        <div className="flex h-11 w-11 items-center justify-center rounded-xl"
          style={{ background: `${tint}1f`, color: tint }}>
          <Icon size={22} />
        </div>
        <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-bold ${clear ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
          {clear ? <CheckCircle2 size={13} /> : <AlertTriangle size={13} />}
          {clear ? 'All clear' : `${urgent} ${urgentLabel}`}
        </span>
      </div>
      <h3 className="mt-4 text-base font-bold text-slate-800">{title}</h3>
      <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-sm text-slate-500">
        {breakdown.map((b) => (
          <span key={b.label}><span className="font-bold text-slate-700">{b.value}</span> {b.label}</span>
        ))}
      </div>
    </div>
  );
}

function SectionCard({ title, icon: Icon, count, children }) {
  return (
    <div className="rounded-2xl border border-slate-200 bg-white shadow-sm dark:bg-zinc-900 dark:border-zinc-800">
      <div className="flex items-center gap-2 border-b border-slate-100 dark:border-zinc-800 px-5 py-3.5">
        <Icon size={18} className="text-slate-400" />
        <h3 className="text-sm font-bold uppercase tracking-wide text-slate-700">{title}</h3>
        <span className="ml-auto text-xs font-semibold text-slate-400">{count} to review</span>
      </div>
      <div className="divide-y divide-slate-100">{children}</div>
    </div>
  );
}

function EmptyRow({ text }) {
  return (
    <div className="flex items-center gap-2 px-5 py-6 text-sm text-slate-400">
      <CheckCircle2 size={16} className="text-emerald-500" /> {text}
    </div>
  );
}

export default function ComplianceTab({ headers }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const { data } = await axios.get(`${API}/staffing/compliance`, { headers });
      setData(data);
    } catch (e) {
      setError(e?.response?.data?.detail || 'Could not load compliance data.');
    } finally {
      setLoading(false);
    }
  }, [headers]);

  useEffect(() => { load(); }, [load]);

  if (loading && !data) {
    return (
      <div className="flex items-center justify-center py-24 text-slate-400" data-testid="compliance-loading">
        <Loader2 className="animate-spin" size={22} />
      </div>
    );
  }
  if (error) {
    return (
      <div className="rounded-2xl border border-rose-200 bg-rose-50 p-6 text-rose-700" data-testid="compliance-error">
        {error} <button onClick={load} className="ml-2 underline">Retry</button>
      </div>
    );
  }

  const s = data.summary;
  const dbsUrgent = s.dbs.expired + s.dbs.expiring + s.dbs.missing;
  const rtwUrgent = s.right_to_work.attention + s.right_to_work.missing;
  const dbsNeed = data.dbs.filter((r) => r.status !== 'ok');
  const rtwNeed = data.right_to_work.filter((r) => r.status !== 'ok');

  return (
    <div className="space-y-6" data-testid="compliance-tab">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-slate-500">
            DBS certificates, Right-to-Work checks and outstanding vehicle fines across {s.staff_count} staff.
          </p>
        </div>
        <button onClick={load} data-testid="compliance-refresh"
          className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white dark:bg-zinc-900 px-3 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50">
          {loading ? <Loader2 size={15} className="animate-spin" /> : <RefreshCw size={15} />} Refresh
        </button>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <SummaryCard testid="compliance-card-dbs" icon={IdCard} tint="#0091ca"
          title="Enhanced DBS" urgent={dbsUrgent} urgentLabel="need action"
          breakdown={[
            { label: 'valid', value: s.dbs.ok },
            { label: 'expiring', value: s.dbs.expiring },
            { label: 'expired', value: s.dbs.expired },
            { label: 'not on file', value: s.dbs.missing },
          ]} />
        <SummaryCard testid="compliance-card-rtw" icon={ShieldCheck} tint="#0091ca"
          title="Right to Work" urgent={rtwUrgent} urgentLabel="need action"
          breakdown={[
            { label: 'verified', value: s.right_to_work.ok },
            { label: 'to check', value: s.right_to_work.attention },
            { label: 'not on file', value: s.right_to_work.missing },
          ]} />
        <SummaryCard testid="compliance-card-fines" icon={Receipt} tint="#e11d48"
          title="Outstanding Fines" urgent={s.fines.unpaid_count} urgentLabel="unpaid"
          breakdown={[
            { label: `unpaid (£${s.fines.unpaid_total.toFixed(2)})`, value: s.fines.unpaid_count },
            { label: '14+ days overdue', value: s.fines.overdue_count },
          ]} />
      </div>

      <SectionCard title="DBS — needs attention" icon={IdCard} count={dbsNeed.length}>
        {dbsNeed.length === 0 ? <EmptyRow text="Every DBS certificate on file is valid." /> :
          dbsNeed.map((r) => (
            <div key={r.staff_id} data-testid="compliance-dbs-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">{r.name}</div>
                <div className="text-xs text-slate-400">
                  {r.expiry_date ? `Expires ${r.expiry_date}` : 'No DBS on file'}
                  {typeof r.days === 'number' && r.status === 'expiring' && ` · in ${r.days} day${r.days === 1 ? '' : 's'}`}
                  {typeof r.days === 'number' && r.status === 'expired' && ` · ${Math.abs(r.days)} day${Math.abs(r.days) === 1 ? '' : 's'} ago`}
                </div>
              </div>
              <StatusPill status={r.status} testid="compliance-dbs-status">
                {r.status === 'expiring' && <Clock size={12} />}
                {r.status === 'expired' && <AlertTriangle size={12} />}
                {r.status === 'missing' && <HelpCircle size={12} />}
                {PILL[r.status]?.label}
              </StatusPill>
            </div>
          ))}
      </SectionCard>

      <SectionCard title="Right to Work — needs attention" icon={ShieldCheck} count={rtwNeed.length}>
        {rtwNeed.length === 0 ? <EmptyRow text="Every Right-to-Work check is verified." /> :
          rtwNeed.map((r) => (
            <div key={r.staff_id} data-testid="compliance-rtw-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">{r.name}</div>
                <div className="text-xs text-slate-400">{r.raw_status ? `Status: ${r.raw_status}` : 'No status recorded'}</div>
              </div>
              <StatusPill status={r.status} testid="compliance-rtw-status" />
            </div>
          ))}
      </SectionCard>

      <SectionCard title="Outstanding vehicle fines" icon={Receipt} count={data.fines.length}>
        {data.fines.length === 0 ? <EmptyRow text="No unpaid fines across the fleet." /> :
          data.fines.map((f, i) => (
            <div key={`${f.vehicle_id}-${i}`} data-testid="compliance-fine-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">
                  {f.reg_no} <span className="font-normal text-slate-400">{f.vehicle ? `· ${f.vehicle}` : ''}</span>
                </div>
                <div className="text-xs text-slate-400">
                  {f.kind || 'Fine'}{f.date ? ` · ${f.date}` : ''}
                  {typeof f.age_days === 'number' && ` · ${f.age_days} day${f.age_days === 1 ? '' : 's'} outstanding`}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span className="font-bold text-slate-800">£{f.value.toFixed(2)}</span>
                {f.overdue && (
                  <span className="inline-flex items-center gap-1 rounded-full border border-rose-200 bg-rose-100 px-2.5 py-0.5 text-xs font-semibold text-rose-700">
                    <AlertTriangle size={12} /> Overdue
                  </span>
                )}
              </div>
            </div>
          ))}
      </SectionCard>
    </div>
  );
}

/** Org Chart visual canvas — pan, zoom, drag, reporting lines. */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  ZoomIn, ZoomOut, Maximize2, RotateCcw, Wand2, Plus, Crosshair,
} from 'lucide-react';
import OrgCard from './OrgCard';
import { CARD_W, CARD_H, bounds } from './layout';
import { deptColor, EDGE_TYPES } from './api';

const EDGE_COLOR = Object.fromEntries(EDGE_TYPES.map((e) => [e.id, e.color]));
const MIN_SCALE = 0.25;
const MAX_SCALE = 2;

function ToolBtn({ onClick, title, children, testId }) {
  return (
    <button onClick={onClick} title={title} data-testid={testId}
      className="w-9 h-9 rounded-lg inline-flex items-center justify-center border transition-colors"
      style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>
      {children}
    </button>
  );
}

export default function Canvas({
  nodes, edges, settings, dimmedIds, focusId, fitSignal, onMoveNode, onRequestSetManager, onOpenNode, onAutoLayout, onAddCard,
}) {
  const { t } = useTranslation();
  const wrapRef = useRef(null);
  const [scale, setScale] = useState(0.8);
  const [tx, setTx] = useState(80);
  const [ty, setTy] = useState(40);
  const [pos, setPos] = useState({});
  const [selected, setSelected] = useState(null);
  const drag = useRef(null);
  const pan = useRef(null);
  const [hoverTarget, setHoverTarget] = useState(null);
  const [, force] = useState(0);

  const toggles = settings?.field_toggles || {};

  // Sync local positions from props.
  useEffect(() => {
    setPos((prev) => {
      const next = {};
      nodes.forEach((n) => { next[n.id] = prev[n.id] && drag.current?.id === n.id ? prev[n.id] : { x: n.x || 0, y: n.y || 0 }; });
      return next;
    });
  }, [nodes]);

  const reportsCount = useMemo(() => {
    const m = {};
    nodes.forEach((n) => { if (n.manager_node_id) m[n.manager_node_id] = (m[n.manager_node_id] || 0) + 1; });
    return m;
  }, [nodes]);

  const byId = useMemo(() => Object.fromEntries(nodes.map((n) => [n.id, n])), [nodes]);

  const toChart = useCallback((clientX, clientY) => {
    const r = wrapRef.current.getBoundingClientRect();
    return { x: (clientX - r.left - tx) / scale, y: (clientY - r.top - ty) / scale };
  }, [tx, ty, scale]);

  const fit = useCallback(() => {
    if (!wrapRef.current || !nodes.length) return;
    const b = bounds(nodes.map((n) => ({ ...n, ...(pos[n.id] || {}) })));
    const r = wrapRef.current.getBoundingClientRect();
    const w = b.maxX - b.minX; const h = b.maxY - b.minY;
    const s = Math.min((r.width - 80) / w, (r.height - 80) / h, MAX_SCALE);
    const ns = Math.max(MIN_SCALE, s || 0.8);
    setScale(ns);
    setTx((r.width - w * ns) / 2 - b.minX * ns);
    setTy((r.height - h * ns) / 2 - b.minY * ns + 10);
  }, [nodes, pos]);

  // Fit once when node count goes from 0→n.
  const fitKey = nodes.length;
  useEffect(() => { const tid = setTimeout(fit, 60); return () => clearTimeout(tid);   }, [fitKey]);

  // On-demand fit (e.g. before an export) — parent bumps `fitSignal`.
  useEffect(() => {
    if (!fitSignal) return undefined;
    const tid = setTimeout(fit, 30);
    return () => clearTimeout(tid);
  }, [fitSignal]); // eslint-disable-line

  // Focus a node (from search).
  useEffect(() => {
    if (!focusId || !pos[focusId] || !wrapRef.current) return;
    const r = wrapRef.current.getBoundingClientRect();
    const p = pos[focusId];
    setScale(1);
    setTx(r.width / 2 - (p.x + CARD_W / 2));
    setTy(r.height / 2 - (p.y + CARD_H / 2));
    setSelected(focusId);
  }, [focusId]); // eslint-disable-line

  // ─── pointer handlers ───
  const onCardPointerDown = (e, node) => {
    e.stopPropagation();
    // setPointerCapture can throw (InvalidStateError / no active pointer) in
    // some browsers when captured on an ancestor of the pointerdown target —
    // never let that crash the canvas.
    try { wrapRef.current?.setPointerCapture?.(e.pointerId); } catch { /* noop */ }
    drag.current = { id: node.id, startX: e.clientX, startY: e.clientY, origX: pos[node.id]?.x || 0, origY: pos[node.id]?.y || 0, moved: false, pointerId: e.pointerId };
    setSelected(node.id);
  };

  const onBgPointerDown = (e) => {
    if (e.target.closest('[data-orgcard]')) return;
    pan.current = { startX: e.clientX, startY: e.clientY, tx, ty };
    setSelected(null);
  };

  const onPointerMove = (e) => {
    if (drag.current) {
      const dx = (e.clientX - drag.current.startX) / scale;
      const dy = (e.clientY - drag.current.startY) / scale;
      if (Math.abs(dx) > 2 || Math.abs(dy) > 2) drag.current.moved = true;
      setPos((p) => ({ ...p, [drag.current.id]: { x: drag.current.origX + dx, y: drag.current.origY + dy } }));
      // hover detection for manager drop
      const c = toChart(e.clientX, e.clientY);
      let hit = null;
      nodes.forEach((n) => {
        if (n.id === drag.current.id) return;
        const np = pos[n.id]; if (!np) return;
        if (c.x >= np.x && c.x <= np.x + CARD_W && c.y >= np.y && c.y <= np.y + CARD_H) hit = n.id;
      });
      if (hit !== hoverTarget) setHoverTarget(hit);
    } else if (pan.current) {
      setTx(pan.current.tx + (e.clientX - pan.current.startX));
      setTy(pan.current.ty + (e.clientY - pan.current.startY));
    }
  };

  const onPointerUp = (e) => {
    if (drag.current) {
      const d = drag.current;
      const target = hoverTarget;
      drag.current = null;
      setHoverTarget(null);
      try { wrapRef.current?.releasePointerCapture?.(d.pointerId); } catch { /* noop */ }
      if (d.moved && target && target !== d.id) {
        // reset visual position; manager change re-layouts via parent
        const home = byId[d.id];
        if (home) setPos((p) => ({ ...p, [d.id]: { x: home.x || 0, y: home.y || 0 } }));
        onRequestSetManager(d.id, target);
      } else if (d.moved) {
        const np = pos[d.id];
        if (np) onMoveNode(d.id, { x: Math.round(np.x), y: Math.round(np.y) });
      }
    }
    pan.current = null;
    force((n) => n + 1);
  };

  const onWheel = (e) => {
    e.preventDefault();
    const r = wrapRef.current.getBoundingClientRect();
    const factor = e.deltaY < 0 ? 1.12 : 0.89;
    const ns = Math.min(MAX_SCALE, Math.max(MIN_SCALE, scale * factor));
    const cx = e.clientX - r.left; const cy = e.clientY - r.top;
    setTx(cx - (cx - tx) * (ns / scale));
    setTy(cy - (cy - ty) * (ns / scale));
    setScale(ns);
  };

  const zoom = (factor) => {
    const ns = Math.min(MAX_SCALE, Math.max(MIN_SCALE, scale * factor));
    const r = wrapRef.current.getBoundingClientRect();
    const cx = r.width / 2; const cy = r.height / 2;
    setTx(cx - (cx - tx) * (ns / scale));
    setTy(cy - (cy - ty) * (ns / scale));
    setScale(ns);
  };

  // connection paths
  const isVertical = settings?.layout === 'vertical';
  const paths = useMemo(() => nodes.map((n) => {
    if (!n.manager_node_id || !byId[n.manager_node_id]) return null;
    const m = pos[n.manager_node_id]; const c = pos[n.id];
    if (!m || !c) return null;
    const dim = dimmedIds.has(n.id) || dimmedIds.has(n.manager_node_id);
    if (isVertical) {
      // orthogonal "file-tree" elbow: down from the manager then right into the child
      const sx = m.x + 22;
      const sy = m.y + CARD_H;
      const ey = c.y + CARD_H / 2;
      const ex = c.x;
      return { id: n.id, d: `M ${sx} ${sy} L ${sx} ${ey} L ${ex} ${ey}`, dim };
    }
    const sx = m.x + CARD_W / 2; const sy = m.y + CARD_H;
    const ex = c.x + CARD_W / 2; const ey = c.y;
    const midY = (sy + ey) / 2;
    return { id: n.id, d: `M ${sx} ${sy} C ${sx} ${midY}, ${ex} ${midY}, ${ex} ${ey}`, dim };
  }).filter(Boolean), [nodes, pos, byId, dimmedIds, isVertical]);

  // dashed secondary-reporting edges
  const edgePaths = useMemo(() => (edges || []).map((e) => {
    const a = pos[e.from_node_id]; const b = pos[e.to_node_id];
    if (!a || !b) return null;
    const sx = a.x + CARD_W / 2; const sy = a.y + CARD_H / 2;
    const ex = b.x + CARD_W / 2; const ey = b.y + CARD_H / 2;
    return { id: e.id, d: `M ${sx} ${sy} C ${(sx + ex) / 2} ${sy}, ${(sx + ex) / 2} ${ey}, ${ex} ${ey}`, color: EDGE_COLOR[e.line_type] || '#0091ca' };
  }).filter(Boolean), [edges, pos]);

  // department / site grouping frames
  const groupBy = settings?.group_by;
  const frames = useMemo(() => {
    if (groupBy !== 'department' && groupBy !== 'site') return [];
    const groups = {};
    nodes.forEach((n) => {
      const key = groupBy === 'department' ? (n.department || 'Unassigned') : (n.site_name || 'No site');
      const p = pos[n.id]; if (!p) return;
      const g = groups[key] || { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity, count: 0 };
      g.minX = Math.min(g.minX, p.x); g.minY = Math.min(g.minY, p.y);
      g.maxX = Math.max(g.maxX, p.x + CARD_W); g.maxY = Math.max(g.maxY, p.y + CARD_H);
      g.count += 1; groups[key] = g;
    });
    const PAD = 22;
    return Object.entries(groups).filter(([, g]) => g.count > 0 && isFinite(g.minX)).map(([key, g]) => ({
      key, color: deptColor(key),
      x: g.minX - PAD, y: g.minY - PAD - 18, w: g.maxX - g.minX + PAD * 2, h: g.maxY - g.minY + PAD * 2 + 18,
    }));
  }, [groupBy, nodes, pos]);

  return (
    <div className="relative rounded-2xl overflow-hidden border" style={{ borderColor: 'var(--theme-border)', height: '64vh', minHeight: 460 }} data-testid="orgchart-canvas">
      {/* toolbar */}
      <div className="absolute top-3 left-3 z-30 flex gap-1.5">
        <ToolBtn onClick={onAddCard} title={t('orgchart.canvas_add_card', 'Add card')} testId="orgchart-toolbar-add"><Plus size={16} /></ToolBtn>
        <ToolBtn onClick={onAutoLayout} title={t('orgchart.canvas_autolayout', 'Auto-layout')} testId="orgchart-toolbar-autolayout"><Wand2 size={16} /></ToolBtn>
      </div>
      <div className="absolute top-3 right-3 z-30 flex gap-1.5">
        <ToolBtn onClick={() => zoom(1.15)} title={t('orgchart.canvas_zoom_in', 'Zoom in')} testId="orgchart-zoom-in"><ZoomIn size={16} /></ToolBtn>
        <ToolBtn onClick={() => zoom(0.87)} title={t('orgchart.canvas_zoom_out', 'Zoom out')} testId="orgchart-zoom-out"><ZoomOut size={16} /></ToolBtn>
        <ToolBtn onClick={fit} title={t('orgchart.canvas_fit', 'Fit to screen')} testId="orgchart-fit"><Maximize2 size={16} /></ToolBtn>
        <ToolBtn onClick={() => { setScale(0.8); setTx(80); setTy(40); }} title={t('orgchart.canvas_reset', 'Reset view')} testId="orgchart-reset"><RotateCcw size={16} /></ToolBtn>
      </div>
      <div className="absolute bottom-3 right-3 z-30 text-[10px] font-semibold px-2 py-1 rounded-md" style={{ background: 'var(--theme-surface)', color: 'var(--theme-text-muted)', border: '1px solid var(--theme-border)' }}>
        {Math.round(scale * 100)}%
      </div>

      {/* grid + canvas */}
      <div
        ref={wrapRef}
        className="absolute inset-0"
        style={{
          cursor: pan.current ? 'grabbing' : 'default', touchAction: 'none',
          background: settings?.show_grid
            ? 'radial-gradient(circle, rgba(100,116,139,0.18) 1px, transparent 1px)' : 'var(--theme-bg, #fbfcfe)',
          backgroundSize: settings?.show_grid ? `${24 * scale}px ${24 * scale}px` : undefined,
          backgroundPosition: settings?.show_grid ? `${tx}px ${ty}px` : undefined,
          backgroundColor: 'var(--theme-bg, #fbfcfe)',
        }}
        onPointerDown={onBgPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onWheel={onWheel}
      >
        <div style={{ position: 'absolute', left: 0, top: 0, transform: `translate(${tx}px, ${ty}px) scale(${scale})`, transformOrigin: '0 0' }}>
          {frames.map((f) => (
            <div key={f.key} className="absolute rounded-2xl" data-group-frame="1" data-testid={`orgchart-group-frame-${f.key}`} style={{ left: f.x, top: f.y, width: f.w, height: f.h, background: `${f.color}0d`, border: `1.5px dashed ${f.color}55`, zIndex: 1 }}>
              <span className="absolute -top-0.5 left-3 text-[11px] font-bold px-2 py-0.5 rounded-b-md" style={{ background: f.color, color: '#fff' }}>{f.key}</span>
            </div>
          ))}
          <svg style={{ position: 'absolute', left: 0, top: 0, overflow: 'visible', width: 1, height: 1, pointerEvents: 'none', zIndex: 5 }}>
            {paths.map((p) => (
              <path key={p.id} d={p.d} fill="none" stroke="#9a9fa1" strokeWidth={1.6} strokeOpacity={p.dim ? 0.15 : 0.6} />
            ))}
            {edgePaths.map((p) => (
              <path key={p.id} d={p.d} fill="none" stroke={p.color} strokeWidth={1.6} strokeDasharray="5 4" strokeOpacity={0.7} />
            ))}
          </svg>
          {nodes.map((n) => {
            const p = pos[n.id] || { x: n.x, y: n.y };
            const dim = dimmedIds.has(n.id);
            return (
              <div key={n.id} style={{ opacity: dim ? 0.22 : 1, pointerEvents: dim ? 'none' : 'auto' }}>
                <OrgCard
                  node={{ ...n, x: p.x, y: p.y }}
                  toggles={toggles}
                  reportsCount={reportsCount[n.id] || 0}
                  selected={selected === n.id || hoverTarget === n.id}
                  dragging={drag.current?.id === n.id}
                  onPointerDown={(e) => onCardPointerDown(e, n)}
                  onOpen={onOpenNode}
                />
              </div>
            );
          })}
        </div>
      </div>

      {!nodes.length && (
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 text-center px-6 z-20">
          <Crosshair size={26} style={{ color: 'var(--theme-text-muted)' }} />
          <p className="text-sm font-semibold" style={{ color: 'var(--theme-text)' }}>{t('orgchart.canvas_no_cards', 'No cards yet')}</p>
          <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('orgchart.canvas_no_cards_hint', 'Add a card or sync your staff to start building.')}</p>
        </div>
      )}
    </div>
  );
}

/** Org Chart Builder — orchestrator (Operations → Staffing → Org Chart).
 *
 * Sub-tabs: Org Chart (canvas) · List View · Vacancies · Import/Export · Settings.
 * Links to existing staff_members; never duplicates them. */
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { toPng } from 'html-to-image';
import jsPDF from 'jspdf';
import {
  Network, List, UserPlus, FileUp, Settings as SettingsIcon, Search,
  Loader2, RefreshCw, Plus, X, Sparkles, LayoutTemplate, History, Presentation as PresentIcon, Share2,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ocApi } from './api';
import { computeLayout } from './layout';
import Canvas from './Canvas';
import ListView from './ListView';
import Vacancies from './Vacancies';
import ImportExport from './ImportExport';
import Settings from './Settings';
import AIPanel from './AIPanel';
import HistoryTab from './HistoryTab';
import Templates from './Templates';
import PresentationMode from './Presentation';
import ShareModal from './ShareModal';
import { AddNodeModal, NodeDrawer, MoveConfirmModal } from './panels';

const STAFF_API = `${process.env.REACT_APP_BACKEND_URL}/api/staffing/staff`;
const SUBTABS = [
  { id: 'chart', label: 'Org Chart', icon: Network },
  { id: 'list', label: 'List View', icon: List },
  { id: 'vacancies', label: 'Vacancies', icon: UserPlus },
  { id: 'ai', label: 'AI Assist', icon: Sparkles },
  { id: 'templates', label: 'Templates', icon: LayoutTemplate },
  { id: 'history', label: 'History', icon: History },
  { id: 'import', label: 'Import / Export', icon: FileUp },
  { id: 'settings', label: 'Settings', icon: SettingsIcon },
];

function StatChip({ label, value, warn, sid }) {
  return (
    <div className="rounded-xl border px-3 py-2 min-w-[88px]" style={{ borderColor: warn && value > 0 ? '#fcd34d' : 'var(--theme-border)', background: warn && value > 0 ? '#fffbeb' : 'transparent' }} data-testid={`orgchart-stat-${sid}`}>
      <div className="text-lg font-bold leading-none" style={{ color: warn && value > 0 ? '#b45309' : 'var(--theme-text)' }}>{value}</div>
      <div className="text-[9px] uppercase tracking-wide mt-1" style={{ color: 'var(--theme-text-muted)' }}>{label}</div>
    </div>
  );
}

export default function OrgChartTab() {
  const { t } = useTranslation();
  const headers = useMemo(() => ({ Authorization: `Bearer ${localStorage.getItem('token')}` }), []);
  const [loading, setLoading] = useState(true);
  const [charts, setCharts] = useState([]);
  const [chartId, setChartId] = useState(null);
  const [chart, setChart] = useState(null);
  const [nodes, setNodes] = useState([]);
  const [edges, setEdges] = useState([]);
  const [sites, setSites] = useState([]);
  const [insights, setInsights] = useState(null);
  const [staffOptions, setStaffOptions] = useState([]);
  const [sub, setSub] = useState('chart');
  const [search, setSearch] = useState('');
  const [focusId, setFocusId] = useState(null);
  const [presenting, setPresenting] = useState(false);
  const [fitSignal, setFitSignal] = useState(0);
  const [filter, setFilter] = useState({ department: '', site: '', type: '', flag: '' });
  const [addOpen, setAddOpen] = useState(false);
  const [editNode, setEditNode] = useState(null);
  const [moveData, setMoveData] = useState(null);
  const [sharing, setSharing] = useState(false);

  const byId = useMemo(() => Object.fromEntries(nodes.map((n) => [n.id, n])), [nodes]);
  const departments = useMemo(() => [...new Set(nodes.map((n) => n.department).filter(Boolean))].sort(), [nodes]);

  const loadStaff = useCallback(async () => {
    try {
      const r = await axios.get(STAFF_API, { headers });
      setStaffOptions(r.data.staff || []);
    } catch { /* non-fatal */ }
  }, [headers]);

  const loadChart = useCallback(async (cid) => {
    const data = await ocApi.getChart(cid);
    setChart(data.chart);
    setNodes(data.nodes || []);
    setEdges(data.edges || []);
    setSites(data.sites || []);
    ocApi.insights(cid).then(setInsights).catch(() => {});
  }, []);

  const boot = useCallback(async () => {
    setLoading(true);
    try {
      let { charts: list } = await ocApi.listCharts();
      if (!list.length) {
        const c = await ocApi.createChart({ name: 'Organisation Chart', auto_build: true });
        list = [c];
      }
      setCharts(list);
      const saved = localStorage.getItem('orgchart.activeId');
      const active = list.find((c) => c.id === saved) ? saved : list[0].id;
      setChartId(active);
      await loadChart(active);
      loadStaff();
    } catch (e) {
      toast.error(t('orgchart.could_not_load', 'Could not load org charts'));
    } finally { setLoading(false); }
  }, [loadChart, loadStaff]);

  useEffect(() => { boot(); }, [boot]);
  useEffect(() => { if (chartId) localStorage.setItem('orgchart.activeId', chartId); }, [chartId]);

  const reload = useCallback(() => { if (chartId) { loadChart(chartId); loadStaff(); } }, [chartId, loadChart, loadStaff]);

  const switchChart = async (cid) => { setChartId(cid); setLoading(true); await loadChart(cid); setLoading(false); };

  const newChart = async () => {
    const c = await ocApi.createChart({ name: `Chart ${charts.length + 1}`, auto_build: true });
    const { charts: list } = await ocApi.listCharts();
    setCharts(list);
    await switchChart(c.id);
    toast.success(t('orgchart.chart_created', 'Chart created'));
  };

  const syncStaff = async () => {
    const r = await ocApi.syncStaff(chartId);
    await reload();
    toast.success(r.added ? t('orgchart.staff_added', 'Added {{count}} staff', { count: r.added }) : t('orgchart.up_to_date', 'Already up to date'));
  };

  // ─── node ops ───
  const createNode = async (body) => { await ocApi.createNode(chartId, body); await reload(); toast.success(t('orgchart.card_added', 'Card added')); };
  const updateNode = async (nid, body) => {
    try { const updated = await ocApi.updateNode(chartId, nid, body); setNodes((ns) => ns.map((n) => (n.id === nid ? { ...n, ...updated } : n))); ocApi.insights(chartId).then(setInsights).catch(() => {}); return updated; } catch (e) { toast.error(e?.response?.data?.detail || t('orgchart.update_failed', 'Update failed')); throw e; }
  };
  const moveNode = async (nid, posPatch) => { ocApi.updateNode(chartId, nid, posPatch).catch(() => {}); setNodes((ns) => ns.map((n) => (n.id === nid ? { ...n, ...posPatch } : n))); };
  const deleteNode = async (nid) => { await ocApi.deleteNode(chartId, nid); setEditNode(null); await reload(); toast.success(t('orgchart.card_removed', 'Card removed')); };

  const requestSetManager = (childId, managerId) => {
    const child = byId[childId]; const mgr = byId[managerId];
    setMoveData({ childId, managerId, childName: child?.full_name, managerName: mgr?.full_name, hasStaffLink: !!child?.staff_id });
  };
  const chooseMove = async (choice) => {
    if (choice === 'cancel') { setMoveData(null); return; }
    const { childId, managerId } = moveData;
    try {
      await updateNode(childId, { manager_node_id: managerId, write_back_staff: choice === 'update' });
      toast.success(choice === 'update' ? t('orgchart.line_staff_updated', 'Reporting line + staff record updated') : t('orgchart.line_updated', 'Reporting line updated'));
    } catch { /* handled */ }
    setMoveData(null);
  };

  const autoLayout = async () => {
    const laid = computeLayout(nodes, chart?.settings?.layout || 'vertical');
    setNodes(laid);
    toast.success(t('orgchart.auto_arranged', 'Auto-arranged'));
    await Promise.all(laid.map((n) => ocApi.updateNode(chartId, n.id, { x: Math.round(n.x), y: Math.round(n.y) }).catch(() => {})));
  };

  const saveSettings = async (settings) => { const r = await ocApi.updateChart(chartId, { settings }); setChart(r); };
  const renameChart = async (name) => { const r = await ocApi.updateChart(chartId, { name }); setChart(r); setCharts((cs) => cs.map((c) => (c.id === chartId ? { ...c, name } : c))); toast.success(t('orgchart.renamed', 'Renamed')); };
  const deleteChart = async () => {
    await ocApi.deleteChart(chartId);
    const { charts: list } = await ocApi.listCharts();
    if (!list.length) { await boot(); } else { setCharts(list); await switchChart(list[0].id); }
    setSub('chart');
    toast.success(t('orgchart.chart_deleted', 'Chart deleted'));
  };

  // ─── export ───
  // The export buttons live on the Import/Export tab, where the canvas is NOT
  // mounted. Switch to the chart tab, fit the whole chart into view, then
  // capture — so PNG/PDF always have a fully-rendered canvas to grab.
  const prepareCanvas = async () => {
    if (sub !== 'chart') setSub('chart');
    setFitSignal((n) => n + 1);
    await new Promise((r) => setTimeout(r, 600)); // mount + fit + transition
    const el = document.querySelector('[data-testid="orgchart-canvas"]');
    if (!el) throw new Error('no canvas');
    return el;
  };
  const captureCanvas = async () => {
    const el = await prepareCanvas();
    // skipFonts avoids html-to-image rejecting on cross-origin @font-face fetches.
    return toPng(el, { backgroundColor: '#ffffff', pixelRatio: 2, cacheBust: true, skipFonts: true });
  };
  const exportImage = async () => {
    try { const url = await captureCanvas(); const a = document.createElement('a'); a.href = url; a.download = `${chart?.name || 'org-chart'}.png`; a.click(); toast.success(t('orgchart.png_exported', 'PNG exported')); }
    catch (e) { console.error('orgchart PNG export failed', e); toast.error(t('orgchart.export_failed', 'Export failed')); }
  };
  const exportPdf = async () => {
    try {
      const url = await captureCanvas();
      const img = new Image(); img.src = url;
      await new Promise((res) => { img.onload = res; });
      const pdf = new jsPDF({ orientation: 'landscape', unit: 'pt', format: 'a4' });
      const pw = pdf.internal.pageSize.getWidth(); const ph = pdf.internal.pageSize.getHeight();
      pdf.setFontSize(14); pdf.text(chart?.name || 'Organisation Chart', 30, 30);
      pdf.setFontSize(8); pdf.text(new Date().toLocaleString(), 30, 44);
      const ratio = Math.min((pw - 60) / img.width, (ph - 80) / img.height);
      pdf.addImage(url, 'PNG', 30, 60, img.width * ratio, img.height * ratio);
      pdf.save(`${chart?.name || 'org-chart'}.pdf`);
      toast.success(t('orgchart.pdf_exported', 'PDF exported'));
    } catch (e) { console.error('orgchart PDF export failed', e); toast.error(t('orgchart.export_failed', 'Export failed')); }
  };

  // ─── filter / search ───
  const matchesFilter = useCallback((n) => {
    if (filter.department && n.department !== filter.department) return false;
    if (filter.site && n.site_id !== filter.site) return false;
    if (filter.type && n.type !== filter.type) return false;
    if (filter.flag === 'vacancies' && n.type !== 'vacancy') return false;
    if (filter.flag === 'engineers' && !n.is_engineer) return false;
    if (filter.flag === 'no_manager' && (n.manager_node_id || n.type === 'vacancy')) return false;
    if (filter.flag === 'no_site' && n.site_id) return false;
    return true;
  }, [filter]);
  const dimmedIds = useMemo(() => {
    const set = new Set();
    const active = filter.department || filter.site || filter.type || filter.flag;
    if (active) nodes.forEach((n) => { if (!matchesFilter(n)) set.add(n.id); });
    return set;
  }, [nodes, filter, matchesFilter]);

  const runSearch = (e) => {
    e?.preventDefault();
    const q = search.trim().toLowerCase();
    if (!q) return;
    const hit = nodes.find((n) => [n.full_name, n.job_title, n.department, n.site_name, n.email].some((f) => (f || '').toLowerCase().includes(q)));
    if (hit) { setSub('chart'); setFocusId(null); setTimeout(() => setFocusId(hit.id), 30); }
    else toast.error(t('orgchart.no_match', 'No match found'));
  };

  if (loading) {
    return <div className="py-16 flex items-center justify-center gap-2 text-sm" style={{ color: 'var(--theme-text-muted)' }} data-testid="orgchart-loading"><Loader2 size={16} className="animate-spin" /> {t('orgchart.loading', 'Loading org chart…')}</div>;
  }

  return (
    <div className="space-y-4" data-testid="orgchart-tab">
      {/* chart picker + actions */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <select value={chartId || ''} onChange={(e) => switchChart(e.target.value)} className="px-3 py-2 rounded-lg text-sm font-semibold border outline-none" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg,#fff)', color: 'var(--theme-text)' }} data-testid="orgchart-chart-select">
            {charts.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          <button onClick={newChart} title={t('orgchart.new_chart', 'New chart')} className="w-9 h-9 rounded-lg inline-flex items-center justify-center border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }} data-testid="orgchart-new-chart"><Plus size={16} /></button>
        </div>
        <div className="flex items-center gap-2">
          <form onSubmit={runSearch} className="relative">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2" style={{ color: 'var(--theme-text-muted)' }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={t('orgchart.search_people', 'Search people…')} className="pl-8 pr-3 py-2 rounded-lg text-sm border outline-none w-44" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg,#fff)', color: 'var(--theme-text)' }} data-testid="orgchart-search" />
          </form>
          <button onClick={() => setSharing(true)} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border" style={chart?.is_public ? { borderColor: '#16a34a', color: '#16a34a' } : { borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="orgchart-share"><Share2 size={13} /> {chart?.is_public ? t('orgchart.shared', 'Shared') : t('orgchart.share', 'Share')}</button>
          <button onClick={() => setPresenting(true)} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="orgchart-present"><PresentIcon size={13} /> {t('orgchart.present', 'Present')}</button>
          <button onClick={syncStaff} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="orgchart-sync"><RefreshCw size={13} /> {t('orgchart.sync_staff', 'Sync staff')}</button>
        </div>
      </div>

      {/* insights */}
      {insights && (
        <div className="flex flex-wrap gap-2" data-testid="orgchart-insights">
          <StatChip sid="people" label={t('orgchart.stat_people', 'People')} value={insights.total_people} />
          <StatChip sid="managers" label={t('orgchart.stat_managers', 'Managers')} value={insights.total_managers} />
          <StatChip sid="engineers" label={t('orgchart.stat_engineers', 'Engineers')} value={insights.total_engineers} />
          <StatChip sid="open-roles" label={t('orgchart.stat_open_roles', 'Open roles')} value={insights.open_vacancies} />
          <StatChip sid="departments" label={t('orgchart.stat_departments', 'Departments')} value={insights.departments} />
          <StatChip sid="avg-reports" label={t('orgchart.stat_avg_reports', 'Avg reports')} value={insights.avg_direct_reports} />
          <StatChip sid="no-manager" label={t('orgchart.stat_no_manager', 'No manager')} value={insights.staff_without_manager} warn />
          <StatChip sid="no-site" label={t('orgchart.stat_no_site', 'No site')} value={insights.staff_without_site} warn />
        </div>
      )}

      {/* sub-nav */}
      <div className="flex items-center gap-1.5 flex-wrap border-b pb-2" style={{ borderColor: 'var(--theme-border)' }}>
        {SUBTABS.map(({ id, label, icon: Icon }) => (
          <button key={id} onClick={() => setSub(id)} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors" style={sub === id ? { background: 'rgba(25,205,255,0.12)', color: 'var(--color-brand-cyan)' } : { color: 'var(--theme-text-muted)' }} data-testid={`orgchart-subtab-${id}`}>
            <Icon size={13} /> {t(`orgchart.subtab_${id}`, label)}
          </button>
        ))}
      </div>

      {/* filters (chart + list only) */}
      {(sub === 'chart' || sub === 'list') && (
        <div className="flex flex-wrap items-center gap-2" data-testid="orgchart-filters">
          <select value={filter.department} onChange={(e) => setFilter({ ...filter, department: e.target.value })} className="px-2 py-1.5 rounded-lg text-xs border outline-none" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg,#fff)', color: 'var(--theme-text)' }} data-testid="orgchart-filter-dept">
            <option value="">{t('orgchart.all_departments', 'All departments')}</option>
            {departments.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>
          {!!sites.length && (
            <select value={filter.site} onChange={(e) => setFilter({ ...filter, site: e.target.value })} className="px-2 py-1.5 rounded-lg text-xs border outline-none" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg,#fff)', color: 'var(--theme-text)' }} data-testid="orgchart-filter-site">
              <option value="">{t('orgchart.all_sites', 'All sites')}</option>
              {sites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          )}
          <select value={filter.flag} onChange={(e) => setFilter({ ...filter, flag: e.target.value })} className="px-2 py-1.5 rounded-lg text-xs border outline-none" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg,#fff)', color: 'var(--theme-text)' }} data-testid="orgchart-filter-flag">
            <option value="">{t('orgchart.everyone', 'Everyone')}</option>
            <option value="vacancies">{t('orgchart.vacancies_only', 'Vacancies only')}</option>
            <option value="engineers">{t('orgchart.engineers_only', 'Engineers only')}</option>
            <option value="no_manager">{t('orgchart.missing_manager', 'Missing manager')}</option>
            <option value="no_site">{t('orgchart.missing_site', 'Missing site')}</option>
          </select>
          {(filter.department || filter.site || filter.type || filter.flag) && (
            <button onClick={() => setFilter({ department: '', site: '', type: '', flag: '' })} className="inline-flex items-center gap-1 text-xs font-semibold px-2 py-1.5 rounded-lg" style={{ color: 'var(--color-brand-cyan)' }} data-testid="orgchart-filter-clear"><X size={12} /> {t('orgchart.clear', 'Clear')}</button>
          )}
        </div>
      )}

      {/* content */}
      {sub === 'chart' && (
        <Canvas
          nodes={nodes}
          edges={edges}
          settings={chart?.settings}
          dimmedIds={dimmedIds}
          focusId={focusId}
          fitSignal={fitSignal}
          onMoveNode={moveNode}
          onRequestSetManager={requestSetManager}
          onOpenNode={(n) => setEditNode(n)}
          onAutoLayout={autoLayout}
          onAddCard={() => setAddOpen(true)}
        />
      )}
      {sub === 'list' && <ListView nodes={nodes.filter(matchesFilter)} byId={byId} onOpen={(n) => setEditNode(n)} />}
      {sub === 'vacancies' && <Vacancies nodes={nodes} byId={byId} onOpen={(n) => setEditNode(n)} onAdd={() => setAddOpen(true)} onUpdate={updateNode} />}
      {sub === 'ai' && <AIPanel chartId={chartId} onImported={reload} />}
      {sub === 'templates' && <Templates chartId={chartId} onApplied={reload} />}
      {sub === 'history' && <HistoryTab chartId={chartId} onRestored={reload} />}
      {sub === 'import' && <ImportExport chartId={chartId} onImported={reload} onExportImage={exportImage} onExportPdf={exportPdf} />}
      {sub === 'settings' && chart && <Settings chart={chart} onSave={saveSettings} onRename={renameChart} onDelete={deleteChart} />}

      {/* modals */}
      <AddNodeModal open={addOpen} onClose={() => setAddOpen(false)} onCreate={createNode} staffOptions={staffOptions.filter((s) => !nodes.some((n) => n.staff_id === s.id))} sites={sites} departments={departments} />
      <NodeDrawer node={editNode} onClose={() => setEditNode(null)} onSave={updateNode} onDelete={deleteNode} sites={sites} nodes={nodes} departments={departments} chartId={chartId} edges={edges} onEdgesChanged={reload} />
      <MoveConfirmModal data={moveData} onChoose={chooseMove} onClose={() => setMoveData(null)} />
      {presenting && <PresentationMode nodes={nodes} byId={byId} onClose={() => setPresenting(false)} />}
      {sharing && chart && <ShareModal chart={chart} onClose={() => setSharing(false)} onChanged={reload} />}
    </div>
  );
}

/** Org Chart — presentation mode (clean, full-screen, section-by-section). */
import { useEffect, useMemo, useState } from 'react';
import { createPortal } from 'react-dom';
import { X, ChevronLeft, ChevronRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { deptColor, humanize } from './api';

function PCard({ n }) {
  const { t } = useTranslation();
  const accent = n.type === 'vacancy' ? '#f59e0b' : deptColor(n.department);
  return (
    <div className="rounded-2xl px-4 py-3 min-w-[180px]" style={{ background: 'rgba(255,255,255,0.06)', borderLeft: `4px solid ${accent}`, backdropFilter: 'blur(8px)' }}>
      <div className="text-sm font-bold" style={{ color: '#ffffff' }}>{n.full_name}</div>
      <div className="text-xs" style={{ color: 'rgba(255,255,255,0.65)' }}>{humanize(n.job_title) || (n.type === 'vacancy' ? t('orgchart.open_role', 'Open role') : '')}</div>
      {n.department && <div className="text-[10px] mt-1 font-semibold" style={{ color: accent }}>{n.department}</div>}
    </div>
  );
}

export default function Presentation({ nodes, byId, onClose }) {
  const { t } = useTranslation();
  const [i, setI] = useState(0);

  const slides = useMemo(() => {
    const roots = nodes.filter((n) => !n.manager_node_id);
    const depts = [...new Set(nodes.map((n) => n.department).filter(Boolean))].sort();
    const vacancies = nodes.filter((n) => n.type === 'vacancy');
    const out = [{ title: t('orgchart.present_org', 'Organisation'), subtitle: t('orgchart.present_people_depts', '{{people}} people · {{depts}} departments', { people: nodes.length, depts: depts.length }), nodes: roots }];
    depts.forEach((d) => out.push({ title: d, subtitle: t('orgchart.present_department', 'Department'), nodes: nodes.filter((n) => n.department === d) }));
    if (vacancies.length) out.push({ title: t('orgchart.present_open_roles', 'Open roles'), subtitle: t('orgchart.present_vacancies', '{{count}} vacancies', { count: vacancies.length }), nodes: vacancies });
    return out;
  }, [nodes, t]);

  useEffect(() => {
    const h = (e) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') setI((x) => Math.min(slides.length - 1, x + 1));
      if (e.key === 'ArrowLeft') setI((x) => Math.max(0, x - 1));
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, [slides.length, onClose]);

  const slide = slides[Math.min(i, slides.length - 1)];

  return createPortal(
    <div className="fixed inset-0 z-[2000] flex flex-col" style={{ background: 'linear-gradient(160deg, #0a1530 0%, #0f1f3d 100%)' }} data-testid="orgchart-presentation">
      <div className="flex items-center justify-between px-8 py-5">
        <div>
          <div className="text-2xl font-bold pulse-font-heading" style={{ color: '#ffffff' }}>{slide?.title}</div>
          <div className="text-sm" style={{ color: 'rgba(255,255,255,0.55)' }}>{slide?.subtitle}</div>
        </div>
        <button onClick={onClose} className="w-10 h-10 rounded-xl inline-flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.08)', color: 'rgba(255,255,255,0.8)' }} data-testid="orgchart-present-close"><X size={20} /></button>
      </div>

      <div className="flex-1 overflow-auto px-8 pb-8">
        <div className="flex flex-wrap gap-3 content-start">
          {(slide?.nodes || []).map((n) => <PCard key={n.id} n={n} />)}
          {!slide?.nodes?.length && <div className="text-sm" style={{ color: 'rgba(255,255,255,0.45)' }}>{t('orgchart.present_no_cards', 'No cards in this section.')}</div>}
        </div>
      </div>

      <div className="flex items-center justify-center gap-4 py-5">
        <button onClick={() => setI((x) => Math.max(0, x - 1))} disabled={i === 0} className="w-10 h-10 rounded-full inline-flex items-center justify-center disabled:opacity-30" style={{ background: 'rgba(255,255,255,0.1)', color: '#ffffff' }} data-testid="orgchart-present-prev"><ChevronLeft size={20} /></button>
        <div className="flex gap-1.5">
          {slides.map((_, idx) => <span key={idx} className="w-2 h-2 rounded-full" style={{ background: idx === i ? 'var(--color-brand-cyan, #19cdff)' : 'rgba(255,255,255,0.25)' }} />)}
        </div>
        <button onClick={() => setI((x) => Math.min(slides.length - 1, x + 1))} disabled={i === slides.length - 1} className="w-10 h-10 rounded-full inline-flex items-center justify-center disabled:opacity-30" style={{ background: 'rgba(255,255,255,0.1)', color: '#ffffff' }} data-testid="orgchart-present-next"><ChevronRight size={20} /></button>
      </div>
    </div>, document.body,
  );
}

/** Org Chart — publish & share a read-only public link. */
import { useState } from 'react';
import { createPortal } from 'react-dom';
import { toast } from 'sonner';
import {
  X, Share2, Link2, Copy, Check, RefreshCw, Globe, Lock, Loader2, ExternalLink,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ocApi } from './api';

const center = {
  position: 'fixed', inset: 0, zIndex: 1100, background: 'rgba(27, 28, 29,0.45)',
  display: 'flex', alignItems: 'center', justifyContent: 'center',
};
const box = {
  width: 'min(460px, 92vw)', borderRadius: 18, padding: 22,
  background: 'var(--theme-surface, #fff)', boxShadow: '0 20px 60px rgba(27, 28, 29,0.3)',
};

export default function ShareModal({ chart, onClose, onChanged }) {
  const { t } = useTranslation();
  const published = !!chart?.is_public;
  const [token, setToken] = useState(chart?.public_token || null);
  const [showContact, setShowContact] = useState(!!chart?.public_show_contact);
  const [busy, setBusy] = useState(false);
  const [copied, setCopied] = useState(false);
  const url = token ? ocApi.publicUrl(token) : '';

  const publish = async () => {
    setBusy(true);
    try { const r = await ocApi.publish(chart.id, showContact); setToken(r.public_token); toast.success(t('orgchart.share_ready', 'Public link ready')); onChanged?.(); }
    catch { toast.error(t('orgchart.share_pub_err', 'Could not publish')); } finally { setBusy(false); }
  };
  const unpublish = async () => {
    setBusy(true);
    try { await ocApi.unpublish(chart.id); setToken(null); toast.success(t('orgchart.share_disabled', 'Public link disabled')); onChanged?.(); }
    catch { toast.error(t('orgchart.share_unpub_err', 'Could not unpublish')); } finally { setBusy(false); }
  };
  const rotate = async () => {
    setBusy(true);
    try { const r = await ocApi.rotateLink(chart.id); setToken(r.public_token); toast.success(t('orgchart.share_rotated', 'New link generated — the old one no longer works')); onChanged?.(); }
    catch { toast.error(t('orgchart.share_rotate_err', 'Could not rotate')); } finally { setBusy(false); }
  };
  const toggleContact = async (next) => {
    setShowContact(next);
    if (token) { try { await ocApi.publish(chart.id, next); onChanged?.(); } catch { /* ignore */ } }
  };
  const copy = () => { navigator.clipboard.writeText(url); setCopied(true); toast.success(t('orgchart.share_copied', 'Link copied')); setTimeout(() => setCopied(false), 1500); };

  return createPortal(
    <div style={center} onMouseDown={onClose}>
      <div style={box} onMouseDown={(e) => e.stopPropagation()} data-testid="orgchart-share-modal">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-base font-bold pulse-font-heading inline-flex items-center gap-2" style={{ color: 'var(--theme-text)' }}><Share2 size={16} /> {t('orgchart.share_title', 'Share org chart')}</h3>
          <button onClick={onClose} data-testid="orgchart-share-close"><X size={18} style={{ color: 'var(--theme-text-muted)' }} /></button>
        </div>

        {!token ? (
          <div className="text-center py-2">
            <Globe size={26} className="mx-auto mb-2" style={{ color: 'var(--color-brand-cyan)' }} />
            <p className="text-sm font-semibold mb-1" style={{ color: 'var(--theme-text)' }}>{t('orgchart.share_publish_heading', 'Publish a read-only link')}</p>
            <p className="text-xs mb-4" style={{ color: 'var(--theme-text-muted)' }}>{t('orgchart.share_publish_desc', 'Anyone with the link can view the structure — no login needed. Emails, phones, notes and salary bands are never shared unless you opt in.')}</p>
            <label className="flex items-center justify-center gap-2 text-xs mb-4" style={{ color: 'var(--theme-text)' }}>
              <input type="checkbox" checked={showContact} onChange={(e) => setShowContact(e.target.checked)} data-testid="orgchart-share-contact" /> {t('orgchart.share_show_contact', 'Also show email & phone on cards')}
            </label>
            <button onClick={publish} disabled={busy} className="w-full py-2.5 rounded-lg text-sm font-bold inline-flex items-center justify-center gap-2 disabled:opacity-50" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }} data-testid="orgchart-share-publish">
              {busy ? <Loader2 size={15} className="animate-spin" /> : <Globe size={15} />} {t('orgchart.share_publish_btn', 'Publish link')}
            </button>
          </div>
        ) : (
          <div>
            <div className="inline-flex items-center gap-1.5 text-[11px] font-semibold px-2.5 py-1 rounded-full mb-3" style={{ background: 'rgba(22,163,74,0.12)', color: '#16a34a' }}>
              <Globe size={12} /> {t('orgchart.share_live', 'Live — anyone with the link can view')}
            </div>
            <div className="flex items-center gap-2 rounded-lg border p-2 mb-3" style={{ borderColor: 'var(--theme-border)' }}>
              <Link2 size={14} style={{ color: 'var(--theme-text-muted)', flexShrink: 0 }} />
              <input readOnly value={url} className="flex-1 text-xs bg-transparent outline-none" style={{ color: 'var(--theme-text)' }} data-testid="orgchart-share-url" />
              <button onClick={copy} className="flex-shrink-0" data-testid="orgchart-share-copy">{copied ? <Check size={14} style={{ color: '#16a34a' }} /> : <Copy size={14} style={{ color: 'var(--color-brand-cyan)' }} />}</button>
            </div>
            <label className="flex items-center justify-between gap-2 text-xs mb-4 px-1" style={{ color: 'var(--theme-text)' }}>
              <span className="inline-flex items-center gap-1.5"><Lock size={12} style={{ color: 'var(--theme-text-muted)' }} /> {t('orgchart.share_show_contact_short', 'Show email & phone on cards')}</span>
              <input type="checkbox" checked={showContact} onChange={(e) => toggleContact(e.target.checked)} data-testid="orgchart-share-contact-live" />
            </label>
            <div className="flex flex-wrap gap-2">
              <a href={url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="orgchart-share-open"><ExternalLink size={13} /> {t('orgchart.share_open', 'Open')}</a>
              <button onClick={rotate} disabled={busy} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border disabled:opacity-50" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="orgchart-share-rotate"><RefreshCw size={13} /> {t('orgchart.share_new_link', 'New link')}</button>
              <button onClick={unpublish} disabled={busy} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold border disabled:opacity-50 ml-auto" style={{ borderColor: '#fca5a5', color: '#dc2626' }} data-testid="orgchart-share-unpublish"><Lock size={13} /> {t('orgchart.share_stop', 'Stop sharing')}</button>
            </div>
          </div>
        )}
      </div>
    </div>, document.body,
  );
}

