          <Eye size={12} />
          <span>Viewing {adminView === 'lite' ? 'Pulse Self-Service (Lite)' : 'Pulse Self-Service Pro'} as Admin{adminDemoRole ? ` — ${adminDemoRole.charAt(0).toUpperCase() + adminDemoRole.slice(1)} View` : ''}</span>
