const AIDirectorPanel = ({ API, headers, entitlement, seedBriefId, onSeedConsumed }) => {
  const { t } = useTranslation();
  const [presets, setPresets] = useState({ tones: FALLBACK_TONES, goals: FALLBACK_GOALS, channels: [] });
  const [recentBriefs, setRecentBriefs] = useState([]);

  const [prompt, setPrompt] = useState('');
  const [goal, setGoal] = useState('');
  const [tone, setTone] = useState('high_energy');
  const [audienceHint, setAudienceHint] = useState('');
  const [brandLock, setBrandLock] = useState(true);
  const [resPreset, setResPreset] = useState('1080x1350');
  const [segmentKeys, setSegmentKeys] = useState([]);

  const [busy, setBusy] = useState(false);
  const [refineBusy, setRefineBusy] = useState(false);
  const [brief, setBrief] = useState(null);
  const [autoPilot, setAutoPilot] = useState(false);
  const [perRecipient, setPerRecipient] = useState(false);
  const [optimalWindow, setOptimalWindow] = useState(null);
  const [coverage, setCoverage] = useState(null);

  // Phase 7 — fetch the org's optimal send window for autopilot UX hints
  useEffect(() => {
    (async () => {
      try {
        const [w, c] = await Promise.all([
          axios.get(`${API}/api/marketing/creative/director/optimal-window`, { headers }),
          axios.get(`${API}/api/marketing/creative/director/per-recipient-coverage`, { headers }),
        ]);
        setOptimalWindow(w.data);
        setCoverage(c.data);
      } catch { /* soft-fail */ }
    })();
  }, [API, headers]);

  const locked = entitlement && !entitlement.features?.ai_creative_studio;

  useEffect(() => {
    (async () => {
      try {
        const [presetsR, briefsR] = await Promise.all([
          axios.get(`${API}/api/marketing/creative/director/presets`, { headers }),
          axios.get(`${API}/api/marketing/creative/director/briefs`, { headers }),
        ]);
        setPresets(presetsR.data || {});
        setRecentBriefs(briefsR.data?.briefs || []);
      } catch (e) {
        // soft-fail; the form still works
      }
    })();
  }, [API, headers]);

  // Phase 4 — load a seeded brief from the legacy Single-Asset tab
  useEffect(() => {
    if (seedBriefId) {
      loadBrief(seedBriefId);
      onSeedConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: reviewed in iter 216h226-deps-walk — effect either runs once on mount or re-fires on the listed trigger deps; omitted refs are stable identities or fetcher closures that read live state at call time, so including them would re-fire without changing semantics.
  }, [seedBriefId]);

  // Dedup — accept a seed prompt forwarded from the floating AI Assistant
  useEffect(() => {
    const handler = (e) => {
      const seedPrompt = e?.detail?.prompt;
      if (seedPrompt) {
        setPrompt(seedPrompt);
        setBrief(null);
        const el = document.querySelector('[data-testid="director-prompt-input"]');
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        notify.success(t('mkt.dir_seed_prompt', 'Prompt brought across from AI Assistant — review and hit Generate'));
      }
    };
    window.addEventListener('director:seed-prompt', handler);
    return () => window.removeEventListener('director:seed-prompt', handler);
  }, []);

  const resolution = useMemo(() => {
    const [w, h] = resPreset.split('x').map((n) => parseInt(n, 10));
    return { w, h };
  }, [resPreset]);

  const generate = async () => {
    if (!prompt.trim()) {
      notify.error(t('mkt.dir_err_prompt', 'Tell the Director what to promote'));
      return;
    }
    setBusy(true);
    setBrief(null);
    try {
      const r = await axios.post(`${API}/api/marketing/creative/director/build`, {
        prompt, goal, tone, audience_hint: audienceHint, brand_lock: brandLock,
        resolution, segment_keys: segmentKeys,
      }, { headers, timeout: 240000 });
      setBrief(r.data);
      notify.success(t('mkt.dir_draft_ready', 'Director draft ready — review and refine'));
      const list = await axios.get(`${API}/api/marketing/creative/director/briefs`, { headers });
      setRecentBriefs(list.data?.briefs || []);
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dir_build_err', 'Director failed — please try again'));
    }
    setBusy(false);
  };

  const refine = async (instruction, channel = null, regenerateImage = false) => {
    if (!brief?.id) return;
    setRefineBusy(true);
    try {
      const r = await axios.post(`${API}/api/marketing/creative/director/refine`, {
        brief_id: brief.id, instruction, channel, regenerate_image: regenerateImage,
      }, { headers, timeout: 120000 });
      setBrief(r.data);
      notify.success(t('mkt.dir_refined', 'Refined'));
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dir_refine_err', 'Refine failed'));
    }
    setRefineBusy(false);
  };

  const launchAsCampaign = async () => {
    if (!brief?.id) return;
    try {
      const r = await axios.post(
        `${API}/api/marketing/creative/director/briefs/${brief.id}/launch`,
        { auto_pilot: autoPilot, auto_post_mortem: true, per_recipient_timing: perRecipient },
        { headers },
      );
      const note = r.data?.scheduled_for
        ? t('mkt.dir_scheduled', 'Scheduled for {{w}}', { w: optimalWindow?.label || t('mkt.dir_optimal_window', 'optimal window') })
        : (r.data?.already_launched ? t('mkt.dir_already_launched', 'Already launched as a campaign') : t('mkt.dir_campaign_created', 'Campaign created — find it on the Campaigns tab'));
      notify.success(note);
      setBrief({ ...brief, campaign_id: r.data.campaign_id, scheduled_for: r.data.scheduled_for });
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dir_launch_err', 'Launch failed'));
    }
  };

  const loadBrief = async (id) => {
    setBusy(true);
    try {
      const r = await axios.get(`${API}/api/marketing/creative/director/briefs/${id}`, { headers });
      setBrief(r.data);
    } catch {
      notify.error(t('mkt.dir_load_err', 'Could not load brief'));
    }
    setBusy(false);
  };

  if (locked) {
    return (
      <div className="rounded-xl border border-amber-200 dark:border-amber-700 bg-amber-50 dark:bg-amber-950/40 p-6 text-center" data-testid="ai-director-locked">
        <Lock className="mx-auto text-amber-500 mb-2" size={28} />
        <h2 className="text-lg font-bold text-zinc-900 dark:text-zinc-100">{t('mkt.dir_locked_title', 'AI Creative Director is a Pro feature')}</h2>
        <p className="text-sm text-zinc-600 dark:text-zinc-400 mt-1">{t('mkt.dir_locked_body', 'Upgrade to Pro to generate full campaigns from a single prompt.')}</p>
      </div>
    );
  }

  return (
    <div className="space-y-4" data-testid="ai-director-panel">

      {/* ── Prompt hero ───────────────────────────────────────────── */}
      <div className="rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-gradient-to-br from-white via-white to-blue-50/30 dark:from-zinc-900 dark:via-zinc-900 dark:to-blue-950/10 p-5 shadow-sm">
        <div className="flex items-center gap-2 mb-3">
          <Sparkles className="text-[var(--color-brand-blue)]" size={18} />
          <h2 className="text-lg font-bold text-zinc-900 dark:text-zinc-100">{t('mkt.dir_title', 'AI Creative Director')}</h2>
          <span className="ml-2 text-[10px] uppercase tracking-wider px-1.5 py-0.5 rounded bg-[rgb(var(--rgb-brand-blue)/0.1)] text-[var(--color-brand-blue)]">{t('mkt.dir_phase', 'Phase 1')}</span>
        </div>
        <p className="text-xs text-zinc-500 dark:text-zinc-400 mb-3">
          {t('mkt.dir_desc', 'One prompt → full campaign. Strategy, multi-format copy (email/IG/FB/SMS/push), and a branded Gemini poster — under 60 seconds.')}
        </p>

        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder={t('mkt.dir_prompt_ph', 'e.g. Promote Saturday morning spin classes to members who have not attended in 30+ days')}
          rows={3}
          className="w-full px-3 py-2.5 border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 rounded-lg text-sm focus:outline-none focus:border-[var(--color-brand-blue)] resize-none"
          data-testid="director-prompt-input"
        />

        {/* ── Quick-start templates (Iter 216h113i) ──────────────────
            Pre-built campaigns that customers can launch with one click.
            They pre-fill the prompt + goal + tone so the AI generates a
            poster using the customer's saved brand kit immediately. */}
        <div className="mt-3">
          <p className="text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 mb-1.5 font-semibold flex items-center gap-1">
            <Sparkles size={10}/> {t('mkt.dir_quickstart', 'Quick-start templates')} <span className="text-[9px] font-normal text-zinc-400">— {t('mkt.dir_quickstart_hint', 'one click, brand-kit applied')}</span>
          </p>
          <div className="flex flex-wrap gap-1.5">
            {QUICKSTART_TEMPLATES.map((qs) => (
              <button
                key={qs.id}
                type="button"
                onClick={() => {
                  setPrompt(qs.prompt);
                  setGoal(qs.goal);
                  setTone(qs.tone);
                  if (qs.audience) setAudienceHint(qs.audience);
                }}
                title={t('mkt.dir_qs_' + qs.id + '_tagline', qs.tagline)}
                className="px-3 py-1.5 rounded-full text-[11px] font-semibold border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-950 text-zinc-700 dark:text-zinc-200 hover:border-[var(--color-brand-blue)] hover:text-[var(--color-brand-blue)] transition"
                data-testid={`director-quickstart-${qs.id}`}
              >
                {t('mkt.dir_qs_' + qs.id + '_label', qs.label)}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 mt-3">
          <Select label={t('mkt.dir_goal', 'Goal')} value={goal} onChange={setGoal} testId="director-goal"
            options={[{ key: '', label: t('mkt.dir_optional', '— optional —') }, ...(presets.goals || []).map((g) => ({ key: g.key, label: t('mkt.dir_goal_' + g.key, g.label) }))]} />
          <Select label={t('mkt.dir_tone', 'Tone')} value={tone} onChange={setTone} testId="director-tone"
            options={(presets.tones || []).map((tn) => ({ key: tn.key, label: t('mkt.dir_tone_' + tn.key, tn.label), hint: tn.hint }))} />
          <Select label={t('mkt.dir_resolution', 'Resolution')} value={resPreset} onChange={setResPreset} testId="director-resolution"
            options={[
              { key: '1080x1350', label: t('mkt.dir_res_ig_portrait', 'Instagram portrait (1080×1350)') },
              { key: '1080x1080', label: t('mkt.dir_res_square', 'Square (1080×1080)') },
              { key: '1080x1920', label: t('mkt.dir_res_story', 'Story / Reel (1080×1920)') },
              { key: '1200x628',  label: t('mkt.dir_res_fb', 'Facebook / email (1200×628)') },
              { key: '2480x3508', label: t('mkt.dir_res_a4', 'A4 print poster') },
            ]} />
          <div>
            <p className="text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 mb-1 font-semibold">{t('mkt.dir_brand_lock', 'Brand lock')}</p>
            <button onClick={() => setBrandLock((v) => !v)}
              className={`w-full px-2 py-2 rounded-md text-xs font-medium border ${
                brandLock
                  ? 'bg-[var(--color-brand-blue)] text-white border-[var(--color-brand-blue)]'
                  : 'bg-white dark:bg-zinc-950 text-zinc-600 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700'
              }`}
              data-testid="director-brand-lock">
              <Lock size={11} className="inline mr-1" />
              {brandLock ? t('mkt.dir_on', 'On') : t('mkt.dir_off', 'Off')}
            </button>
          </div>
        </div>

        <input
          value={audienceHint}
          onChange={(e) => setAudienceHint(e.target.value)}
          placeholder={t('mkt.dir_audience_ph', 'Audience hint (optional) — e.g. PT eligible, lapsed 30 days, family members')}
          className="w-full mt-3 px-3 py-2 border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 rounded-md text-xs focus:outline-none focus:border-[var(--color-brand-blue)]"
          data-testid="director-audience-hint"
        />

        {/* Phase 3 — segment chips */}
        <div className="mt-3">
          <p className="text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 mb-1.5 font-semibold flex items-center gap-1">
            <Users size={10}/> {t('mkt.dir_behaviour_variants', 'Behaviour-driven variants')} <span className="text-[9px] font-normal text-zinc-400">{t('mkt.dir_behaviour_hint', '(optional — generates per-segment copy)')}</span>
          </p>
          <div className="flex flex-wrap gap-1.5">
            {SEGMENT_OPTIONS.map((s) => {
              const active = segmentKeys.includes(s.key);
              return (
                <button key={s.key}
                  onClick={() => setSegmentKeys((arr) => active ? arr.filter(k => k !== s.key) : [...arr, s.key])}
                  title={t('mkt.dir_seg_' + s.key + '_hint', s.hint)}
                  className={`px-2 py-1 rounded-full text-[10px] font-medium border transition ${
                    active
                      ? 'bg-[var(--color-brand-blue)] text-white border-[var(--color-brand-blue)]'
                      : 'bg-white dark:bg-zinc-950 text-zinc-600 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:border-[var(--color-brand-blue)] hover:text-[var(--color-brand-blue)]'
                  }`}
                  data-testid={`director-segment-${s.key}`}>
                  {t('mkt.dir_seg_' + s.key + '_label', s.label)}
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex items-center justify-between mt-4">
          <p className="text-[10px] text-zinc-400 dark:text-zinc-500">
            {t('mkt.dir_powered', 'Powered by Claude Sonnet 4.5 + Gemini Nano Banana')}
          </p>
          <button onClick={generate} disabled={busy || !prompt.trim()}
            className="px-4 py-2 rounded-lg bg-[var(--color-brand-blue)] hover:bg-[var(--color-brand-blue-alt2)] disabled:bg-zinc-300 disabled:dark:bg-zinc-700 disabled:cursor-not-allowed text-white font-semibold text-sm flex items-center gap-2 transition shadow-sm"
            data-testid="director-generate-btn">
            {busy ? <><Loader2 size={14} className="animate-spin"/> {t('mkt.dir_directing', 'Directing campaign…')}</> : <><Sparkles size={14}/> {t('mkt.dir_generate', 'Generate Campaign')}</>}
          </button>
        </div>
      </div>

      {/* ── Recent briefs strip ─────────────────────────────────── */}
      {recentBriefs.length > 0 && !brief && (
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-3">
          <p className="text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 font-semibold mb-2">
            {t('mkt.dir_recent', 'Recent Director briefs')}
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
            {recentBriefs.slice(0, 6).map((b) => (
              <div key={b.id}
                className="group relative rounded-md border border-zinc-200 dark:border-zinc-700 hover:border-[var(--color-brand-blue)] hover:bg-[rgb(var(--rgb-brand-blue)/0.05)] transition"
                data-testid={`director-recent-${b.id}`}>
                <button onClick={() => loadBrief(b.id)} className="w-full text-left p-2 pr-7">
                  <p className="text-xs font-medium text-zinc-800 dark:text-zinc-100 truncate">{b.prompt}</p>
                  <p className="text-[10px] text-zinc-500 dark:text-zinc-400 mt-0.5 flex items-center gap-1">
                    <Target size={9}/> {b.goal || t('mkt.dir_no_goal', 'no goal')} · {t('mkt.dir_refined_n', 'refined ×{{n}}', { n: b.refined_count || 0 })}
                  </p>
                </button>
                <RowActions className="!absolute top-1 right-1">
                  <Button
                    variant="ghostDestructive"
                    size="iconSm"
                    icon={X}
                    title={t('mkt.dir_del_brief_title', 'Delete this brief from history')}
                    aria-label={t('mkt.dir_del_brief', 'Delete brief')}
                    data-testid={`director-recent-delete-${b.id}`}
                    onClick={async (e) => {
                      e.stopPropagation();
                      try {
                        await axios.delete(`${API}/api/marketing/creative/director/briefs/${b.id}`, { headers });
                        setRecentBriefs((prev) => prev.filter((x) => x.id !== b.id));
                        notify.success(t('mkt.dir_brief_removed', 'Brief removed from history'));
                      } catch (err) {
                        notifyApiError(notify, err, t('mkt.dir_del_err', 'Delete failed'));
                      }
                    }}
                  />
                </RowActions>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Brief output ────────────────────────────────────────── */}
      {brief && (
        <div className="space-y-4" data-testid="director-output">
          {/* Strategy card */}
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4 shadow-sm">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Megaphone className="text-[var(--color-brand-blue)]" size={16}/>
                <h3 className="font-bold text-zinc-900 dark:text-zinc-100 text-sm">{t('mkt.dir_strategy', 'Strategy')}</h3>
                {Array.isArray(brief.learnings_applied) && brief.learnings_applied.length > 0 && (
                  <span className="ml-1 inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300 font-semibold"
                    title={brief.learnings_applied.map((x, i) => `${i + 1}. ${x}`).join('\n')}
                    data-testid="director-learnings-badge">
                    <Sparkles size={9}/> {t('mkt.dir_learnings', 'Applying {{n}} past learning(s)', { n: brief.learnings_applied.length })}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2 flex-wrap">
                <button onClick={() => setAutoPilot((v) => !v)}
                  disabled={!!brief.campaign_id}
                  title={optimalWindow?.source === 'history'
                    ? `Auto-schedule for the org's best-performing window (${optimalWindow.label}, ${(optimalWindow.open_rate*100).toFixed(0)}% avg open rate from ${optimalWindow.sample_size} past sends) and run an AI post-mortem 72h later`
                    : `Auto-schedule for ${optimalWindow?.label || 'Tuesday 6PM'} (industry default — needs more send history for org-tuned timing) and run an AI post-mortem 72h later`}
                  className={`px-2.5 py-1.5 rounded-md text-[11px] font-semibold border flex items-center gap-1 transition ${
                    autoPilot
                      ? 'bg-purple-500 text-white border-purple-500'
                      : 'bg-white dark:bg-zinc-900 text-zinc-600 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:border-purple-500 hover:text-purple-600'
                  } ${brief.campaign_id ? 'opacity-50 cursor-not-allowed' : ''}`}
                  data-testid="director-autopilot-toggle">
                  <Rocket size={11}/> {t('mkt.dir_autopilot', 'Auto-pilot')} {autoPilot && optimalWindow ? `· ${optimalWindow.label}` : ''}
                </button>
                <button onClick={() => setPerRecipient((v) => !v)}
                  disabled={!!brief.campaign_id}
                  title={coverage && coverage.total_members > 0
                    ? `Send each recipient at their personal best hour (${coverage.personal}/${coverage.total_members} members have personal data — ${coverage.coverage_pct}% coverage; the rest fall back to ${optimalWindow?.label || 'the org-best window'})`
                    : `Send each recipient at their personal best hour. No member email-open data yet — every recipient will fall back to ${optimalWindow?.label || 'the org-best window'} until opens accrue.`}
                  className={`px-2.5 py-1.5 rounded-md text-[11px] font-semibold border flex items-center gap-1 transition ${
                    perRecipient
                      ? 'bg-fuchsia-500 text-white border-fuchsia-500'
                      : 'bg-white dark:bg-zinc-900 text-zinc-600 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:border-fuchsia-500 hover:text-fuchsia-600'
                  } ${brief.campaign_id ? 'opacity-50 cursor-not-allowed' : ''}`}
                  data-testid="director-per-recipient-toggle">
                  <Users size={11}/> {t('mkt.dir_per_recipient', 'Per-recipient')} {perRecipient && coverage && coverage.total_members > 0 ? `· ${coverage.coverage_pct}% ${t('mkt.dir_personal', 'personal')}` : ''}
                </button>
                <button onClick={launchAsCampaign}
                  disabled={!!brief.campaign_id}
                  className="px-3 py-1.5 rounded-md bg-emerald-500 hover:bg-emerald-600 disabled:bg-zinc-300 disabled:dark:bg-zinc-700 text-white text-xs font-semibold flex items-center gap-1.5"
                  data-testid="director-launch-campaign">
                  {brief.campaign_id ? <><Check size={12}/> {t('mkt.dir_launched', 'Launched')}</> : <><Send size={12}/> {autoPilot ? t('mkt.dir_schedule_send', 'Schedule send') : t('mkt.dir_launch_campaign', 'Launch as Campaign')}</>}
                </button>
              </div>
            </div>
            <p className="text-sm text-zinc-700 dark:text-zinc-200 mb-3">
              {brief.strategy?.summary}
            </p>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs">
              <Stat icon={Users} label={t('mkt.dir_stat_audience', 'Audience')} value={brief.strategy?.audience?.name || '—'}
                hint={brief.strategy?.audience?.segment_filter_hint} />
              <Stat icon={Zap} label={t('mkt.dir_stat_channels', 'Channels')} value={(brief.strategy?.channels || []).join(', ') || '—'} />
              <Stat icon={Clock} label={t('mkt.dir_stat_send_window', 'Send window')}
                value={brief.strategy?.schedule?.send_window || '—'}
                hint={brief.strategy?.schedule?.frequency} />
              <Stat icon={Target} label={t('mkt.dir_stat_tone', 'Tone')} value={brief.tone} />
            </div>
          </div>

          {/* Refine toolbar */}
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/60 p-3">
            <div className="flex items-center gap-2 mb-2">
              <Wand2 className="text-[var(--color-brand-blue)]" size={14}/>
              <p className="text-[11px] uppercase tracking-wider font-semibold text-zinc-600 dark:text-zinc-300">
                {t('mkt.dir_make_better', 'Make it better')}
              </p>
              {refineBusy && <Loader2 size={12} className="animate-spin text-[var(--color-brand-blue)]"/>}
            </div>
            <div className="flex flex-wrap gap-1.5">
              {REFINE_QUICKACTIONS.map((qa, qi) => (
                <button key={qa.label}
                  disabled={refineBusy}
                  onClick={() => refine(qa.instr)}
                  className="px-2.5 py-1 rounded-full border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-[11px] font-medium text-zinc-700 dark:text-zinc-200 hover:border-[var(--color-brand-blue)] hover:text-[var(--color-brand-blue)] disabled:opacity-50 transition"
                  data-testid={`director-refine-${qa.label.toLowerCase().replace(/[^a-z]/g,'-')}`}>
                  {t('mkt.dir_refine_' + qi, qa.label)}
                </button>
              ))}
            </div>
          </div>

          {/* Poster + channel cards */}
          <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.2fr] gap-4">
            <PosterCard brief={brief} onRegenerate={() =>
              refine('Regenerate the poster image with the same copy but a fresh visual angle', 'poster', true)
            } refineBusy={refineBusy}/>
            <div className="space-y-2">
              {Object.keys(CHANNEL_META).filter(k => k !== 'poster').map((k) => (
                <ChannelCard key={k} channelKey={k} copy={brief.copy?.[k]}
                  onRefine={(instr) => refine(instr, k)} disabled={refineBusy}/>
              ))}
            </div>
          </div>

          {/* Alt-tones / variation grid */}
          {Array.isArray(brief.alt_tones) && brief.alt_tones.length > 0 && (
            <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4">
              <p className="text-[11px] uppercase tracking-wider font-semibold text-zinc-500 dark:text-zinc-400 mb-2">
                {t('mkt.dir_alt_tones', 'Alt-tone variations (A/B)')}
              </p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                {brief.alt_tones.map((alt, i) => (
                  <div key={i}
                    className="rounded-md border border-zinc-200 dark:border-zinc-700 p-3"
                    data-testid={`director-alt-tone-${i}`}>
                    <p className="text-[10px] uppercase tracking-wider font-semibold text-[var(--color-brand-blue)] mb-1">{alt.tone}</p>
                    <p className="text-sm font-bold text-zinc-900 dark:text-zinc-100 mb-1">{alt.headline}</p>
                    <p className="text-xs text-zinc-600 dark:text-zinc-300 mb-1"><strong>{t('mkt.dir_email_lbl', 'Email:')}</strong> {alt.email_subject}</p>
                    <p className="text-xs text-zinc-600 dark:text-zinc-300"><strong>{t('mkt.dir_sms_lbl', 'SMS:')}</strong> {alt.sms}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Phase 3 — Behaviour-driven per-segment variants */}
          {Array.isArray(brief.segment_variants) && brief.segment_variants.length > 0 && (
            <div className="rounded-xl border border-emerald-200 dark:border-emerald-800 bg-emerald-50/30 dark:bg-emerald-950/20 p-4" data-testid="director-segment-variants">
              <div className="flex items-center gap-2 mb-2">
                <Users size={14} className="text-emerald-600 dark:text-emerald-400"/>
                <p className="text-[11px] uppercase tracking-wider font-semibold text-emerald-700 dark:text-emerald-300">
                  {t('mkt.dir_behaviour_driven', 'Behaviour-Driven Variants ({{n}})', { n: brief.segment_variants.length })}
                </p>
                <span className="text-[10px] text-zinc-500 dark:text-zinc-400">— {t('mkt.dir_behaviour_sub', 'Same campaign, different copy per segment')}</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                {brief.segment_variants.map((v, i) => (
                  <div key={i}
                    className="rounded-md border border-emerald-100 dark:border-emerald-800/40 p-3 bg-white dark:bg-zinc-900"
                    data-testid={`director-segment-variant-${v.segment_key}`}>
                    <div className="flex items-center justify-between mb-1.5">
                      <p className="text-[11px] font-bold text-emerald-700 dark:text-emerald-300">{v.segment_label}</p>
                      <span className="text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-700 dark:text-emerald-300">
                        {v.audience_count != null ? t('mkt.dir_members_n', '{{n}} member(s)', { n: v.audience_count }) : t('mkt.dir_live_count', 'live count')}
                      </span>
                    </div>
                    {v.behaviour && <p className="text-[10px] text-zinc-500 dark:text-zinc-400 italic mb-2">{v.behaviour}</p>}
                    <p className="text-sm font-bold text-zinc-900 dark:text-zinc-100 mb-1">{v.headline}</p>
                    <p className="text-xs text-zinc-700 dark:text-zinc-200 mb-1"><strong>{t('mkt.dir_email_lbl', 'Email:')}</strong> {v.email_subject}</p>
                    <p className="text-xs text-zinc-700 dark:text-zinc-200 mb-1"><strong>{t('mkt.dir_sms_lbl', 'SMS:')}</strong> {v.sms}</p>
                    {v.lever_used && (
                      <p className="text-[10px] text-emerald-600 dark:text-emerald-400 mt-1.5 italic">
                        <Zap size={9} className="inline mr-0.5"/> {v.lever_used}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// ───────────────────────── Sub-components ─────────────────────────

const Select = ({ label, value, onChange, options, testId }) => (
  <div>
    <p className="text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 mb-1 font-semibold">{label}</p>
    <select value={value} onChange={(e) => onChange(e.target.value)}
      className="w-full px-2 py-2 border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 rounded-md text-xs"
      data-testid={testId}>
      {options.map((opt) => (
        <option key={opt.key} value={opt.key} title={opt.hint || ''}>{opt.label}</option>
      ))}
    </select>
  </div>
);

const Stat = ({ icon: Icon, label, value, hint }) => (
  <div className="rounded-md border border-zinc-100 dark:border-zinc-800 p-2 bg-zinc-50/50 dark:bg-zinc-900/40">
    <div className="flex items-center gap-1 text-[10px] uppercase tracking-wider text-zinc-500 dark:text-zinc-400 font-semibold">
      <Icon size={10}/> {label}
    </div>
    <p className="text-xs font-medium text-zinc-800 dark:text-zinc-100 mt-0.5 break-words">{value}</p>
    {hint && <p className="text-[10px] text-zinc-400 dark:text-zinc-500 mt-0.5">{hint}</p>}
  </div>
);

const PosterCard = ({ brief, onRegenerate, refineBusy }) => {
  const { t } = useTranslation();
  const raw = brief?.poster_data_url;
  // Stored posters are served by the backend at /api/marketing/creative/file/<token>.
  const url = raw && raw.startsWith('/api/') ? `${process.env.REACT_APP_BACKEND_URL}${raw}` : raw;
  return (
    <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-3" data-testid="director-poster-card">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          <ImageIcon className="text-violet-500" size={14}/>
          <p className="text-xs font-semibold text-zinc-700 dark:text-zinc-200">{t('mkt.dir_poster_title', 'Poster — Gemini Nano Banana')}</p>
        </div>
        <button onClick={onRegenerate} disabled={refineBusy}
          className="px-2 py-1 rounded-md text-[10px] font-medium border border-zinc-200 dark:border-zinc-700 hover:border-[var(--color-brand-blue)] hover:text-[var(--color-brand-blue)] disabled:opacity-50 flex items-center gap-1"
          data-testid="director-regenerate-poster">
          {refineBusy ? <Loader2 size={10} className="animate-spin"/> : <RefreshCw size={10}/>}
          {t('mkt.dir_regenerate', 'Regenerate')}
        </button>
      </div>
      <div className="rounded-md overflow-hidden bg-zinc-100 dark:bg-zinc-950 aspect-[4/5] flex items-center justify-center">
        {url ? (
          <img src={url} alt="AI poster"
            className="w-full h-full object-contain"
            data-testid="director-poster-img"/>
        ) : (
          <div className="text-center text-xs text-zinc-400 dark:text-zinc-500 p-6">
            <ImageIcon size={28} className="mx-auto mb-2 opacity-50"/>
            {t('mkt.dir_poster_skipped', 'Poster generation skipped or unavailable')}
          </div>
        )}
      </div>
      <div className="mt-2 text-xs space-y-0.5">
        <p className="font-bold text-zinc-900 dark:text-zinc-100">{brief?.copy?.poster?.headline}</p>
        {brief?.copy?.poster?.subheadline && <p className="text-zinc-600 dark:text-zinc-300">{brief.copy.poster.subheadline}</p>}
        {brief?.copy?.poster?.cta && <p className="text-[var(--color-brand-blue)] font-semibold">{brief.copy.poster.cta} →</p>}
      </div>
    </div>
  );
};

const ChannelCard = ({ channelKey, copy, onRefine, disabled }) => {
  const { t } = useTranslation();
  const meta = CHANNEL_META[channelKey];
  const [refineOpen, setRefineOpen] = useState(false);
  const [refineText, setRefineText] = useState('');
  if (!copy) return null;
  const Icon = meta.icon;

  const fullText = (() => {
    if (channelKey === 'email') return `${copy.subject || ''}\n\n${copy.preheader || ''}\n\n${copy.body_html || ''}`;
    if (channelKey === 'instagram') return `${copy.caption || ''}\n\n${(copy.hashtags || []).join(' ')}`;
    if (channelKey === 'facebook') return copy.post || '';
    if (channelKey === 'sms') return copy.body || '';
    if (channelKey === 'push') return `${copy.title || ''} — ${copy.body || ''}`;
    return JSON.stringify(copy);
  })();

  const submitRefine = () => {
    if (!refineText.trim()) return;
    onRefine(refineText.trim());
    setRefineText('');
    setRefineOpen(false);
  };

  return (
    <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-3" data-testid={`director-channel-${channelKey}`}>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          <Icon className={meta.color} size={14}/>
          <p className="text-xs font-semibold text-zinc-800 dark:text-zinc-100">{t('mkt.dir_chan_' + channelKey, meta.label)}</p>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => { navigator.clipboard.writeText(fullText); notify.success(t('mkt.dir_copied', 'Copied')); }}
            className="p-1.5 rounded-md text-zinc-500 hover:text-[var(--color-brand-blue)] hover:bg-[rgb(var(--rgb-brand-blue)/0.05)]"
            title={t('mkt.dir_copy', 'Copy')} data-testid={`director-${channelKey}-copy`}>
            <Copy size={11}/>
          </button>
          <button onClick={() => setRefineOpen((v) => !v)} disabled={disabled}
            className="p-1.5 rounded-md text-zinc-500 hover:text-[var(--color-brand-blue)] hover:bg-[rgb(var(--rgb-brand-blue)/0.05)] disabled:opacity-50"
            title={t('mkt.dir_refine_channel', 'Refine this channel')} data-testid={`director-${channelKey}-refine`}>
            <Edit3 size={11}/>
          </button>
        </div>
      </div>
      <ChannelBody channelKey={channelKey} copy={copy}/>
      {refineOpen && (
        <div className="mt-2 flex gap-1">
          <input value={refineText} onChange={(e) => setRefineText(e.target.value)}
            placeholder={t('mkt.dir_refine_channel_ph', 'How should I improve {{label}}? e.g. shorter, add emoji…', { label: t('mkt.dir_chan_' + channelKey, meta.label) })}
            className="flex-1 px-2 py-1 border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 rounded-md text-xs"
            onKeyDown={(e) => e.key === 'Enter' && submitRefine()}
            data-testid={`director-${channelKey}-refine-input`}/>
          <button onClick={submitRefine}
            className="px-2 py-1 rounded-md bg-[var(--color-brand-blue)] hover:bg-[var(--color-brand-blue-alt2)] text-white text-xs font-medium flex items-center gap-1">
            <ChevronRight size={11}/>
          </button>
        </div>
      )}
    </div>
  );
};

const ChannelBody = ({ channelKey, copy }) => {
  const { t } = useTranslation();
  if (channelKey === 'email') {
    return (
      <div className="text-xs space-y-1">
        <p><span className="font-semibold text-zinc-700 dark:text-zinc-200">{t('mkt.dir_subject', 'Subject:')}</span> {copy.subject}</p>
        {copy.preheader && <p className="text-zinc-500 dark:text-zinc-400 italic">{t('mkt.dir_preview', 'Preview:')} {copy.preheader}</p>}
        <div
          className="rounded-md border border-zinc-100 dark:border-zinc-800 p-2 bg-zinc-50/50 dark:bg-zinc-950 prose prose-sm dark:prose-invert max-w-none"
          dangerouslySetInnerHTML={{ __html: copy.body_html || '' }}
        />
      </div>
    );
  }
  if (channelKey === 'instagram') {
    return (
      <div className="text-xs space-y-1">
        <p className="text-zinc-700 dark:text-zinc-200 whitespace-pre-line">{copy.caption}</p>
        <p className="text-pink-500 text-[11px]">{(copy.hashtags || []).join(' ')}</p>
      </div>
    );
  }
  if (channelKey === 'facebook') {
    return <p className="text-xs text-zinc-700 dark:text-zinc-200 whitespace-pre-line">{copy.post}</p>;
  }
  if (channelKey === 'sms') {
    return (
      <div className="text-xs">
        <p className="text-zinc-700 dark:text-zinc-200 font-mono bg-zinc-50 dark:bg-zinc-950 p-2 rounded">{copy.body}</p>
        <p className="text-[10px] text-zinc-400 dark:text-zinc-500 mt-1">{t('mkt.dir_chars', '{{n}}/160 chars', { n: (copy.body || '').length })}</p>
      </div>
    );
  }
  if (channelKey === 'push') {
    return (
      <div className="text-xs">
        <p className="font-semibold text-zinc-900 dark:text-zinc-100">{copy.title}</p>
        <p className="text-zinc-600 dark:text-zinc-300">{copy.body}</p>
      </div>
    );
  }
  return null;
};

export default AIDirectorPanel;

/**
 * /blog — index page listing all posts.
 *
 * Merges the file-based legacy registry with SEO Autopilot DB articles
 * (Iter 220ad). DB articles take precedence on slug conflicts.
 */
import React from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { ArrowRight, BookOpen, Clock } from 'lucide-react';

import '../marketing.css';
import PulseMarketingShell from '../PulseMarketingShell';
import { posts as staticPosts } from './posts';

const API = process.env.REACT_APP_BACKEND_URL;

export default function BlogIndex() {
  const [dbPosts, setDbPosts] = React.useState([]);
  React.useEffect(() => {
    let cancelled = false;
    axios.get(`${API}/api/blog/posts`)
      .then((r) => { if (!cancelled) setDbPosts((r.data?.posts || []).map((p) => ({
        slug: p.slug,
        title: p.title,
        excerpt: p.excerpt,
        publishedAt: p.published_at,
        readingMinutes: p.read_time_min || 7,
        tags: p.tags || [],
        hero_image_url: p.hero_image_url,
      }))); })
      .catch(() => { /* silently fall back to static */ });
    return () => { cancelled = true; };
  }, []);

  const seen = new Set(dbPosts.map((p) => p.slug));
  const posts = [
    ...dbPosts,
    ...staticPosts.filter((p) => !seen.has(p.slug)),
  ].sort((a, b) => (b.publishedAt || '').localeCompare(a.publishedAt || ''));

  React.useEffect(() => {
    const prev = document.title;
    const prevMeta = document.querySelector('meta[name="description"]')?.getAttribute('content');
    document.title = 'Pulse Fitness Blog — Operations, reporting, and service-desk playbooks';
    let m = document.querySelector('meta[name="description"]');
    if (!m) { m = document.createElement('meta'); m.setAttribute('name', 'description'); document.head.appendChild(m); }
    m.setAttribute('content', 'Actionable playbooks for gym operators: cut equipment downtime, track the right KPIs, and write SLAs that stick.');
    return () => {
      document.title = prev;
      if (m && prevMeta) m.setAttribute('content', prevMeta);
    };
  }, []);

  return (
    <PulseMarketingShell>
      <section className="gx-grid-bg">
        <div className="max-w-7xl mx-auto px-6 lg:px-8 pt-14 pb-16 lg:pt-20 lg:pb-24">
          <span className="inline-flex items-center gap-2 rounded-full bg-white dark:bg-zinc-900 border border-slate-200 px-3 py-1 text-xs font-bold uppercase tracking-[0.18em] text-slate-600">
            <BookOpen size={12} /> The Pulse Fitness Blog
          </span>
          <h1 className="mt-5 text-4xl md:text-5xl lg:text-6xl tracking-tight font-black leading-[1.05] max-w-4xl" style={{ color: '#1B1C1D' }}>
            Playbooks for operators who<br />
            <span style={{ color: '#19CDFF' }}>run the floor.</span>
          </h1>
          <p className="mt-6 text-lg md:text-xl text-slate-600 max-w-3xl">
            Short, specific, numbers-first reads on service desk, reporting, contracts and the operational habits that separate scale from stall.
          </p>
        </div>
      </section>

      <section className="bg-white pb-24 dark:bg-zinc-900">
        <div className="max-w-6xl mx-auto px-6 lg:px-8 grid md:grid-cols-2 lg:grid-cols-3 gap-5" data-testid="blog-index">
          {posts.map((p) => (
            <Link
              key={p.slug}
              to={`/blog/${p.slug}`}
              data-testid={`blog-card-${p.slug}`}
              className="group rounded-2xl bg-white dark:bg-zinc-900 border border-slate-200 overflow-hidden hover:shadow-lg hover:-translate-y-0.5 hover:border-[#19CDFF] transition flex flex-col"
            >
              <div className="aspect-[16/9] bg-[#1B1C1D] flex items-center justify-center p-6 overflow-hidden">
                {p.hero_image_url ? (
                  <img src={p.hero_image_url} alt="" className="w-full h-full object-cover"/>
                ) : (
                  <span className="text-white/80 text-xs font-bold uppercase tracking-[0.2em]">
                    {p.tags?.[0] || 'Article'}
                  </span>
                )}
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h2 className="text-xl font-black tracking-tight leading-snug" style={{ color: '#1B1C1D' }}>{p.title}</h2>
                <p className="mt-3 text-sm text-slate-600 leading-relaxed flex-1">{p.excerpt}</p>
                <div className="mt-5 flex items-center justify-between text-xs text-slate-500">
                  <span>{p.publishedAt ? new Date(p.publishedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'}</span>
                  <span className="inline-flex items-center gap-1"><Clock size={11} /> {p.readingMinutes}m</span>
                </div>
                <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-bold text-[#1B1C1D] group-hover:text-[#19CDFF] transition-colors">
                  Read <ArrowRight size={14} />
                </span>
              </div>
            </Link>
          ))}
        </div>
      </section>
    </PulseMarketingShell>
  );
}

/**
 * Marketing → Contacts tab — Iter 215bf (May 1, 2026).
 *
 * Purpose:
 *  Lite contact directory inside the Marketing Suite so customers on
 *  the Marketing-only license (£49/mo) can manage the contacts they've
 *  captured via lead-capture forms, edit details, import CSVs, and
 *  feed them into audiences and campaigns. Customers on the CRM
 *  license see the full pipeline + deals UI in the dedicated CRM app
 *  (`/crm`) — this tab is the marketing-only on-ramp.
 *
 *  Backend: `/api/marketing/contacts` (list/get/create/update/delete +
 *  bulk CSV import) gated by `require_module(("crm","marketing"))`.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { Search, Plus, Upload, Trash2, X, Loader2, AtSign, Phone as PhoneIcon, Tag, Sparkles } from 'lucide-react';
import CRMProTrialNudge from './CRMProTrialNudge';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { useAuth } from '@/App';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const PAGE_SIZE = 25;

export default function ContactsTab() {
  const { t } = useTranslation();
  const { token } = useAuth();
  const API = process.env.REACT_APP_BACKEND_URL;
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const [search, setSearch] = useState('');
  const [contacts, setContacts] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editing, setEditing] = useState(null); // contact | "new"

  const fileInputRef = useRef(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/api/marketing/contacts`, {
        headers,
        params: { search, skip: page * PAGE_SIZE, limit: PAGE_SIZE },
      });
      setContacts(data.contacts || []);
      setTotal(data.total || 0);
    } catch (e) {
      notifyApiError(notify, e, t('mkt.ct_load_err', 'Could not load contacts'));
    }
    setLoading(false);
  }, [API, headers, search, page]);

  useEffect(() => { load(); }, [load]);

  // Reset to page 0 when search changes (so users always see page 1 of new results).
  useEffect(() => { setPage(0); }, [search]);

  const handleDelete = async (c) => {
    if (!window.confirm(t('mkt.ct_delete_confirm', 'Delete {{email}}? This cannot be undone.', { email: c.email }))) return;
    try {
      await axios.delete(`${API}/api/marketing/contacts/${c.id}`, { headers });
      notify.success(t('mkt.ct_deleted', 'Contact deleted'));
      load();
    } catch (e) { notifyApiError(notify, e, t('mkt.ct_delete_err', 'Could not delete contact')); }
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleImportFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = ''; // allow re-uploading same file
    const fd = new FormData();
    fd.append('file', file);
    try {
      const { data } = await axios.post(`${API}/api/marketing/contacts/import`, fd, {
        headers: { ...headers, 'Content-Type': 'multipart/form-data' },
      });
      notify.success(t('mkt.ct_import_done', 'Imported {{created}} new · {{updated}} updated · {{skipped}} skipped', { created: data.created, updated: data.updated, skipped: data.skipped }));
      load();
    } catch (e) { notifyApiError(notify, e, t('mkt.ct_import_err', 'CSV import failed')); }
  };

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  return (
    <div className="space-y-5" data-testid="marketing-contacts-tab">
      {/* Iter 215dl — CRM Lite is bundled with Marketing. Surfacing this
          framing turns "another tab in the email tool" into a perceived
          mini-CRM without spinning up a second app. Customers upgrade
          to CRM Pro when they need pipeline / deals / forecasting. */}
      <div
        className="rounded-xl border px-4 py-3 flex items-start gap-3"
        style={{ borderColor: 'var(--theme-border)', background: 'linear-gradient(135deg, rgb(217 70 239 / 0.06) 0%, rgb(99 102 241 / 0.06) 100%)' }}
        data-testid="crm-lite-badge"
      >
        <div className="h-8 w-8 rounded-lg flex items-center justify-center shrink-0" style={{ background: 'linear-gradient(135deg, #19cdff 0%, #19cdff 100%)', color: 'white' }}>
          <Sparkles size={14} />
        </div>
        <div className="min-w-0 text-sm">
          <p className="font-bold" style={{ color: 'var(--theme-text)' }}>
            <span className="inline-block px-1.5 py-0.5 rounded text-[10px] font-extrabold uppercase tracking-wider mr-1.5" style={{ background: '#6366f122', color: '#19cdff' }}>{t('mkt.ct_crm_lite', 'CRM Lite')}</span>
            {t('mkt.ct_included', 'included with Marketing')}
          </p>
          <p className="text-xs opacity-70 mt-0.5">
            {t('mkt.ct_lite_desc', 'Manage contacts, segments and lead-capture forms here. Need pipeline, deals or forecasting?')}{' '}
            <span className="font-semibold" style={{ color: 'var(--theme-text)' }}>{t('mkt.ct_upgrade', 'Upgrade to CRM Pro.')}</span>
          </p>
        </div>
      </div>

      {/* Iter 215dm — in-product upsell when the contact base scales
          past 250. Self-renders empty (returns null) if the tenant
          already has CRM Pro, dismissed, or below threshold. */}
      <CRMProTrialNudge totalContacts={total} threshold={250} />

      <div className="flex flex-wrap items-center gap-3">
        {/* search + actions row */}
        <div className="flex-1 min-w-[220px] relative">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search name, email, phone…"
            className="pl-9 h-10 rounded-xl bg-white border-slate-200 dark:bg-zinc-900 dark:border-zinc-800"
            data-testid="contacts-search"
          />
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv"
          onChange={handleImportFile}
          className="hidden"
          data-testid="contacts-import-input"
        />
        <Button
          variant="outline"
          onClick={handleImportClick}
          className="h-10 rounded-full border-slate-200 dark:border-zinc-800"
          data-testid="contacts-import-btn"
        >
          <Upload size={14} className="mr-1.5" /> {t('mkt.ct_import_csv', 'Import CSV')}
        </Button>
        <Button
          onClick={() => setEditing('new')}
          className="h-10 rounded-full bg-gradient-to-r from-[var(--gx-brand-from)] to-[var(--gx-brand-to)] text-white border-0 shadow-[0_6px_16px_-6px_rgba(25, 205, 255,0.35)]"
          data-testid="contacts-create-btn"
        >
          <Plus size={14} className="mr-1.5" /> {t('mkt.ct_new_contact', 'New contact')}
        </Button>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white overflow-hidden shadow-[0_1px_2px_rgba(27, 28, 29,0.04)] dark:bg-zinc-900 dark:border-zinc-800">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-[11px] uppercase tracking-[0.16em] font-bold text-slate-500 dark:bg-zinc-900 dark:border-zinc-800">
              <th className="text-left px-5 py-3">{t('mkt.ct_th_name', 'Name')}</th>
              <th className="text-left px-5 py-3 hidden sm:table-cell">{t('mkt.ct_th_email', 'Email')}</th>
              <th className="text-left px-5 py-3 hidden md:table-cell">{t('mkt.ct_th_phone', 'Phone')}</th>
              <th className="text-left px-5 py-3 hidden lg:table-cell">{t('mkt.ct_th_tags', 'Tags')}</th>
              <th className="text-right px-5 py-3 w-1">{t('mkt.ct_th_actions', 'Actions')}</th>
            </tr>
          </thead>
          <tbody>
            {loading && (
              <tr><td colSpan={5} className="px-5 py-8 text-center text-slate-400"><Loader2 size={16} className="animate-spin inline mr-2" /> {t('mkt.ct_loading', 'Loading contacts…')}</td></tr>
            )}
            {!loading && contacts.length === 0 && (
              <tr><td colSpan={5} className="px-5 py-12 text-center">
                <div className="text-slate-700 font-semibold mb-1">{t('mkt.ct_empty_title', 'No contacts yet')}</div>
                <p className="text-sm text-slate-500 max-w-sm mx-auto">
                  {t('mkt.ct_empty_body', 'Capture leads with a Form on your site, import a CSV, or create one manually. Contacts feed Audiences, Campaigns and Journeys.')}
                </p>
              </td></tr>
            )}
            {!loading && contacts.map((c) => (
              <tr key={c.id} className="border-b border-slate-100 hover:bg-slate-50/50 dark:border-zinc-800" data-testid={`contact-row-${c.id}`}>
                <td className="px-5 py-3">
                  <button
                    type="button"
                    onClick={() => setEditing(c)}
                    className="font-semibold text-slate-900 hover:text-[var(--gx-brand-from)] text-left dark:text-zinc-100"
                  >
                    {(c.first_name || c.last_name) ? `${c.first_name || ''} ${c.last_name || ''}`.trim() : <span className="text-slate-400 italic">{t('mkt.ct_no_name', 'No name')}</span>}
                  </button>
                  <div className="text-xs text-slate-500 sm:hidden mt-0.5">{c.email}</div>
                </td>
                <td className="px-5 py-3 hidden sm:table-cell text-slate-700">{c.email}</td>
                <td className="px-5 py-3 hidden md:table-cell text-slate-500">{c.phone || '—'}</td>
                <td className="px-5 py-3 hidden lg:table-cell">
                  <div className="flex flex-wrap gap-1">
                    {(c.tags || []).slice(0, 3).map((tag) => (
                      <span key={tag} className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-slate-100 text-[11px] font-semibold text-slate-700 dark:bg-zinc-800"><Tag size={9} /> {tag}</span>
                    ))}
                  </div>
                </td>
                <td className="px-5 py-3 text-right">
                  <button
                    type="button"
                    onClick={() => handleDelete(c)}
                    className="text-slate-400 hover:text-red-600 p-1.5 rounded-lg hover:bg-red-50"
                    aria-label={t('mkt.ct_delete_aria', 'Delete contact')}
                    data-testid={`contact-delete-${c.id}`}
                  >
                    <Trash2 size={14} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-5 py-3 border-t border-slate-100 text-sm text-slate-600 dark:border-zinc-800">
            <span>{t('mkt.ct_pagination', 'Page {{page}} of {{total}} · {{count}} contacts', { page: page + 1, total: totalPages, count: total.toLocaleString() })}</span>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" disabled={page <= 0} onClick={() => setPage((p) => p - 1)} data-testid="contacts-prev">{t('mkt.ct_prev', 'Prev')}</Button>
              <Button variant="outline" size="sm" disabled={page + 1 >= totalPages} onClick={() => setPage((p) => p + 1)} data-testid="contacts-next">{t('mkt.ct_next', 'Next')}</Button>
            </div>
          </div>
        )}
      </div>

      {editing && (
        <ContactDialog
          contact={editing === 'new' ? null : editing}
          onClose={() => setEditing(null)}
          onSaved={() => { setEditing(null); load(); }}
          API={API}
          headers={headers}
        />
      )}
    </div>
  );
}

function ContactDialog({ contact, onClose, onSaved, API, headers }) {
  const { t } = useTranslation();
  const isNew = !contact;
  const [form, setForm] = useState({
    first_name: contact?.first_name || '',
    last_name: contact?.last_name || '',
    email: contact?.email || '',
    phone: contact?.phone || '',
    tags: (contact?.tags || []).join(', '),
    email_consent: contact?.marketing_consent?.email !== false,
    sms_consent: contact?.marketing_consent?.sms === true,
  });
  const [saving, setSaving] = useState(false);

  const save = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const body = {
        first_name: form.first_name.trim(),
        last_name: form.last_name.trim(),
        email: form.email.trim().toLowerCase(),
        phone: form.phone.trim() || null,
        tags: form.tags.split(',').map((tag) => tag.trim()).filter(Boolean),
        email_consent: form.email_consent,
        sms_consent: form.sms_consent,
      };
      if (isNew) {
        await axios.post(`${API}/api/marketing/contacts`, body, { headers });
        notify.success(t('mkt.ct_created', 'Contact created'));
      } else {
        await axios.put(`${API}/api/marketing/contacts/${contact.id}`, {
          ...body,
          marketing_consent: { email: body.email_consent, sms: body.sms_consent },
        }, { headers });
        notify.success(t('mkt.ct_updated', 'Contact updated'));
      }
      onSaved();
    } catch (e2) { notifyApiError(notify, e2, t('mkt.ct_save_err', 'Could not save contact')); }
    setSaving(false);
  };

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="sm:max-w-md bg-white dark:bg-zinc-900">
        <DialogHeader>
          <DialogTitle>{isNew ? t('mkt.ct_new_contact', 'New contact') : t('mkt.ct_edit_contact', 'Edit contact')}</DialogTitle>
        </DialogHeader>
        <form onSubmit={save} className="space-y-3" data-testid="contact-dialog-form">
          <div className="grid grid-cols-2 gap-3">
            <Input value={form.first_name} onChange={(e) => setForm((f) => ({ ...f, first_name: e.target.value }))} placeholder={t('mkt.ct_first_name', 'First name')} data-testid="contact-first-name" />
            <Input value={form.last_name} onChange={(e) => setForm((f) => ({ ...f, last_name: e.target.value }))} placeholder={t('mkt.ct_last_name', 'Last name')} data-testid="contact-last-name" />
          </div>
          <div className="relative">
            <AtSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} placeholder="email@example.com" required type="email" className="pl-9" data-testid="contact-email" />
          </div>
          <div className="relative">
            <PhoneIcon size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} placeholder="Phone (optional)" className="pl-9" data-testid="contact-phone" />
          </div>
          <Input value={form.tags} onChange={(e) => setForm((f) => ({ ...f, tags: e.target.value }))} placeholder="Tags, comma separated" data-testid="contact-tags" />
          <div className="flex items-center gap-4 text-sm">
            <label className="inline-flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.email_consent} onChange={(e) => setForm((f) => ({ ...f, email_consent: e.target.checked }))} data-testid="contact-email-consent" />
              <span className="text-slate-700">Email consent</span>
            </label>
            <label className="inline-flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.sms_consent} onChange={(e) => setForm((f) => ({ ...f, sms_consent: e.target.checked }))} data-testid="contact-sms-consent" />
              <span className="text-slate-700">{t('mkt.ct_sms_consent', 'SMS consent')}</span>
            </label>
          </div>
          <DialogFooter className="pt-2">
            <Button type="button" variant="outline" onClick={onClose}><X size={14} className="mr-1.5" /> {t('mkt.ct_cancel', 'Cancel')}</Button>
            <Button type="submit" disabled={saving} className="bg-gradient-to-r from-[var(--gx-brand-from)] to-[var(--gx-brand-to)] text-white border-0" data-testid="contact-save-btn">
              {saving ? <><Loader2 size={14} className="animate-spin mr-1.5" /> {t('mkt.ct_saving', 'Saving…')}</> : t('mkt.ct_save_contact', 'Save contact')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/* Dynamic Lists tab — auto-refreshing audience segments (Iter 229).
 *
 * Differs from static Audiences in two ways:
 *   • each list re-evaluates on read if older than its refresh interval
 *   • list rows show a "last refreshed" timestamp + manual refresh button
 *
 * Reuses the same FIELDS/OPS vocabulary as AudiencesTab so users learn
 * one rule-builder, not two.
 */
import React, { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { ListChecks, Plus, Sparkles, Loader2, Trash2, Save, RefreshCw, ChevronDown, ChevronUp, Clock } from 'lucide-react';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const BASE_FIELDS = [
  { id: 'lifetime_value_gbp', label: 'Lifetime value (£)', type: 'number' },
  { id: 'churn_risk_score', label: 'Churn risk score', type: 'number' },
  { id: 'attendance_30d', label: 'Visits in last 30 days', type: 'number' },
  { id: 'last_attended_at', label: 'Last attended', type: 'days_ago' },
  { id: 'signup_at', label: 'Signed up', type: 'days_ago' },
  { id: 'class_preference', label: 'Class preference', type: 'enum', options: ['spin', 'hiit', 'pt', 'yoga', 'strength'] },
  { id: 'subscription_tier', label: 'Subscription tier', type: 'enum', options: ['free', 'pro', 'premium'] },
  { id: 'payment_status', label: 'Payment status', type: 'enum', options: ['active', 'failed', 'cancelled'] },
];
const FIELD_TYPE_TO_RB = (ft) => {
  if (ft === 'number') return 'number';
  if (ft === 'date') return 'days_ago';
  if (ft === 'select' || ft === 'multi_select') return 'enum';
  return 'text';
};
const OPS = [
  { id: '>=', label: '≥' }, { id: '<=', label: '≤' }, { id: '==', label: '=' }, { id: '!=', label: '≠' },
];
const REFRESH_OPTIONS = [
  { value: 15, label: 'Every 15 minutes' },
  { value: 60, label: 'Hourly (default)' },
  { value: 240, label: 'Every 4 hours' },
  { value: 1440, label: 'Daily' },
];

const formatRelative = (iso) => {
  if (!iso) return 'never';
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 60_000) return 'just now';
  const m = Math.floor(ms / 60_000);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
};

const DynamicListsTab = ({ API, headers }) => {
  const { t } = useTranslation();
  const [lists, setLists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [draftName, setDraftName] = useState('');
  const [draftDescription, setDraftDescription] = useState('');
  const [draftInterval, setDraftInterval] = useState(60);
  const [draftConditions, setDraftConditions] = useState([]);
  const [draftPreviewSize, setDraftPreviewSize] = useState(0);
  const [busy, setBusy] = useState(false);
  const [expandedId, setExpandedId] = useState(null);
  const [members, setMembers] = useState({});
  const [customFields, setCustomFields] = useState([]);

  const FIELDS = React.useMemo(() => [...BASE_FIELDS, ...customFields], [customFields]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/api/marketing/dynamic-lists`, { headers });
      setLists(data.lists || []);
    } catch {
      notify.error(t('mkt.dl_load_err', 'Failed to load dynamic lists'));
    }
    setLoading(false);
  }, [API, headers]);

  const loadCustomProps = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API}/api/custom-properties?entity_type=contact`, { headers });
      const cf = (data.properties || []).map((p) => ({
        id: `custom_fields.${p.key}`,
        label: `${p.label} (custom)`,
        type: FIELD_TYPE_TO_RB(p.field_type),
        options: (p.options || []).map((o) => o.value),
      }));
      setCustomFields(cf);
    } catch { /* noop */ }
  }, [API, headers]);

  useEffect(() => { load(); loadCustomProps(); }, [load, loadCustomProps]);

  const refreshDraftPreview = useCallback(async (conditions) => {
    try {
      const { data } = await axios.post(`${API}/api/marketing/audiences/preview`, {
        rules: { op: 'and', conditions },
      }, { headers });
      setDraftPreviewSize(data.estimated_size || 0);
    } catch { /* noop */ }
  }, [API, headers]);

  useEffect(() => {
    if (creating) refreshDraftPreview(draftConditions);
  }, [creating, draftConditions, refreshDraftPreview]);

  const addCondition = () => setDraftConditions((c) => [...c, { field: 'lifetime_value_gbp', op: '>=', value: 100 }]);
  const updateCondition = (i, patch) => setDraftConditions((c) => c.map((x, idx) => idx === i ? { ...x, ...patch } : x));
  const removeCondition = (i) => setDraftConditions((c) => c.filter((_, idx) => idx !== i));

  const save = async () => {
    if (!draftName.trim()) return;
    setBusy(true);
    try {
      await axios.post(`${API}/api/marketing/dynamic-lists`, {
        name: draftName,
        description: draftDescription,
        rules: { op: 'and', conditions: draftConditions },
        refresh_interval_minutes: draftInterval,
      }, { headers });
      notify.success(t('mkt.dl_created', 'Dynamic list created'));
      setDraftName(''); setDraftDescription(''); setDraftConditions([]); setDraftInterval(60);
      setCreating(false);
      load();
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_save_err', 'Save failed'));
    } finally { setBusy(false); }
  };

  const refreshOne = async (id) => {
    setBusy(true);
    try {
      await axios.post(`${API}/api/marketing/dynamic-lists/${id}/refresh`, {}, { headers });
      load();
      if (expandedId === id) loadMembers(id);
      notify.success(t('mkt.dl_refreshed', 'List refreshed'));
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_refresh_err', 'Refresh failed'));
    } finally { setBusy(false); }
  };

  const remove = async (id) => {
    if (!window.confirm(t('mkt.dl_delete_confirm', 'Delete this dynamic list?'))) return;
    try {
      await axios.delete(`${API}/api/marketing/dynamic-lists/${id}`, { headers });
      notify.success(t('mkt.dl_deleted', 'Deleted'));
      load();
    } catch (e) {
      notifyApiError(notify, e, t('mkt.dl_delete_err', 'Delete failed'));
    }
  };

  const loadMembers = async (id) => {
    try {
      const { data } = await axios.get(`${API}/api/marketing/dynamic-lists/${id}/members?page=1&page_size=20`, { headers });
      setMembers((prev) => ({ ...prev, [id]: data.members || [] }));
    } catch { /* noop */ }
  };

  const toggleExpand = (id) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
      if (!members[id]) loadMembers(id);
    }
  };

  return (
    <div className="space-y-5" data-testid="marketing-dynamic-lists-tab">
      {/* Iter 216h245 — H2 "Dynamic Lists" removed (redundant with the
          tab pill). The "What is a Dynamic List?" explainer box stays —
          it's onboarding content, not a sub-header. */}
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div className="flex-1 min-w-0">
          <div className="max-w-3xl rounded-xl border border-fuchsia-200/60 bg-fuchsia-50/40 px-4 py-3 text-[13px] leading-relaxed" style={{ color: 'var(--theme-text)' }} data-testid="dynamic-lists-explainer">
            <strong className="text-fuchsia-700">{t('mkt.dl_explainer_title', 'What is a Dynamic List?')}</strong>
            <span className="text-[var(--theme-text-muted)]"> {t('mkt.dl_explainer_body', 'A saved audience that updates itself. You write a rule once (e.g. members joined in the last 30 days who skipped a class) and the list re-evaluates every time a contact\'s data changes — no manual refresh, no stale exports. Use them as campaign audiences or journey entry conditions. Compare with a Static list (fixed snapshot, never updates).')}</span>
          </div>
        </div>
        <button
          onClick={() => setCreating((c) => !c)}
          className="px-3 py-2 rounded-md bg-[var(--color-brand-blue)] text-white text-sm font-semibold inline-flex items-center gap-1.5"
          data-testid="dynamic-list-new-btn"
        >
          <Plus size={13} /> {creating ? t('mkt.dl_cancel', 'Cancel') : t('mkt.dl_new', 'New dynamic list')}
        </button>
      </div>

      {/* Create form */}
      {creating && (
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-5 space-y-3" data-testid="dynamic-list-builder">
          <input
            value={draftName}
            onChange={(e) => setDraftName(e.target.value)}
            placeholder={t('mkt.dl_name_placeholder', 'List name')}
            className="w-full px-3 py-2 border border-zinc-200 dark:border-zinc-800 rounded-md text-sm bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
            data-testid="dynamic-list-name-input"
          />
          <input
            value={draftDescription}
            onChange={(e) => setDraftDescription(e.target.value)}
            placeholder={t('mkt.dl_desc_placeholder', 'Optional description')}
            className="w-full px-3 py-2 border border-zinc-200 dark:border-zinc-800 rounded-md text-sm bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
            data-testid="dynamic-list-desc-input"
          />
          <div className="space-y-2">
            {draftConditions.map((c, i) => {
              const f = FIELDS.find((x) => x.id === c.field) || FIELDS[0];
              return (
                <div key={i} className="flex items-center gap-2" data-testid={`dynamic-list-condition-${i}`}>
                  <select value={c.field} onChange={(e) => updateCondition(i, { field: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                    {FIELDS.map((fld) => <option key={fld.id} value={fld.id}>{fld.label}</option>)}
                  </select>
                  <select value={c.op} onChange={(e) => updateCondition(i, { op: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs w-16 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                    {OPS.map((op) => <option key={op.id} value={op.id}>{op.label}</option>)}
                  </select>
                  {f.type === 'enum' ? (
                    <select value={c.value} onChange={(e) => updateCondition(i, { value: e.target.value })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100">
                      {f.options.map((o) => <option key={o} value={o}>{o}</option>)}
                    </select>
                  ) : f.type === 'days_ago' ? (
                    <input type="text" value={c.value} onChange={(e) => updateCondition(i, { value: e.target.value })} placeholder="30d_ago" className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100" />
                  ) : (
                    <input type="number" value={c.value} onChange={(e) => updateCondition(i, { value: parseFloat(e.target.value) || 0 })} className="px-2 py-1.5 border border-zinc-200 dark:border-zinc-800 rounded-md text-xs flex-1 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100" />
                  )}
                  <button onClick={() => removeCondition(i)} className="p-1 text-zinc-400 dark:text-zinc-500 hover:text-red-500"><Trash2 size={13} /></button>
                </div>
              );
            })}
            <button onClick={addCondition} className="inline-flex items-center gap-1 text-xs text-[var(--color-brand-blue)] font-semibold mt-1" data-testid="dynamic-list-add-condition">
              <Plus size={12} /> {t('mkt.dl_add_condition', 'Add condition')}
            </button>
          </div>
          <div className="flex items-center justify-between flex-wrap gap-2 mt-3 pt-3 border-t border-zinc-200 dark:border-zinc-800">
            <label className="text-xs inline-flex items-center gap-1.5" style={{ color: 'var(--theme-text-muted)' }}>
              <Clock size={12} /> Refresh:
              <select
                value={draftInterval}
                onChange={(e) => setDraftInterval(parseInt(e.target.value, 10))}
                className="px-2 py-1 border border-zinc-200 dark:border-zinc-800 rounded text-xs bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100"
                data-testid="dynamic-list-interval"
              >
                {REFRESH_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </label>
            <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
              <Sparkles size={12} className="inline text-amber-500 mr-1" />
              <span className="font-bold" style={{ color: 'var(--theme-text)' }}>{draftPreviewSize.toLocaleString()}</span> contacts will match
            </p>
            <button
              onClick={save}
              disabled={busy || !draftName.trim()}
              className="px-3 py-1.5 rounded-md bg-[var(--color-brand-blue)] text-white text-xs font-semibold disabled:opacity-50 inline-flex items-center gap-1"
              data-testid="dynamic-list-save"
            >
              {busy ? <Loader2 size={11} className="animate-spin" /> : <Save size={11} />} Save
            </button>
          </div>
        </div>
      )}

      {/* Lists */}
      {loading ? (
        <div className="text-center py-12">
          <Loader2 size={32} className="animate-spin text-[var(--color-brand-blue)] mx-auto" />
        </div>
      ) : lists.length === 0 ? (
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-10 text-center" data-testid="dynamic-list-empty">
          <ListChecks size={36} className="mx-auto text-zinc-300 dark:text-zinc-600 mb-3" />
          <p className="text-sm font-medium" style={{ color: 'var(--theme-text)' }}>{t('mkt.dl_empty_title', 'No dynamic lists yet')}</p>
          <p className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>{t('mkt.dl_empty_hint', 'Create one to auto-refresh a segment as your contacts change.')}</p>
        </div>
      ) : (
        <div className="space-y-2" data-testid="dynamic-list-rows">
          {lists.map((l) => {
            const expanded = expandedId === l.id;
            return (
              <div key={l.id} className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900" data-testid={`dynamic-list-row-${l.id}`}>
                <div className="p-4 flex items-center gap-3 flex-wrap">
                  <button onClick={() => toggleExpand(l.id)} className="text-zinc-500 dark:text-zinc-400 hover:text-zinc-800 dark:hover:text-zinc-200" aria-label="Toggle">
                    {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                  </button>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-zinc-900 dark:text-zinc-100 truncate">{l.name}</p>
                    {l.description && (
                      <p className="text-[11px] text-zinc-500 dark:text-zinc-400 truncate">{l.description}</p>
                    )}
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold tabular-nums text-zinc-900 dark:text-zinc-100" data-testid={`dynamic-list-count-${l.id}`}>{(l.member_count || 0).toLocaleString()}</p>
                    <p className="text-[10px] text-zinc-400 dark:text-zinc-500">{t('mkt.dl_contacts', 'contacts')}</p>
                  </div>
                  <div className="text-right text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>
                    {t('mkt.dl_refreshed_rel', 'Refreshed {{rel}}', { rel: formatRelative(l.last_evaluated_at) })}<br />
                    {t('mkt.dl_every', 'every {{n}}m', { n: l.refresh_interval_minutes })}
                  </div>
                  <button
                    onClick={() => refreshOne(l.id)}
                    disabled={busy}
                    className="p-2 rounded hover:bg-zinc-100 dark:bg-zinc-800 dark:hover:bg-zinc-800 text-zinc-500 dark:text-zinc-400"
                    data-testid={`dynamic-list-refresh-${l.id}`}
                    title="Refresh now"
                  >
                    <RefreshCw size={13} />
                  </button>
                  <button
                    onClick={() => remove(l.id)}
                    className="p-2 rounded hover:bg-rose-50 dark:hover:bg-rose-950/40 text-rose-500"
                    data-testid={`dynamic-list-delete-${l.id}`}
                    title="Delete"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
                {expanded && (
                  <div className="border-t border-zinc-200 dark:border-zinc-800 p-4 bg-zinc-50/50 dark:bg-zinc-950/40" data-testid={`dynamic-list-members-${l.id}`}>
                    <p className="text-[10px] uppercase tracking-wider font-semibold mb-2" style={{ color: 'var(--theme-text-muted)' }}>
                      {t('mkt.dl_first_of', 'First {{shown}} of {{total}} members', { shown: (members[l.id] || []).length, total: (l.member_count || 0).toLocaleString() })}
                    </p>
                    {(members[l.id] || []).length === 0 ? (
                      <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('mkt.dl_no_members', 'No members match this list yet.')}</p>
                    ) : (
                      <div className="space-y-1">
                        {(members[l.id] || []).map((m) => (
                          <div key={m.id} className="flex items-center justify-between text-xs py-1">
                            <span className="text-zinc-800 dark:text-zinc-200">{m.first_name} {m.last_name}</span>
                            <span className="text-zinc-500 dark:text-zinc-400">{m.email}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

