/**
 * Memberships → Instructors tab.
 *
 * Operator-only Phase 3 view. Two sub-views:
 *   • Performance — per-instructor stats over a chosen window
 *   • Cover board — outstanding cover requests + assign-to action
 *
 * Mobile-first: stacked cards on small screens, table on lg+.
 */
import { useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { BarChart3, Trophy, AlertTriangle, Users, Calendar,
  PoundSterling, Loader2, ChevronRight, X, BadgeCheck, UserCheck, UserCircle2,
} from 'lucide-react';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';
import InstructorRosterView from './InstructorRosterView';

const WINDOW_OPTIONS = [
  { value: 7,   label: '7d' },
  { value: 30,  label: '30d' },
  { value: 90,  label: '90d' },
];


export default function InstructorsTab({ API, headers }) {
  const { t } = useTranslation();
  const [view, setView] = useState('roster');
  return (
    <div data-testid="mbr-instructors">
      <div className="flex items-end justify-end gap-4 mb-4 flex-wrap">
        <div className="subtab-bar" role="tablist">
          <button type="button" onClick={() => setView('roster')}
            className={`subtab-pill ${view === 'roster' ? 'is-active' : ''}`}
            data-testid="mbr-instructors-tab-roster">
            <UserCircle2 size={12} /> {t('memberships_console.inst_roster', 'Roster')}
          </button>
          <button type="button" onClick={() => setView('performance')}
            className={`subtab-pill ${view === 'performance' ? 'is-active' : ''}`}
            data-testid="mbr-instructors-tab-performance">
            <BarChart3 size={12} /> {t('memberships_console.inst_performance', 'Performance')}
          </button>
          <button type="button" onClick={() => setView('cover')}
            className={`subtab-pill ${view === 'cover' ? 'is-active' : ''}`}
            data-testid="mbr-instructors-tab-cover">
            <AlertTriangle size={12} /> {t('memberships_console.inst_cover_board', 'Cover board')}
          </button>
        </div>
      </div>

      {view === 'roster'     && <InstructorRosterView API={API} headers={headers} />}
      {view === 'performance'&& <PerformanceView     API={API} headers={headers} />}
      {view === 'cover'      && <CoverBoardView      API={API} headers={headers} />}
    </div>
  );
}


function PerformanceView({ API, headers }) {
  const { t } = useTranslation();
  const [days, setDays] = useState(30);
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    axios.get(`${API}/memberships/instructors/performance?days=${days}`, { headers })
      .then((r) => setRows(r.data?.rows || []))
      .catch((e) => notifyApiError(notify, e, t('memberships_console.inst_load_fail', 'Failed to load')))
      .finally(() => setLoading(false));
  }, [API, headers, days]);

  const totals = useMemo(() => rows.reduce((acc, r) => ({
    classes: acc.classes + r.classes_total,
    pay: acc.pay + (r.pay_due_pence || 0),
    bookings: acc.bookings + r.bookings_sum,
    attended: acc.attended + r.attended_sum,
  }), { classes: 0, pay: 0, bookings: 0, attended: 0 }), [rows]);

  return (
    <div>
      <div className="flex items-center gap-2 mb-3 overflow-x-auto -mx-1 px-1 pb-1">
        <span className="text-[10px] uppercase tracking-wider font-bold text-[color:var(--theme-text-muted)] flex-shrink-0">{t('memberships_console.inst_window', 'Window')}</span>
        {WINDOW_OPTIONS.map((o) => (
          <button key={o.value} onClick={() => setDays(o.value)}
            className={`px-2.5 py-1 rounded-md text-[11px] font-bold border transition flex-shrink-0 ${
              days === o.value
                ? 'bg-[var(--color-brand-cyan)] text-[var(--color-surface-darker)] border-[var(--color-brand-cyan)]'
                : 'bg-transparent border-[color:var(--theme-border)] text-[color:var(--theme-text-muted)]'
            }`}
            data-testid={`mbr-instructors-window-${o.value}`}>
            {o.label}
          </button>
        ))}
      </div>

      {loading ? (
        <CenteredSpinner />
      ) : rows.length === 0 ? (
        <div className="rounded-xl border border-dashed border-[color:var(--theme-border)] p-10 text-center" data-testid="mbr-instructors-empty">
          <Trophy size={32} className="mx-auto text-[color:var(--theme-text-muted)] mb-3" />
          <p className="text-sm font-bold">{t('memberships_console.inst_no_activity', 'No instructor activity in the last {{days}} days', { days })}</p>
        </div>
      ) : (
        <>
          {/* Totals strip */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
            <SummaryStat label={t('memberships_console.inst_classes', 'Classes')} value={totals.classes} icon={Calendar} />
            <SummaryStat label={t('memberships_console.inst_bookings', 'Bookings')} value={totals.bookings} icon={Users} />
            <SummaryStat label={t('memberships_console.inst_attended', 'Attended')} value={totals.attended} icon={UserCheck} />
            <SummaryStat label={t('memberships_console.inst_pay_due', 'Pay due')} value={`£${(totals.pay / 100).toFixed(2)}`} icon={PoundSterling} />
          </div>
          {/* Mobile: stacked cards. Desktop: table-like rows. */}
          <div className="space-y-2">
            {rows.map((r, i) => (
              <PerformanceRow key={r.instructor_user_id} row={r} rank={i + 1} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}


function PerformanceRow({ row, rank }) {
  const { t } = useTranslation();
  const fill = row.fill_rate_pct;
  const attRate = row.attendance_rate_pct;
  const noShow = row.no_show_rate_pct;
  return (
    <div className="rounded-xl border border-[color:var(--theme-border)] bg-white/[0.03] p-3 sm:p-4"
      data-testid={`mbr-instructor-${row.instructor_user_id}`}>
      <div className="flex items-start gap-3">
        <div className="flex-shrink-0 w-9 h-9 rounded-full overflow-hidden bg-[rgb(var(--rgb-brand-cyan)/0.15)] grid place-items-center text-[var(--color-brand-cyan)] font-extrabold text-sm">
          {row.avatar_url ? <img src={row.avatar_url} alt={row.name} className="w-full h-full object-cover" />
                          : (row.name || '?').slice(0, 1).toUpperCase()}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <p className="font-bold truncate">{row.name}</p>
            {rank <= 3 && (
              <span className={`text-[9px] font-extrabold uppercase tracking-wider px-1.5 py-0.5 rounded ${
                rank === 1 ? 'bg-amber-500/15 text-amber-500'
                : rank === 2 ? 'bg-zinc-500/15 text-zinc-400'
                : 'bg-orange-500/15 text-orange-500'
              }`}>
                <Trophy size={9} className="inline mr-0.5" /> #{rank}
              </span>
            )}
          </div>
          <p className="text-[11px] text-[color:var(--theme-text-muted)] truncate">{row.email}</p>
        </div>
        <div className="text-right flex-shrink-0">
          <p className="text-base font-extrabold tracking-tight">£{(row.pay_due_pence / 100).toFixed(2)}</p>
          <p className="text-[9px] uppercase tracking-wider font-bold text-[color:var(--theme-text-muted)]">{t('memberships_console.inst_pay_due', 'Pay due')}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mt-3">
        <Metric label={t('memberships_console.inst_classes', 'Classes')} primary={row.classes_total}
          subtitle={t('memberships_console.inst_done_cancelled', '{{done}} done · {{cancelled}} cancelled', { done: row.classes_completed, cancelled: row.classes_cancelled })} />
        <Metric label={t('memberships_console.inst_fill_rate', 'Fill rate')} primary={`${fill}%`} bar={fill}
          tone={fill >= 70 ? 'emerald' : fill >= 40 ? 'amber' : 'red'} />
        <Metric label={t('memberships_console.inst_attendance', 'Attendance')} primary={`${attRate}%`} bar={attRate}
          tone={attRate >= 80 ? 'emerald' : 'amber'} />
        <Metric label={t('memberships_console.inst_no_show', 'No-show')} primary={`${noShow}%`}
          tone={noShow >= 15 ? 'red' : noShow >= 7 ? 'amber' : 'emerald'} />
      </div>
    </div>
  );
}


function Metric({ label, primary, subtitle, bar, tone = 'emerald' }) {
  const tones = {
    emerald: 'bg-emerald-500',
    amber:   'bg-amber-500',
    red:     'bg-red-500',
  };
  return (
    <div className="rounded-lg border border-[color:var(--theme-border)] p-2">
      <p className="text-[9px] uppercase tracking-wider font-bold text-[color:var(--theme-text-muted)]">{label}</p>
      <p className="text-sm font-extrabold mt-0.5">{primary}</p>
      {subtitle && <p className="text-[10px] text-[color:var(--theme-text-muted)] truncate">{subtitle}</p>}
      {bar !== undefined && (
        <div className="h-1 mt-1 rounded bg-zinc-500/15 overflow-hidden">
          <div className={`h-full ${tones[tone]}`}
            style={{ width: `${Math.min(Math.max(bar, 0), 100)}%` }} />
        </div>
      )}
    </div>
  );
}


function SummaryStat({ label, value, icon: Icon }) {
  return (
    <div className="rounded-lg border border-[color:var(--theme-border)] bg-white/[0.03] p-2.5">
      <p className="text-[9px] uppercase tracking-wider font-bold text-[color:var(--theme-text-muted)] flex items-center gap-1">
        {Icon && <Icon size={9} />} {label}
      </p>
      <p className="text-base font-extrabold mt-0.5">{value}</p>
    </div>
  );
}


/* ─────────────────── Cover board ─────────────────── */


function CoverBoardView({ API, headers }) {
  const { t } = useTranslation();
  const [requests, setRequests] = useState([]);
  const [instructors, setInstructors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [assignFor, setAssignFor] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const [reqR, usersR] = await Promise.all([
        axios.get(`${API}/memberships/cover-requests`, { headers }),
        axios.get(`${API}/users?role=instructor`, { headers }).catch(() => ({ data: { users: [] } })),
      ]);
      setRequests(reqR.data?.requests || reqR.data?.cover_requests || []);
      setInstructors(usersR.data?.users || []);
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inst_cover_load_fail', 'Failed to load cover board'));
    }
    setLoading(false);
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: the loader closure(s) re-read live state on every call; the effect re-fires on the listed trigger deps, so adding the function identity would just thrash without changing behaviour.
  useEffect(() => { load();   }, []);

  if (loading) return <CenteredSpinner />;

  if (requests.length === 0) {
    return (
      <div className="rounded-xl border border-dashed border-[color:var(--theme-border)] p-10 text-center" data-testid="mbr-cover-empty">
        <BadgeCheck size={32} className="mx-auto text-emerald-500 mb-3" />
        <p className="text-sm font-bold">{t('memberships_console.inst_no_cover', 'No outstanding cover requests')}</p>
        <p className="text-xs text-[color:var(--theme-text-muted)] mt-1">
          {t('memberships_console.inst_no_cover_hint', "Instructors can request cover from their portal — it'll show here for you to assign.")}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-2" data-testid="mbr-cover-list">
      {requests.map((r) => (
        <CoverRow key={r.id} req={r} onAssign={() => setAssignFor(r)} />
      ))}
      {assignFor && (
        <AssignCoverModal API={API} headers={headers}
          req={assignFor} instructors={instructors}
          onClose={(refresh) => { setAssignFor(null); if (refresh) load(); }} />
      )}
    </div>
  );
}


function CoverRow({ req, onAssign }) {
  const { t } = useTranslation();
  const isOpen = req.status === 'open' || req.status === 'open_to_all';
  return (
    <div className="rounded-xl border border-[color:var(--theme-border)] bg-white/[0.03] p-3 sm:p-4 flex items-start gap-3"
      data-testid={`mbr-cover-${req.id}`}>
      <div className="flex-shrink-0 w-9 h-9 rounded-md bg-amber-500/15 grid place-items-center">
        <AlertTriangle size={14} className="text-amber-500" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-bold text-sm truncate">{req.class_name || t('memberships_console.inst_class', 'Class')} · {req.starts_at && new Date(req.starts_at).toLocaleString([], { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</p>
        <p className="text-[11px] text-[color:var(--theme-text-muted)] mt-0.5 truncate">
          {t('memberships_console.inst_from', 'From')} {req.from_user_name || req.from_user_email || '—'}
          {req.reason && <span className="block sm:inline sm:ml-2">· {req.reason}</span>}
        </p>
      </div>
      {isOpen ? (
        <button onClick={onAssign}
          className="flex-shrink-0 px-3 py-1.5 rounded-md text-[11px] font-extrabold flex items-center gap-1"
          style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-surface-darker)' }}
          data-testid={`mbr-cover-assign-${req.id}`}>
          {t('memberships_console.inst_assign', 'Assign')} <ChevronRight size={11} />
        </button>
      ) : (
        <span className="flex-shrink-0 text-[10px] uppercase tracking-wider font-bold px-2 py-1 rounded bg-emerald-500/15 text-emerald-500">
          {req.status}
        </span>
      )}
    </div>
  );
}


function AssignCoverModal({ API, headers, req, instructors, onClose }) {
  const { t } = useTranslation();
  const [picked, setPicked] = useState('');
  const [busy, setBusy] = useState(false);
  const submit = async () => {
    if (!picked) { notify.error(t('memberships_console.inst_pick', 'Pick an instructor')); return; }
    setBusy(true);
    try {
      await axios.post(`${API}/memberships/cover-requests/${req.id}/assign`,
        { instructor_user_id: picked }, { headers });
      notify.success(t('memberships_console.inst_cover_assigned', 'Cover assigned'));
      onClose(true);
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inst_failed', 'Failed'));
    }
    setBusy(false);
  };
  const eligible = instructors.filter((u) => u.id !== req.from_user_id);

  return (
    <div className="fixed inset-0 z-[80] bg-black/70 grid place-items-end sm:place-items-center p-3" onClick={() => onClose(false)}>
      <div className="bg-[color:var(--theme-surface)] dark:bg-zinc-900 rounded-2xl border border-[color:var(--theme-border)] w-full max-w-md shadow-2xl"
        onClick={(e) => e.stopPropagation()}
        data-testid="mbr-cover-assign-modal">
        <div className="px-5 py-4 border-b border-[color:var(--theme-border)] flex items-start justify-between">
          <div>
            <p className="text-[10px] uppercase tracking-[0.2em] font-extrabold text-amber-500">{t('memberships_console.inst_assign_cover', 'Assign cover')}</p>
            <h3 className="text-lg font-extrabold mt-0.5">{req.class_name}</h3>
            <p className="text-xs text-[color:var(--theme-text-muted)]">
              {req.starts_at && new Date(req.starts_at).toLocaleString()}
            </p>
          </div>
          <button onClick={() => onClose(false)} className="p-1.5 rounded hover:bg-zinc-500/10"><X size={14} /></button>
        </div>
        <div className="p-5 max-h-[60vh] overflow-y-auto">
          {eligible.length === 0 ? (
            <p className="text-sm text-[color:var(--theme-text-muted)]">{t('memberships_console.inst_no_eligible', 'No eligible instructors. Add one in Master Admin → Users.')}</p>
          ) : (
            <div className="space-y-2">
              {eligible.map((u) => (
                <label key={u.id}
                  className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer ${
                    picked === u.id
                      ? 'border-[var(--color-brand-cyan)] bg-[rgb(var(--rgb-brand-cyan)/0.05)]'
                      : 'border-[color:var(--theme-border)] hover:bg-zinc-500/[0.04]'
                  }`}
                  data-testid={`mbr-cover-pick-${u.id}`}>
                  <input type="radio" name="cover-pick" checked={picked === u.id}
                    onChange={() => setPicked(u.id)} className="accent-[var(--color-brand-cyan)]" />
                  <div className="min-w-0 flex-1">
                    <p className="font-bold text-sm truncate">
                      {(u.first_name || '') + ' ' + (u.last_name || '')}
                    </p>
                    <p className="text-[11px] text-[color:var(--theme-text-muted)] truncate">{u.email}</p>
                  </div>
                </label>
              ))}
            </div>
          )}
        </div>
        <div className="px-5 py-4 border-t border-[color:var(--theme-border)] flex justify-end gap-2">
          <button onClick={() => onClose(false)}
            className="px-3 py-2 text-sm font-bold text-[color:var(--theme-text-muted)] hover:text-zinc-900 dark:hover:text-white">
            {t('memberships_console.inst_cancel', 'Cancel')}
          </button>
          <button onClick={submit} disabled={busy || !picked}
            className="px-4 py-2 rounded-md text-sm font-extrabold disabled:opacity-50 flex items-center gap-1"
            style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-surface-darker)' }}
            data-testid="mbr-cover-assign-confirm">
            {busy ? <Loader2 size={11} className="animate-spin" /> : <BadgeCheck size={11} />} {t('memberships_console.inst_assign', 'Assign')}
          </button>
        </div>
      </div>
    </div>
  );
}


function CenteredSpinner() {
  return (
    <div className="flex items-center justify-center py-10 text-[color:var(--theme-text-muted)] text-sm gap-2">
      <Loader2 size={14} className="animate-spin" /> Loading…
    </div>
  );
}

/**
 * Pulse Fitness Memberships — Monthly class invoicing.
 *
 * Two use-cases in one tab:
 *   1. Pick a month → preview what each member would be invoiced for
 *      the classes they booked/attended → generate (and optionally
 *      email) invoices in one click.
 *   2. Browse all previously-generated invoices with status chips and
 *      a "Send" shortcut for drafts.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import { FileText, Mail, Eye, CheckCircle2, Clock, XCircle, Send, RefreshCcw, Users, Calendar, Receipt, Link as LinkIcon, Zap } from 'lucide-react';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';
import EmptyState from '@/components/shared/EmptyState';
import Button from '@/components/shared/Button';

const STATUS_STYLES = {
  draft: 'bg-zinc-500/15 text-zinc-300',
  sent: 'bg-[rgb(var(--rgb-brand-cyan)/0.15)] text-[color:var(--color-brand-cyan)]',
  paid: 'bg-emerald-500/15 text-emerald-300',
  void: 'bg-red-500/15 text-red-300',
};
const STATUS_ICON = { draft: Clock, sent: Send, paid: CheckCircle2, void: XCircle };

function currentPeriod() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function formatPeriodLabel(p) {
  if (!p) return '';
  try {
    const [y, m] = p.split('-').map((s) => parseInt(s, 10));
    return new Date(y, m - 1, 1).toLocaleString('en-GB', { month: 'long', year: 'numeric' });
  } catch {
    return p;
  }
}

function Money({ pence }) {
  const v = typeof pence === 'number' ? pence : 0;
  return <span>£{(v / 100).toFixed(2)}</span>;
}

export default function InvoicingTab({ API, headers }) {
  const { t } = useTranslation();
  const [period, setPeriod] = useState(currentPeriod());
  const [attendedOnly, setAttendedOnly] = useState(false);
  const [includeSmoothed, setIncludeSmoothed] = useState(true);
  const [defaultRate, setDefaultRate] = useState(''); // pounds
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [sendEmail, setSendEmail] = useState(false);
  const [invoices, setInvoices] = useState([]);
  const [invoicesLoading, setInvoicesLoading] = useState(false);
  const [expandedId, setExpandedId] = useState(null);
  const [siblingPct, setSiblingPct] = useState(0);
  const [siblingSaving, setSiblingSaving] = useState(false);
  const [autoPayMembers, setAutoPayMembers] = useState(new Set());
  const [connectStatus, setConnectStatus] = useState(null);

  // Iter 220y — fetch the gym's own Stripe Connect status so the billing
  // screen can reassure operators that member card payments land in their
  // connected account once charges are enabled.
  useEffect(() => {
    let cancel = false;
    (async () => {
      try {
        const { data } = await axios.get(`${API}/stripe-connect/me/status`, { headers });
        if (!cancel) setConnectStatus(data);
      } catch { /* non-fatal */ }
    })();
    return () => { cancel = true; };
  }, [API, headers]);

  // Load sibling-discount setting + auto-pay roster once on mount
  useEffect(() => {
    let cancel = false;
    (async () => {
      try {
        const { data } = await axios.get(`${API}/memberships/billing/sibling-discount`, { headers });
        if (!cancel) setSiblingPct(Number(data?.pct || 0));
      } catch { /* non-fatal */ }
      try {
        const { data } = await axios.get(`${API}/memberships/billing/autopay/members`, { headers });
        if (!cancel) setAutoPayMembers(new Set((data?.members || []).map((m) => m.id)));
      } catch { /* non-fatal */ }
    })();
    return () => { cancel = true; };
  }, [API, headers]);

  const saveSibling = async () => {
    setSiblingSaving(true);
    try {
      const pct = Math.max(0, Math.min(50, Math.round(Number(siblingPct) || 0)));
      await axios.post(`${API}/memberships/billing/sibling-discount`, { pct }, { headers });
      setSiblingPct(pct);
      notify.success(pct === 0 ? t('memberships_console.inv_sibling_disabled', 'Sibling discount disabled') : t('memberships_console.inv_sibling_set', 'Sibling discount set to {{pct}}%', { pct }));
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_sibling_save_fail', 'Could not save sibling discount'));
    } finally {
      setSiblingSaving(false);
    }
  };

  const runPreview = useCallback(async () => {
    setLoading(true);
    setPreview(null);
    try {
      const payload = {
        period,
        include_attended_only: attendedOnly,
        include_smoothed: includeSmoothed,
      };
      if (defaultRate !== '') payload.default_per_class_pence = Math.round(Number(defaultRate) * 100);
      const { data } = await axios.post(`${API}/memberships/billing/monthly-invoice/preview`, payload, { headers });
      setPreview(data);
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_preview_fail', 'Failed to run preview'));
    } finally {
      setLoading(false);
    }
  }, [API, headers, period, attendedOnly, includeSmoothed, defaultRate]);

  const loadInvoices = useCallback(async () => {
    setInvoicesLoading(true);
    try {
      const { data } = await axios.get(`${API}/memberships/billing/invoices`, { headers });
      setInvoices(data.invoices || []);
    } catch {
      // silent — empty state is fine
    } finally {
      setInvoicesLoading(false);
    }
  }, [API, headers]);

  useEffect(() => { loadInvoices(); }, [loadInvoices]);
  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: the loader closure(s) re-read live state on every call; the effect re-fires on the listed trigger deps, so adding the function identity would just thrash without changing behaviour.
  useEffect(() => { runPreview();   }, [period]);

  const generate = async () => {
    if (!preview || !preview.invoices?.length) {
      notify.info(t('memberships_console.inv_nothing', 'Nothing to invoice for this period'));
      return;
    }
    setGenerating(true);
    try {
      const payload = {
        period,
        include_attended_only: attendedOnly,
        include_smoothed: includeSmoothed,
        send_email: sendEmail,
      };
      if (defaultRate !== '') payload.default_per_class_pence = Math.round(Number(defaultRate) * 100);
      const { data } = await axios.post(`${API}/memberships/billing/monthly-invoice/generate`, payload, { headers });
      const em = data.email || {};
      const emailBit = sendEmail
        ? ` · ${t('memberships_console.inv_email_bit', '{{sent}} emailed, {{skipped}} without email, {{failed}} failed', { sent: em.sent, skipped: em.skipped_no_email, failed: em.failed })}`
        : '';
      notify.success(t('memberships_console.inv_generated_ok', 'Generated {{count}} invoice(s)', { count: data.generated_count }) + emailBit);
      await loadInvoices();
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_generate_fail', 'Failed to generate invoices'));
    } finally {
      setGenerating(false);
    }
  };

  const sendOne = async (inv) => {
    try {
      await axios.post(`${API}/memberships/billing/invoices/${inv.id}/send`, {}, { headers });
      notify.success(t('memberships_console.inv_sent_to', 'Sent to {{email}}', { email: inv.member_email }));
      await loadInvoices();
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_send_fail', 'Send failed'));
    }
  };

  const copyPayLink = async (inv) => {
    try {
      const { data } = await axios.post(`${API}/memberships/billing/invoices/${inv.id}/checkout`, {}, { headers });
      try { await navigator.clipboard.writeText(data.checkout_url); } catch { /* fall through */ }
      notify.success(t('memberships_console.inv_paylink_copied', 'Pay link copied to clipboard'));
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_paylink_fail', 'Could not create pay link'));
    }
  };

  const setStatus = async (inv, status) => {
    try {
      await axios.patch(`${API}/memberships/billing/invoices/${inv.id}/status`, { status }, { headers });
      await loadInvoices();
    } catch (e) {
      notifyApiError(notify, e, t('memberships_console.inv_status_fail', 'Status update failed'));
    }
  };

  // Month picker options — last 12 + current + next
  const periodOptions = useMemo(() => {
    const opts = [];
    const now = new Date();
    for (let i = -12; i <= 1; i += 1) {
      const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
      const v = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      opts.push({ v, label: formatPeriodLabel(v) });
    }
    return opts.reverse();
  }, []);

  return (
    <div data-testid="mbr-invoicing">
      {/* Iter 216h245 — sub-header removed (Billing eyebrow + H1 +
          description). The tab pill above already names this section. */}

      {/* Iter 220y — payouts reassurance once Stripe Connect is live */}
      {connectStatus?.charges_enabled && (
        <div
          className="mb-4 rounded-xl border border-emerald-300 bg-emerald-50 px-4 py-3 flex items-start gap-3"
          data-testid="mbr-billing-payouts-banner"
        >
          <CheckCircle2 size={18} className="text-emerald-600 shrink-0 mt-0.5" />
          <div className="text-sm text-emerald-900">
            <span className="font-bold">{t('memberships_console.inv_payouts_title', 'Payouts go straight to your Stripe account.')}</span>{' '}
            {typeof connectStatus.platform_fee_percent === 'number'
              ? t('memberships_console.inv_payouts_desc_fee', 'Member card payments are deposited into your connected Stripe account minus a {{fee}}% platform fee, and paid out by Stripe on your schedule.', { fee: connectStatus.platform_fee_percent })
              : t('memberships_console.inv_payouts_desc', 'Member card payments are deposited into your connected Stripe account, and paid out by Stripe on your schedule.')}
          </div>
        </div>
      )}

      {/* Controls */}
      <div className="rounded-xl border border-[color:var(--theme-border)] p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <label className="block">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_period', 'Period')}</span>
          <select value={period} onChange={(e) => setPeriod(e.target.value)}
            className="mt-1 w-full rounded-lg border border-[color:var(--theme-border)] bg-transparent px-2 py-2 text-sm"
            data-testid="mbr-invoicing-period">
            {periodOptions.map((p) => (<option key={p.v} value={p.v}>{p.label}</option>))}
          </select>
        </label>
        <label className="block">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_default_rate', 'Default £/class (blank = auto)')}</span>
          <input type="number" step="0.01" value={defaultRate} onChange={(e) => setDefaultRate(e.target.value)}
            className="mt-1 w-full rounded-lg border border-[color:var(--theme-border)] bg-transparent px-2 py-2 text-sm"
            placeholder={t('memberships_console.inv_default_rate_ph', 'Auto — lowest PAYG plan')}
            data-testid="mbr-invoicing-rate" />
        </label>
        <label className="flex items-center gap-2 mt-5 text-sm">
          <input type="checkbox" checked={attendedOnly} onChange={(e) => setAttendedOnly(e.target.checked)}
            data-testid="mbr-invoicing-attended-only" />
          <span className="text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_attended_only', 'Attended classes only')}</span>
        </label>
        <label className="flex items-center gap-2 mt-5 text-sm">
          <input type="checkbox" checked={includeSmoothed} onChange={(e) => setIncludeSmoothed(e.target.checked)}
            data-testid="mbr-invoicing-smoothed" />
          <span className="text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_include_smoothed', 'Include pro-rata plan installments')}</span>
        </label>
      </div>

      {/* Summary + actions */}
      <div className="mt-4 flex flex-wrap items-center gap-3">
        <Button
          variant="secondary" size="md" icon={RefreshCcw}
          loading={loading}
          onClick={runPreview} disabled={loading}
          data-testid="mbr-invoicing-refresh"
        >
          {loading ? t('memberships_console.inv_loading', 'Loading…') : t('memberships_console.inv_refresh_preview', 'Refresh preview')}
        </Button>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" checked={sendEmail} onChange={(e) => setSendEmail(e.target.checked)}
            data-testid="mbr-invoicing-send-email" />
          <span>{t('memberships_console.inv_email_after', 'Email invoices to members after generating')}</span>
        </label>
        {/* Iter 215z — Sibling discount setting */}
        <div className="flex items-center gap-2 text-sm sm:ml-2 sm:pl-3 sm:border-l border-[color:var(--theme-border)] flex-wrap"
          data-testid="mbr-invoicing-sibling-discount">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)]">
            {t('memberships_console.inv_sibling_discount', 'Sibling discount')}
          </span>
          <input type="number" min="0" max="50" step="1" value={siblingPct}
            onChange={(e) => setSiblingPct(e.target.value)}
            className="w-16 rounded-lg border border-[color:var(--theme-border)] bg-transparent px-2 py-1 text-sm text-right"
            data-testid="mbr-invoicing-sibling-input"
            title={t('memberships_console.inv_sibling_title', "Percent off each sibling beyond the 1st child in a family's monthly invoice")} />
          <span className="text-xs text-[color:var(--theme-text-muted)]">%</span>
          <Button
            variant="secondary" size="sm"
            onClick={saveSibling} disabled={siblingSaving}
            data-testid="mbr-invoicing-sibling-save"
          >
            {siblingSaving ? t('memberships_console.inv_saving', 'Saving…') : t('memberships_console.inv_save', 'Save')}
          </Button>
        </div>
        <div className="ml-auto">
          <Button
            variant="primary" size="md" icon={Receipt}
            loading={generating}
            onClick={generate} disabled={generating || !preview?.invoices?.length}
            data-testid="mbr-invoicing-generate"
          >
            {generating ? t('memberships_console.inv_generating', 'Generating…') : t('memberships_console.inv_generate', 'Generate invoices')}
          </Button>
        </div>
      </div>

      {/* Preview table */}
      {preview && (
        <div className="mt-4 rounded-xl border border-[color:var(--theme-border)] overflow-hidden" data-testid="mbr-invoicing-preview">
          <div className="flex items-center gap-4 p-3 text-xs font-bold text-[color:var(--theme-text-muted)] bg-[rgb(var(--rgb-brand-cyan)/0.06)]">
            <div className="flex items-center gap-1.5"><Users size={12} />{t('memberships_console.inv_member_count', '{{count}} members', { count: preview.member_count })}</div>
            <div className="flex items-center gap-1.5"><Calendar size={12} />{formatPeriodLabel(preview.period)}</div>
            <div className="ml-auto flex items-center gap-1.5 text-[color:var(--color-brand-cyan)]">
              <FileText size={12} />{t('memberships_console.inv_total', 'Total:')} <Money pence={preview.total_pence} />
            </div>
          </div>
          {preview.invoices?.length === 0 ? (
            <div className="p-8 text-center text-sm text-[color:var(--theme-text-muted)]">
              {t('memberships_console.inv_no_activity', 'No members have bookable activity in {{period}} yet.', { period: formatPeriodLabel(preview.period) })}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm min-w-[680px]">
                <thead>
                  <tr className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)] border-b border-[color:var(--theme-border)]">
                    <th className="px-3 py-2 text-left">{t('memberships_console.inv_col_member', 'Member')}</th>
                    <th className="px-3 py-2 text-left">{t('memberships_console.inv_col_email', 'Email')}</th>
                    <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_classes', 'Classes')}</th>
                    <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_subtotal', 'Subtotal')}</th>
                    <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_smoothed', 'Smoothed')}</th>
                    <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_total', 'Total')}</th>
                  </tr>
                </thead>
                <tbody>
                  {preview.invoices.map((row) => (
                    <React.Fragment key={row.member_id}>
                      <tr className="border-b border-[color:var(--theme-border)] hover:bg-[rgb(var(--rgb-brand-cyan)/0.04)]"
                        data-testid={`mbr-invoicing-preview-row-${row.member_id}`}>
                        <td className="px-3 py-2 font-semibold">
                          <div className="flex items-center gap-1.5">
                            <span>{row.member_name}</span>
                            {autoPayMembers.has(row.member_id) && (
                              <span title={t('memberships_console.inv_autopay_title', 'Auto-Bill enabled — will charge on the 1st')}
                                className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wider bg-emerald-500/20 text-emerald-300"
                                data-testid={`mbr-invoicing-autopay-${row.member_id}`}>
                                <Zap size={9} />{t('memberships_console.inv_auto', 'Auto')}
                              </span>
                            )}
                          </div>
                          {(row.attendees?.length || 0) > 1 && (
                            <div className="mt-1 flex flex-wrap gap-1" data-testid={`mbr-invoicing-attendees-${row.member_id}`}>
                              {row.attendees.filter((a) => a.attendee_kind !== 'smoothed').map((a) => (
                                <span key={a.attendee_name + (a.attendee_sub_profile_id || '')}
                                  className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-white/5">
                                  {a.attendee_name} · £{(a.subtotal_pence / 100).toFixed(2)}
                                </span>
                              ))}
                            </div>
                          )}
                        </td>
                        <td className="px-3 py-2 text-[color:var(--theme-text-muted)] text-xs">{row.member_email || '—'}</td>
                        <td className="px-3 py-2 text-right tabular-nums">{row.line_count}</td>
                        <td className="px-3 py-2 text-right tabular-nums"><Money pence={row.subtotal_pence} /></td>
                        <td className="px-3 py-2 text-right tabular-nums">{row.smoothed_pence ? <Money pence={row.smoothed_pence} /> : '—'}</td>
                        <td className="px-3 py-2 text-right font-extrabold tabular-nums"><Money pence={row.total_pence} /></td>
                      </tr>
                    </React.Fragment>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Generated invoices */}
      <div className="mt-10 flex items-end justify-between gap-4">
        <div>
          <div className="text-[10px] font-bold uppercase tracking-[0.22em] text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_history', 'History')}</div>
          <h3 className="mt-1 text-xl font-black tracking-tight">{t('memberships_console.inv_generated_invoices', 'Generated invoices')}</h3>
        </div>
        <button onClick={loadInvoices}
          className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-bold border border-[color:var(--theme-border)]"
          data-testid="mbr-invoicing-history-refresh">
          <RefreshCcw size={12} /> {t('memberships_console.inv_refresh', 'Refresh')}
        </button>
      </div>
      <div className="mt-3 rounded-xl border border-[color:var(--theme-border)] overflow-hidden" data-testid="mbr-invoicing-history">
        {invoicesLoading ? (
          <div className="p-8 text-center text-sm text-[color:var(--theme-text-muted)]">{t('memberships_console.inv_loading', 'Loading…')}</div>
        ) : invoices.length === 0 ? (
          <div className="p-2">
            <EmptyState
              icon={Receipt}
              title={t('memberships_console.inv_empty_title', 'No invoices generated yet')}
              hint={t('memberships_console.inv_empty_hint', 'Pick a period above and click Preview to see what each member owes for the classes they booked or attended. Generate in one click — emails optional.')}
              testId="mbr-invoicing-empty"
            />
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[720px]">
              <thead>
              <tr className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)] border-b border-[color:var(--theme-border)]">
                <th className="px-3 py-2 text-left">{t('memberships_console.inv_period', 'Period')}</th>
                <th className="px-3 py-2 text-left">{t('memberships_console.inv_col_member', 'Member')}</th>
                <th className="px-3 py-2 text-left">{t('memberships_console.inv_col_status', 'Status')}</th>
                <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_lines', 'Lines')}</th>
                <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_total', 'Total')}</th>
                <th className="px-3 py-2 text-right">{t('memberships_console.inv_col_actions', 'Actions')}</th>
              </tr>
            </thead>
            <tbody>
              {invoices.map((inv) => {
                const Icon = STATUS_ICON[inv.status] || Clock;
                const expanded = expandedId === inv.id;
                return (
                  <React.Fragment key={inv.id}>
                    <tr className="border-b border-[color:var(--theme-border)] hover:bg-[rgb(var(--rgb-brand-cyan)/0.04)]"
                      data-testid={`mbr-invoicing-inv-${inv.id}`}>
                      <td className="px-3 py-2 font-semibold">{formatPeriodLabel(inv.period)}</td>
                      <td className="px-3 py-2">
                        <div className="flex items-center gap-1.5">
                          <div className="font-semibold">{inv.member_name}</div>
                          {autoPayMembers.has(inv.member_id) && (
                            <span title={t('memberships_console.inv_autopay_title', 'Auto-Bill enabled — will charge on the 1st')}
                              className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wider bg-emerald-500/20 text-emerald-300"
                              data-testid={`mbr-invoicing-history-autopay-${inv.id}`}>
                              <Zap size={9} />{t('memberships_console.inv_auto', 'Auto')}
                            </span>
                          )}
                        </div>
                        <div className="text-xs text-[color:var(--theme-text-muted)]">{inv.member_email || '—'}</div>
                      </td>
                      <td className="px-3 py-2">
                        <span className={`inline-flex items-center gap-1 rounded px-2 py-0.5 text-[10px] font-bold uppercase ${STATUS_STYLES[inv.status] || 'bg-zinc-500/15'}`}>
                          <Icon size={10} />{t(`memberships_console.inv_status_${inv.status}`, inv.status)}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-right tabular-nums">{inv.lines?.length || 0}</td>
                      <td className="px-3 py-2 text-right font-extrabold tabular-nums"><Money pence={inv.total_pence} /></td>
                      <td className="px-3 py-2 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <button onClick={() => setExpandedId(expanded ? null : inv.id)}
                            className="p-1.5 rounded hover:bg-white/10 text-[color:var(--theme-text-muted)]"
                            title={expanded ? t('memberships_console.inv_hide', 'Hide') : t('memberships_console.inv_view_lines', 'View lines')}
                            data-testid={`mbr-invoicing-view-${inv.id}`}>
                            <Eye size={12} />
                          </button>
                          {inv.status === 'draft' && inv.member_email && (
                            <button onClick={() => sendOne(inv)}
                              className="p-1.5 rounded hover:bg-white/10 text-[color:var(--color-brand-cyan)]"
                              title={t('memberships_console.inv_send_email', 'Send by email')}
                              data-testid={`mbr-invoicing-send-${inv.id}`}>
                              <Mail size={12} />
                            </button>
                          )}
                          {inv.status !== 'paid' && inv.status !== 'void' && (
                            <button onClick={() => copyPayLink(inv)}
                              className="p-1.5 rounded hover:bg-white/10 text-emerald-300"
                              title={t('memberships_console.inv_copy_paylink', 'Copy Stripe pay-link')}
                              data-testid={`mbr-invoicing-paylink-${inv.id}`}>
                              <LinkIcon size={12} />
                            </button>
                          )}
                          {inv.status === 'sent' && (
                            <button onClick={() => setStatus(inv, 'paid')}
                              className="px-2 py-1 rounded text-[10px] font-bold bg-emerald-500/15 text-emerald-300 hover:bg-emerald-500/25"
                              data-testid={`mbr-invoicing-mark-paid-${inv.id}`}>
                              {t('memberships_console.inv_mark_paid', 'Mark paid')}
                            </button>
                          )}
                          {inv.status !== 'paid' && inv.status !== 'void' && (
                            <button onClick={() => setStatus(inv, 'void')}
                              className="px-2 py-1 rounded text-[10px] font-bold bg-red-500/10 text-red-300 hover:bg-red-500/20"
                              data-testid={`mbr-invoicing-void-${inv.id}`}>
                              {t('memberships_console.inv_void', 'Void')}
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                    {expanded && (
                      <tr>
                        <td colSpan={6} className="bg-[rgb(var(--rgb-brand-cyan)/0.03)] px-6 py-3">
                          <div className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--theme-text-muted)] mb-1">{t('memberships_console.inv_line_items', 'Line items')}</div>
                          {(inv.attendees && inv.attendees.filter((a) => a.attendee_kind !== 'smoothed').length > 1) ? (
                            (() => {
                              const groups = {};
                              (inv.lines || []).forEach((l) => {
                                const key = l.kind === 'class' ? (l.attendee_name || 'Account') : 'Account';
                                (groups[key] = groups[key] || []).push(l);
                              });
                              return Object.entries(groups).map(([name, rows]) => {
                                const sub = rows.reduce((s, r) => s + (r.amount_pence || 0), 0);
                                return (
                                  <div key={name} className="mt-2">
                                    <div className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-[color:var(--color-brand-cyan)] mb-1">
                                      {name} · £{(sub / 100).toFixed(2)}
                                    </div>
                                    {rows.map((l, idx) => (
                                      <div key={idx} className="flex justify-between text-xs py-1 border-b border-[color:var(--theme-border)] last:border-0 pl-3">
                                        <span>{l.description}</span>
                                        <span className="tabular-nums font-semibold"><Money pence={l.amount_pence} /></span>
                                      </div>
                                    ))}
                                  </div>
                                );
                              });
                            })()
                          ) : (
                            (inv.lines || []).map((l, idx) => (
                              <div key={idx} className="flex justify-between text-xs py-1 border-b border-[color:var(--theme-border)] last:border-0">
                                <span>{l.description}</span>
                                <span className="tabular-nums font-semibold"><Money pence={l.amount_pence} /></span>
                              </div>
                            ))
                          )}
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
        )}
      </div>
    </div>
  );
}

/**
 * Pulse Fitness Memberships — Operator console.
 *
 * Tabbed SPA page: Dashboard · Members · Timetable · Plans. Reuses the
 * operator JWT already in localStorage (set by the standard Pulse/Gym
 * login). Dark Pulse Fitness aesthetic — cyan accent, slate surfaces.
 *
 * Phase 1a scope: list + create + key actions. Deeper flows (sell plan,
 * refund, comms) land in Phase 1b.
 */
import React, { Suspense, lazy, useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, Link, useParams, useSearchParams } from 'react-router-dom';
import axios from 'axios';
import { notify, useConfirm } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';
import { useTranslation } from 'react-i18next';
import {
  LayoutDashboard, Users, Users as UsersIcon, Calendar, PackageOpen, Plus, X, ChevronLeft,
  ChevronRight, Pause, XOctagon, Activity, Sparkles, CheckCircle2, Edit3, Trash2, Dumbbell, Link as LinkIcon, Copy, Megaphone, BarChart3, Printer, Settings, Tag, ClipboardCheck, Workflow, Smartphone, ReceiptPoundSterling as Receipt, Wand2, HeartHandshake, Theater, Loader2, Wallet, Mail, AlertCircle, Bot, ShieldCheck,
} from 'lucide-react';
import { useAuth } from '@/App';
import EmptyState from '@/components/shared/EmptyState';
import Button from '@/components/shared/Button';
import RowActions from '@/components/shared/RowActions';
import ListPanel from '@/components/shared/ListPanel';
import InvitePortalButton from '@/components/memberships/InvitePortalButton';
import ExportCsvButton from '@/components/shared/ExportCsvButton';
import {
  Header, Kpi, StatusPill, CapacityBar, Loading, Empty, Input, Select, ModalShell, ModalActions,
} from '@/pages/Memberships/_shared';
import AddMemberModal from '@/pages/Memberships/modals/AddMemberModal';
import PlanEditorModal from '@/pages/Memberships/modals/PlanEditorModal';
import ClassEditorModal from '@/pages/Memberships/modals/ClassEditorModal';
import SavedViewsDropdown from '@/components/memberships/SavedViewsDropdown';
import MembersBulkBar from '@/components/memberships/MembersBulkBar';
import PullToRefresh from '@/components/shared/PullToRefresh';
import Navbar from '@/components/shared/Navbar';
import MobileBottomNav from '@/components/shared/MobileBottomNav';
import ModuleSwitcher, { hasModuleAccess } from '@/components/shared/ModuleSwitcher';
import ModulePageHeader from '@/components/shared/ModulePageHeader';
import CrossModuleTipsBanner from '@/components/shared/CrossModuleTipsBanner';
import ModuleAccessGate from '@/components/shared/ModuleAccessGate';
import HelpHint from '@/components/HelpHint';
import TourConversionTile from '@/pages/Memberships/TourConversionTile';
