  return (
    <div className="mt-5 rounded-xl border border-[rgb(var(--rgb-brand-cyan)/0.3)] bg-gradient-to-br from-[rgb(var(--rgb-brand-cyan)/0.1)] to-transparent overflow-hidden" data-testid="mbr-app-url-card">
