                      <option key={u.orbit4_user_id} value={u.orbit4_user_id}>
                        {`${u.first_name || ''} ${u.last_name || ''}`.trim() || u.email || t('service.o4_user_n', 'User {{n}}', { n: u.orbit4_user_id })}
