            <p className="text-xs text-white/60">
              {t('service.eng_home_v2_stats', '{{today}} today · {{upcoming}} upcoming · {{new}} new', { today: kpis.today_jobs || 0, upcoming: kpis.upcoming_jobs || 0, new: kpis.notifications_unread || 0 })}
            </p>
