// Iter 220dp · ReturnToFixCard — top-of-Complete gate. "Yes" stays
// out of the way (collapsed default state), "No, need to return"
// expands into a date picker + reason + customer-notify toggle and
// posts to the new ``return-to-fix`` endpoint.
function ReturnToFixCard({ job, onRescheduled }) {
  const { t } = useTranslation();
  const existing = job.return_to_fix || null;
  const [mode, setMode] = useState(existing ? 'no' : null);
  const [busy, setBusy] = useState(false);
  const defaultReturnAt = useMemo(() => {
    const d = new Date();
    d.setDate(d.getDate() + 2);
    d.setHours(9, 0, 0, 0);
    // datetime-local needs YYYY-MM-DDTHH:mm
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  }, []);
  const [returnAt, setReturnAt] = useState(
    existing?.return_at ? existing.return_at.slice(0, 16) : defaultReturnAt,
  );
  const [reason, setReason] = useState(existing?.reason || '');
  const [notifyCustomer, setNotifyCustomer] = useState(true);

  const submit = async () => {
    if (!returnAt) { notify.error(t('service.eng_jd_rtf_pick_date', 'Pick a return date')); return; }
    setBusy(true);
    try {
      const iso = new Date(returnAt).toISOString();
      await axios.post(
        `${API}/svc/engineer/jobs/${job.id}/return-to-fix`,
        {
          return_at: iso,
          reason: reason.trim(),
          notify_customer: notifyCustomer,
        },
        auth(),
      );
      await onRescheduled?.();
    } catch (e) {
      notify.error(e?.response?.data?.detail || t('service.eng_jd_rtf_failed', 'Could not schedule return'));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      className="bg-white rounded-2xl border border-slate-200 p-4"
      data-testid="complete-return-to-fix"
    >
      <p className="text-[11px] uppercase font-bold tracking-wide text-slate-500 mb-2">
        {t('service.eng_jd_rtf_question', 'Did you fix it on this visit?')}
      </p>
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => setMode('yes')}
          className={`px-3 py-1.5 rounded-full text-xs font-bold border ${
            mode === 'yes'
              ? 'bg-emerald-600 text-white border-emerald-600'
              : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50'
          }`}
          data-testid="rtf-yes"
        >
          {t('service.eng_jd_rtf_yes', 'Yes — closing today')}
        </button>
        <button
          type="button"
          onClick={() => setMode('no')}
          className={`px-3 py-1.5 rounded-full text-xs font-bold border ${
            mode === 'no'
              ? 'bg-rose-600 text-white border-rose-600'
              : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50'
          }`}
          data-testid="rtf-no"
        >
          {t('service.eng_jd_rtf_no', 'No — need a return visit')}
        </button>
      </div>

      {mode === 'no' && (
        <div className="mt-3 space-y-2" data-testid="rtf-form">
          <label className="block">
            <span className="block text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1">
              {t('service.eng_jd_rtf_return_date', 'Return date')}
            </span>
            <input
              type="datetime-local"
              value={returnAt}
              onChange={(e) => setReturnAt(e.target.value)}
              className="w-full text-sm border border-slate-200 rounded-lg px-3 py-2 bg-white"
              data-testid="rtf-return-at"
            />
          </label>
          <label className="block">
            <span className="block text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1">
              {t('service.eng_jd_rtf_why', 'Why a return visit?')}
            </span>
            <textarea
              rows={2}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={t('service.eng_jd_rtf_reason_ph', 'Parts on order · waiting on spec · need 2-person lift…')}
              className="w-full text-sm border border-slate-200 rounded-lg px-3 py-2 bg-white"
              data-testid="rtf-reason"
            />
          </label>
          <label className="flex items-center gap-2 text-xs text-slate-700 select-none">
            <input
              type="checkbox"
              checked={notifyCustomer}
              onChange={(e) => setNotifyCustomer(e.target.checked)}
              data-testid="rtf-notify-customer"
            />
            {t('service.eng_jd_rtf_notify', 'Notify the customer of the new return time')}
          </label>
          <button
            type="button"
            onClick={submit}
            disabled={busy}
            className="w-full inline-flex items-center justify-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-br from-rose-600 to-rose-700 text-white text-sm font-bold disabled:opacity-50"
            data-testid="rtf-submit"
          >
            {busy ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
            {t('service.eng_jd_rtf_submit', 'Reschedule + notify customer')}
          </button>
          {existing && (
            <p className="text-[11px] text-slate-500" data-testid="rtf-existing">
              {t('service.eng_jd_rtf_existing', 'A return is already booked — submitting again will refresh the date and re-notify the customer.')}
            </p>
          )}
        </div>
      )}
    </div>
  );
}


function CompleteTab({ job, locked, onChange, navigate, draft, setDraft, clearDraft }) {
  const { t } = useTranslation();
  // Iter 220c — Use the parent's lifted draft so tab switches NEVER
  // lose typed text. Falls back to the case's stored values on first
  // open so engineers see what was previously persisted.
  const summary = draft.summary !== undefined ? draft.summary : (job.resolution_notes || '');
  const target = draft.target || 'awaiting_sign_off';
  const customFields = draft.custom_fields || {};
  const autoInvoice = draft.auto_invoice === undefined ? true : !!draft.auto_invoice;

  const [signatureData, setSignatureData] = useState('');
  const [busy, setBusy] = useState(false);
  const [draftResult, setDraftResult] = useState(null);
  const [signoffInfo, setSignoffInfo] = useState({ site_contact: null, signoff: null });
  useEffect(() => {
    axios.get(`${API}/svc/engineer/jobs/${job.id}/signoff`, auth()).then((r) => setSignoffInfo(r.data)).catch(() => {});
  }, [job.id]);
  const signoffCheck = () => buildSignoffPayload({ draft, signatureData, existing: signoffInfo.signoff, job });

  const setSummary = (v) => setDraft({ summary: v });
  const setTarget = (v) => setDraft({ target: v });
  const setReport = (patch) => setDraft((prev) => ({ ...prev, report: { ...(prev?.report || {}), ...patch } }));
  const reportDefaults = useMemo(() => {
    const entries = (job.time_entries || []).filter((e) => e.start_at);
    const starts = entries.map((e) => e.start_at).sort();
    const open = entries.some((e) => !e.end_at);
    const ends = entries.map((e) => e.end_at).filter(Boolean).sort();
    return { start: starts[0] || job.arrived_at || '', end: open || !ends.length ? '' : ends[ends.length - 1] };
  }, [job]);
  const buildReport = () => ({ ...withReportDefaults(draft.report, reportDefaults.start, reportDefaults.end), work_completed: summary.trim() });
  const reportCheck = () => {
    const r = buildReport();
    if (!r.start_time || !r.end_time) return 'Add the start and end time';
    return reportTimeError(r);
  };
  const searchParts = useCallback(async (q) => {
    const r = await axios.get(`${API}/svc/parts/catalogue?search=${encodeURIComponent(q)}&page_size=6`, auth());
    return r.data?.items || [];
  }, []);
  // Iter 220ea·3 — kept for symmetry with the other draft setters
  // (other tabs use it for editable custom-field rows). Unused at
  // close-out time, but harmless to keep.
  const _setCustomFields = (patchOrFn) => setDraft((prev) => ({
    ...prev,
    custom_fields: typeof patchOrFn === 'function'
      ? patchOrFn(prev?.custom_fields || {})
      : patchOrFn,
  }));
  const setAutoInvoice = (v) => setDraft({ auto_invoice: !!v });

  // Iter 220e0 — Cover-aware close-out. When the case sits under an
  // active contract or warranty we should not be defaulting to
  // "Close & invoice" — the gym already pays for cover. Engineers
  // can still tick "Misuse — bill anyway" for chargeable misuse, but
  // that's now an explicit override rather than the default.
  // Iter 220e1 — shared with the JobAtAGlance cover banner so both
  // surfaces tell the same story.
  const coverState = useMemo(() => computeCoverState(job), [job]);

  // When the case is covered we treat "misuse" as the chargeable
  // override. Stored on the draft so it autosaves like any other
  // close-out field.
  const misuseOverride = !!draft.misuse_override;
  const setMisuseOverride = (v) => setDraft({ misuse_override: !!v });

  // Effective "should we bill?" — covered cases default to no-bill;
  // misuse override flips it. Non-covered keep the existing
  // auto_invoice toggle.
  const willBill = coverState.covered ? misuseOverride : autoInvoice;
  const willGenerateInvoice = coverState.covered ? misuseOverride : autoInvoice;

  const complete = async () => {
    if (!summary.trim()) { notify.error(t('service.eng_jd_add_summary', 'Add a description of the work completed')); return; }
    if (reportCheck()) { notify.error(reportCheck()); return; }
    const so = signoffCheck();
    if (so.error) { notify.error(so.error); return; }
    setBusy(true);
    try {
      if (so.payload) {
        await outboxPost(`${API}/svc/engineer/signature`, { ...so.payload, summary: summary.trim() },
          { headers: auth().headers, kind: 'signature', label: `Sign-off · ${job.reference || job.id}` });
      }
      const completeRes = await outboxPost(`${API}/svc/engineer/jobs/${job.id}/complete`, {
        summary: summary.trim(), target,
        // Iter 220e0 — chargeable now follows cover state, not always true.
        chargeable: willBill,
        custom_fields: customFields,
        report: buildReport(),
      }, { headers: auth().headers, kind: 'job_complete',
          label: `Complete · ${job.reference || job.id}` });
      if (completeRes?.queued) {
        notify.success(t('service.eng_jd_saved_offline_sync', 'Saved offline — will sync when back online'),
                       t('service.eng_jd_queued_complete', 'Queued: Complete {{ref}}', { ref: job.reference || job.id }));
      } else {
        notify.success(t('service.eng_jd_job_completed', 'Job completed'));
      }
      if (willGenerateInvoice) {
        try {
          const r = await axios.post(
            `${API}/svc/engineer/jobs/${job.id}/generate-invoice-draft`, {}, auth(),
          );
          setDraftResult(r.data);
          notify.success(t('service.eng_jd_draft_created', 'Draft {{num}} created', { num: r.data.invoice_number }));
        } catch (e) {
          const m = e?.response?.data?.detail || t('service.eng_jd_no_chargeable', 'No chargeable lines yet');
          notify.error(t('service.eng_jd_draft_skipped_msg', 'Invoice draft skipped: {{msg}}', { msg: m }));
        }
      }
      // Iter 220c — flush the autosave draft now that the job is wrapped.
      await clearDraft?.();
      await onChange();
    } catch (e) {
      notify.error(e?.response?.data?.detail || t('service.eng_jd_complete_failed', 'Could not complete job'));
    } finally { setBusy(false); }
  };

  // Iter 220cv — "I'm done — send the invoice" one-tap close-out.
  // Runs the full close-of-day sequence in one button: stop the
  // on-site timer (if still running) → complete the job → generate
  // the invoice draft → email the branded service report to the
  // customer. Each step is wrapped in its own try so a single
  // failure (e.g. no parts allocated yet) doesn't break the chain.
  const completeAndSendInvoice = async () => {
    if (!summary.trim()) { notify.error(t('service.eng_jd_add_summary_first', 'Add a description of the work completed first')); return; }
    if (reportCheck()) { notify.error(reportCheck()); return; }
    const so = signoffCheck();
    if (so.error) { notify.error(so.error); return; }
    setBusy(true);
    try {
      // 1. Stop any active on-site timer.
      const active = (job.time_entries || []).find(
        e => !e.end_at && (e.category === 'on_site' || e.category === 'travel'),
      );
      if (active) {
        try {
          await engineerSendOrQueue({
            method: 'POST',
            path: '/svc/engineer/time/stop',
            body: { entry_id: active.id },
            label: 'Stop timer (close-out)',
          });
        } catch { /* non-blocking */ }
      }
      // 2. Customer sign-off (required).
      if (so.payload) {
        await axios.post(`${API}/svc/engineer/signature`, { ...so.payload, summary: summary.trim() }, auth());
      }
      // 3. Complete the job. Cover-aware: covered + no-misuse cases
      //    close out as "repaired" with chargeable=false; everything
      //    else stays on the original "closed + chargeable" path.
      const fastTarget = coverState.covered && !misuseOverride ? 'repaired' : 'closed';
      await axios.post(`${API}/svc/engineer/jobs/${job.id}/complete`, {
        summary: summary.trim(),
        target: fastTarget,
        chargeable: willBill,
        custom_fields: customFields,
        report: buildReport(),
        email_report: false,
      }, auth());
      // 4. Generate the invoice draft — ONLY when we're actually billing.
      let inv = null;
      if (willBill) {
        try {
          const r = await axios.post(
            `${API}/svc/engineer/jobs/${job.id}/generate-invoice-draft`, {}, auth(),
          );
          inv = r.data;
          setDraftResult(inv);
        } catch (e) {
          notify.error(t('service.eng_jd_draft_skipped', 'Invoice draft skipped'), e?.response?.data?.detail || e?.message);
        }
      }
      // 5. Email the branded service report (matches the "Email report"
      // button on the report card — same backend endpoint).
      try {
        await axios.post(`${API}/svc/cases/${job.id}/service-report/email`, {}, auth());
        notify.success(
          t('service.eng_jd_sent_customer', 'Sent to customer'),
          inv ? t('service.eng_jd_sent_invoice', 'Invoice {{num}} created · service report emailed.', { num: inv.invoice_number })
              : (coverState.covered && !misuseOverride
                  ? t('service.eng_jd_sent_no_charge', 'Service report emailed · no charge (under cover).')
                  : t('service.eng_jd_sent_report', 'Service report emailed.')),
        );
      } catch (e) {
        notify.error(t('service.eng_jd_report_email_failed', 'Report email failed'), e?.response?.data?.detail || e?.message);
      }
      // 6. Iter 220cy — Fire the NPS feedback request. Lands the
      // customer on the public tracking page where the 5-star + NPS
      // form already lives. Soft-fail so a missing email never
      // blocks the close-out.
      try {
        await axios.post(`${API}/svc/cases/${job.id}/feedback-request/send`, {}, auth());
      } catch { /* non-blocking */ }
      await clearDraft?.();
      await onChange();
    } catch (e) {
      notify.error(e?.response?.data?.detail || t('service.eng_jd_close_failed', 'Could not close the job'));
    } finally { setBusy(false); }
  };

  if (locked) {
    // Iter 220ed — read-only recap for a closed job: work summary +
    // captured customer signature + report actions. Nothing editable.
    const sig = job.signature || null;
    const summaryText = job.fix_summary || (sig && sig.summary) || '';
    return (
      <div className="space-y-4" data-testid="complete-locked">
        <div className="bg-white rounded-2xl border border-slate-200 p-5">
          <div className="flex items-center gap-2">
            <CheckCircle2 size={20} className="text-emerald-500" />
            <p className="text-sm font-bold text-slate-900 capitalize">{job.status.replace(/_/g, ' ')}</p>
            <span className="ml-auto text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full bg-slate-100 text-slate-500">{t('service.eng_jd_read_only', 'Read-only')}</span>
          </div>
          <p className="text-xs text-slate-500 mt-1">{t('service.eng_jd_wrapped_up', 'This job is wrapped up — the details below are locked.')}</p>
        </div>

        {job.engineer_report ? (
          <div className="bg-white rounded-2xl border border-slate-200 p-4" data-testid="complete-locked-report">
            <EngineerReportView report={job.engineer_report} signoff={sig} />
          </div>
        ) : summaryText ? (
          <div className="bg-white rounded-2xl border border-slate-200 p-4" data-testid="complete-locked-summary">
            <p className="text-[11px] uppercase font-bold tracking-wide text-slate-500 mb-2">{t('service.eng_jd_work_summary', 'Work summary')}</p>
            <p className="text-sm text-slate-800 whitespace-pre-wrap">{summaryText}</p>
          </div>
        ) : null}

        {job.engineer_report ? null : sig && sig.image_data ? (
          <div className="bg-white rounded-2xl border border-slate-200 p-4" data-testid="complete-locked-signature">
            <p className="text-[11px] uppercase font-bold tracking-wide text-slate-500 mb-2">{t('service.eng_jd_customer_signoff', 'Customer sign-off')}</p>
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-2 inline-block">
              <img src={sig.image_data} alt={t('service.eng_jd_customer_signature', 'Customer signature')} className="max-h-28" />
            </div>
            <p className="text-xs text-slate-600 mt-2">
              {t('service.eng_jd_signed_by', 'Signed by')} <span className="font-bold">{sig.signed_by_name || t('service.eng_jd_customer', 'Customer')}</span>
              {sig.signed_by_email ? ` · ${sig.signed_by_email}` : ''}
              {sig.signed_at ? ` · ${new Date(sig.signed_at).toLocaleString()}` : ''}
            </p>
          </div>
        ) : sig && sig.unavailable ? (
          <div className="bg-white rounded-2xl border border-amber-200 p-4 text-xs text-amber-800" data-testid="complete-locked-unavailable">
            Customer unable to sign — {sig.unavailable_reason}
            {sig.signed_at ? ` · ${new Date(sig.signed_at).toLocaleString()}` : ''}
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-slate-200 p-4 text-xs text-slate-500" data-testid="complete-locked-no-signature">
            {t('service.eng_jd_no_signature', 'No customer signature was captured on this job.')}
          </div>
        )}

